import { Component, OnDestroy, OnInit, ViewEncapsulation } from '@angular/core';

import { OlcTedPublicTemplateEditorService } from './../../../services/olc-ted-public-template-editor.service';
import { OlcTedPublicTemplateRefreshService } from './../../../services/olc-ted-public-template-refresh.service';

import * as $ from 'jquery';
import './../../../assets/scripts/jstree.min.js';
import { uniqueID } from '../../../utils/olc-ted-public-utilities.utils';
import { JsTreeNodeType, Shape } from '../../../models/shape';
import { OlcTedPublicOpenTemplateService } from '../../../services/olc-ted-public-open-template.service';
import { CanvasState } from '../../../models/canvas-state';
import { Subscription } from 'rxjs';

@Component({
  selector: 'app-TED-template-tree',
  templateUrl: './TED-template-tree.component.html',
  styleUrls: ['./TED-template-tree.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class TEDTemplateTreeComponent implements OnInit, OnDestroy {
  canvasState: CanvasState = null;

  subscriptions: Subscription[] = [];

  constructor(
    private templateEditorService: OlcTedPublicTemplateEditorService,
    private templateRefreshService: OlcTedPublicTemplateRefreshService,
    private openTemplateService: OlcTedPublicOpenTemplateService
  ) {}

  ngOnInit() {
    this.subscriptions.push(
      this.templateEditorService.canvasState$.subscribe((canvasState) => {
        this.canvasState = canvasState;
      })
    );

    this.init();
  }

  init() {
    const that = this;

    // @ts-ignore
    $.jstree.plugins.noclose = function () {
      this.close_node = $.noop;
    };

    //jsTree instance
    $('#objectTree')
      // @ts-ignore
      .jstree({
        core: {
          data: [
            {
              id: 'S1',
              parent: '#',
              text: 'Section1',
              type: JsTreeNodeType.SectionOpened,
              data: {
                section: 1,
                sectionName: 'Section1',
              },
            },
            {
              id: 'S1P1',
              parent: 'S1',
              text: 'Page 1',
              type: JsTreeNodeType.Page,
              data: {
                section: 1,
                sectionName: 'Section1',
                page: 1,
              },
            },
          ],
          themes: {
            dots: false,
            //					"variant" : "large"
          },
          dblclick_toggle: false,
          check_callback: function (op, node) {
            // console.log(op);
            // prevent move and copy on page and section
            if (
              (op === 'move_node' || op === 'copy_node') &&
              node.type &&
              (node.type == JsTreeNodeType.Root ||
                node.type == JsTreeNodeType.Section ||
                node.type == JsTreeNodeType.SectionOpened ||
                node.type == JsTreeNodeType.Page)
            ) {
              return false;
            }
            return true;
          },
          multiple: false,
        },
        types: {
          default: {
            icons: false,
          },
          section: {
            icon: '/assets/img/material/ted-tree-section.svg',
            valid_children: [JsTreeNodeType.Page],
          },
          'section-open': {
            icon: '/assets/img/material/ted-tree-section.svg',
            valid_children: [JsTreeNodeType.Page],
          },
          page: {
            icon: '/assets/img/material/ted-tree-page.svg',
            valid_children: ['object', JsTreeNodeType.Image, JsTreeNodeType.Text],
          },
          image: {
            icon: '/assets/img/material/ted-tree-image.svg',
            valid_children: [''],
          },
          text: {
            icon: '/assets/img/material/ted-tree-text.svg',
            valid_children: [''],
          },
          object: {
            icon: 'bi bi-box',
            valid_children: [''],
          },
          '#': {
            valid_children: [JsTreeNodeType.Section],
          },
        },
        plugins: ['types', 'dnd'],
      })
      .on('refresh.jstree', function () {
        const updatedCanvasState = { ...that.canvasState };
        that.templateRefreshService.refreshBackground(updatedCanvasState);
      })
      .on('copy_node.jstree', function (e, data) {
        const updatedCanvasState = { ...that.canvasState };

        // display parent page
        var par = that.templateEditorService.tree.get_node(data.parent);
        that.templateEditorService.currentSection = par.data.section;
        that.templateEditorService.currentDisplayPage = par.data.page;
        // set object to parent page and section
        // need to search as drag and drop might happen prior to select
        for (let i = updatedCanvasState.shapes.length - 1; i >= 0; i--) {
          if (updatedCanvasState.shapes[i].id == data.original.id) {
            // duplicate object
            updatedCanvasState.shapes.push(
              new Shape({
                id: uniqueID(),
                title: updatedCanvasState.shapes[i].title, // title
                x: updatedCanvasState.shapes[i].x, // X
                y: updatedCanvasState.shapes[i].y, // Y
                w: updatedCanvasState.shapes[i].w, // W
                h: updatedCanvasState.shapes[i].h, // H
                page: par.data.page,
                section: par.data.section,
                type: updatedCanvasState.shapes[i].type,
                texts: JSON.parse(JSON.stringify(updatedCanvasState.shapes[i].texts)), // deep copy
                images: JSON.parse(JSON.stringify(updatedCanvasState.shapes[i].images)), // deep copy
                class: updatedCanvasState.shapes[i].class,
                rotate: updatedCanvasState.shapes[i].rotate,
              })
            );
            // Select the newly added text
            updatedCanvasState.selection = updatedCanvasState.shapes[updatedCanvasState.shapes.length - 1];
            break;
          }
        }

        that.templateEditorService.tree.set_id(data.node, updatedCanvasState.selection.id); // set id of the drop object to the newly created
        that.templateEditorService.tree.rename_node(data.node, updatedCanvasState.selection.title); // set text to the new title (copy of)
        that.templateEditorService.tree.deselect_all();
        that.templateEditorService.tree.select_node(data.node); // then select it

        that.templateRefreshService.refreshBackground(updatedCanvasState);
      })
      .on('move_node.jstree', function (e, data) {
        const updatedCanvasState = { ...that.canvasState };

        var par = that.templateEditorService.tree.get_node(data.parent);
        // display parent page
        that.templateEditorService.currentSection = par.data.section;
        that.templateEditorService.currentDisplayPage = par.data.page;
        // set object to parent page and section
        // need to search as drag and drop might happen prior to select
        for (let i = updatedCanvasState.shapes.length - 1; i >= 0; i--) {
          if (updatedCanvasState.shapes[i].id == data.node.id) {
            updatedCanvasState.shapes[i].section = par.data.section;
            updatedCanvasState.shapes[i].page = par.data.page;
            break;
          }
        }

        that.templateRefreshService.refreshBackground(updatedCanvasState);
      })
      .on('select_node.jstree', function (e, data) {
        const updatedCanvasState = { ...that.canvasState };

        switch (data.node.type) {
          case JsTreeNodeType.Text:
          case JsTreeNodeType.Image:
            that.templateEditorService.isPageSelected = true;
            that.templateEditorService.isSectionSelected = false;

            if (updatedCanvasState.selection && updatedCanvasState.selection.id == data.node.id) {
              // Already selected by the mouse
            } else {
              for (let i = updatedCanvasState.shapes.length - 1; i >= 0; i--) {
                if (updatedCanvasState.shapes[i].id == data.node.id) {
                  updatedCanvasState.selection = updatedCanvasState.shapes[i];
                  // get the parent
                  var parent = that.templateEditorService.tree.get_node(data.node.parent);

                  if (
                    that.templateEditorService.currentSection == parent.data.section &&
                    that.templateEditorService.currentDisplayPage == parent.data.page
                  ) {
                    // we are already on the page of the selected object
                  } else {
                    // change page and/or section then force a refresh
                    that.templateEditorService.currentSection = parent.data.section;
                    that.templateEditorService.currentDisplayPage = parent.data.page;
                    that.templateRefreshService.refreshBackground(updatedCanvasState);
                  }

                  that.templateEditorService.setCanvasState(updatedCanvasState, true);
                  return;
                }
              }
            }

            that.templateEditorService.setCanvasState(updatedCanvasState);
            break;
          case JsTreeNodeType.Page:
            updatedCanvasState.selection = null;
            that.templateEditorService.isPageSelected = true;
            that.templateEditorService.isSectionSelected = false;

            if (
              that.templateEditorService.currentSection == data.node.data.section &&
              that.templateEditorService.currentDisplayPage == data.node.data.page
            ) {
              // we are already on the page of the selected object
            } else {
              // change page and/or section then force a refresh
              that.templateEditorService.currentSection = data.node.data.section;
              that.templateEditorService.currentDisplayPage = data.node.data.page;
              that.templateRefreshService.refreshBackground(updatedCanvasState);
            }

            that.templateEditorService.setCanvasState(updatedCanvasState, true);
            break;
          case JsTreeNodeType.Section:
          case JsTreeNodeType.SectionOpened:
            updatedCanvasState.selection = null;
            that.templateEditorService.isPageSelected = false;
            that.templateEditorService.isSectionSelected = true;

            if (
              that.templateEditorService.currentSection == data.node.data.section &&
              that.templateEditorService.currentDisplayPage == 0
            ) {
              // we are already on the first page and section of the selected object
            } else {
              // change page and/or section then force a refresh
              that.templateEditorService.currentSection = data.node.data.section;
              that.templateEditorService.currentDisplayPage = 0; // go to the first page
              that.templateRefreshService.refreshBackground(updatedCanvasState);
            }

            that.templateEditorService.setCanvasState(updatedCanvasState, true);
            break;
        }
      })
      .on('dblclick.jstree', function (e) {
        // get the node that triggered the event
        e.preventDefault();
        // @ts-ignore
        var instance = $.jstree.reference(this),
          node = instance?.get_node(e.target);
        switch (node.type) {
          case JsTreeNodeType.Section:
          case JsTreeNodeType.SectionOpened:
            const selectedSectionIndex = that.openTemplateService
              .getOrderedSections(that.canvasState.sections)
              .findIndex((s) => s.id === node.data.sectionId);

            if (selectedSectionIndex !== -1 && selectedSectionIndex !== that.templateEditorService.currentSection) {
              that.templateEditorService.currentSection = selectedSectionIndex;
              that.templateEditorService.currentDisplayPage = 0;
            }

            that.templateEditorService.onEditBackground.next();
            break;

          case JsTreeNodeType.Page:
            if (node.data.section) {
              that.templateEditorService.currentSection = node.data.section;
            }

            that.templateEditorService.onEditBodyText.next();
            break;

          case JsTreeNodeType.Text:
            that.templateEditorService.onEditText.next();
            break;
          case JsTreeNodeType.Image:
            that.templateEditorService.onEditImage.next();
            break;
          default:
            break;
        }
      });

    // Change the icon depending on folder status (open / closed)
    $('#objectTree').on('open_node.jstree', function (event, data) {
      if (data.node.type == JsTreeNodeType.Section || data.node.type == JsTreeNodeType.SectionOpened)
        data.instance.set_type(data.node, JsTreeNodeType.SectionOpened);
    });

    $('#objectTree').on('close_node.jstree', function (event, data) {
      if (data.node.type == JsTreeNodeType.Section || data.node.type == JsTreeNodeType.SectionOpened)
        data.instance.set_type(data.node, JsTreeNodeType.Section);
    });

    // @ts-ignore
    that.templateEditorService.tree = $('#objectTree').jstree(true);
  }

  ngOnDestroy(): void {
    this.subscriptions.forEach((s) => s.unsubscribe());

    $('#objectTree')
      .off('refresh.jstree')
      .off('copy_node.jstree')
      .off('move_node.jstree')
      .off('select_node.jstree')
      .off('dblclick.jstree')
      .off('open_node.jstree')
      .off('close_node.jstree');
  }
}
