import { Component, OnInit, Input, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { Tab } from 'shared-code-lib';
import { TemplateVersion } from '../../models/template';

@Component({
  selector: 'app-version-properties-form',
  templateUrl: './version-properties-form.component.html',
  styleUrls: ['./version-properties-form.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class VersionPropertiesFormComponent implements OnInit {
  @Input() version: TemplateVersion;

  activeTab = 'general';
  tabs = new Array<Tab>();

  constructor(private translateService: TranslateService) {}

  ngOnInit() {
    this.tabs.push(new Tab('general', this.translateService.instant('admin-olc-templates.general')));

    if (this.version.approval) {
      this.tabs.push(new Tab('approval', this.translateService.instant('admin-olc-templates.approval')));
    }
  }

  activateTab = (tab) => {
    this.activeTab = tab;
  };
}
