import { Injectable } from '@angular/core';
import { OlcTedPublicTemplateEditorService } from './olc-ted-public-template-editor.service';

import { CanvasState } from '../models/canvas-state';
import { ITEDPayloadState, TEDItem } from '../models/ted-state';
import { JsTreeNodeType, Shape } from '../models/shape';

@Injectable({
  providedIn: 'root',
})
export class OlcTedPublicPayloadsService {
  constructor(private templateEditorService: OlcTedPublicTemplateEditorService) {}

  prepareJsonPayload(state: CanvasState): ITEDPayloadState {
    this.templateEditorService.payload = { items: [], sections: JSON.parse(JSON.stringify(state.sections)) };

    let shape: Shape, shapeId: string;

    const treeElements = this.templateEditorService.tree.get_json('#', { flat: true });

    for (let i = 0; i < treeElements.length; i++) {
      if (treeElements[i].type != JsTreeNodeType.Text && treeElements[i].type != JsTreeNodeType.Image) continue;

      shapeId = treeElements[i].id;
      shape = state.shapes.find((obj) => obj.id == shapeId); // find matching shape
      if (!shape) continue;

      this.addItemToPayload(shape);
    }

    if (this.templateEditorService.saveToHistory) {
      this.templateEditorService.undoIndex = this.templateEditorService.undoIndex + 1;

      this.templateEditorService.undo.splice(
        this.templateEditorService.undoIndex,
        0,
        this.templateEditorService.payload
      );
    } else {
      this.templateEditorService.saveToHistory = true;
    }

    return {
      sections: this.templateEditorService.payload.sections,
      items: this.templateEditorService.payload.items,
    };
  }

  addItemToPayload(shape: Shape) {
    const item = {
      id: shape.id,
      x: shape.x,
      y: shape.y,
      w: shape.w,
      h: shape.h,
      rotate: shape.rotate,
      page: shape.page,
      section: shape.section || 0,
      class: shape.class,
      texts: [],
      images: [],
      title: shape.title,
      type: shape.type,
    };

    for (let j = 0; j < shape.texts.length; j++) {
      item.texts.push({
        group: shape.texts[j].group,
        condition: shape.texts[j].condition,
        from: shape.texts[j].from,
        to: shape.texts[j].to,
        text: shape.texts[j].text,
      });
    }

    for (let j = 0; j < shape.images.length; j++) {
      item.images.push({
        group: shape.images[j].group,
        condition: shape.images[j].condition,
        from: shape.images[j].from,
        to: shape.images[j].to,
        image: shape.images[j].image,
        imageName: shape.images[j].imageName,
        type: shape.images[j].type,
      });
    }

    this.templateEditorService.payload.items.push(item);
  }
}
