import { AfterViewInit, Component, OnDestroy, OnInit, ViewEncapsulation } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Subscription } from 'rxjs';
import { OlcTedPublicTemplateEditorService } from './services/olc-ted-public-template-editor.service';
import { OlcTedPublicOpenTemplateService } from './services/olc-ted-public-open-template.service';
import { CanvasState } from './models/canvas-state';
import { UserStateService } from './../../../../blocks/services/user-state.service';

import './assets/scripts/bootstrap.5.1.0.min.js';

@Component({
  selector: 'app-template-editor',
  templateUrl: './template-editor.component.html',
  styleUrls: ['./template-editor.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class TemplateEditorComponent implements OnInit, AfterViewInit, OnDestroy {
  keepUndoRedoStateHistory = false;
  canvasState: CanvasState = null;
  subscriptions: Subscription[] = [];

  constructor(
    private userStateService: UserStateService,
    private templateEditorService: OlcTedPublicTemplateEditorService,
    private openTemplateService: OlcTedPublicOpenTemplateService,
    private activatedRoute: ActivatedRoute,
    private router: Router
  ) {}

  ngOnInit() {
    this.templateEditorService.conditionalContentSelections = [];
    this.templateEditorService.setCurrentTemplate(null);

    this.activatedRoute.paramMap.subscribe((params) => {
      this.templateEditorService.templateID = params.get('templateId');
    });

    this.activatedRoute.queryParamMap.subscribe((params) => {
      this.templateEditorService.versionId = params.get('versionId');
    });

    this.templateEditorService.currentSection = this.router.getCurrentNavigation()?.extras?.state?.currentSection || 0;
    this.templateEditorService.currentDisplayPage = this.router.getCurrentNavigation()?.extras?.state?.currentPage || 0;
    this.templateEditorService.isPageSelected =
      this.router.getCurrentNavigation()?.extras?.state?.isPageSelected || true;
    this.templateEditorService.isSectionSelected =
      this.router.getCurrentNavigation()?.extras?.state?.isSectionSelected || false;

    this.keepUndoRedoStateHistory = !!this.router.getCurrentNavigation()?.extras?.state?.keepUndoRedoStateHistory;

    this.subscriptions.push(
      this.templateEditorService.canvasState$.subscribe((canvasState) => (this.canvasState = canvasState))
    );

    this.setDefaultMeasurementUnit();
  }

  ngAfterViewInit(): void {
    if (!this.keepUndoRedoStateHistory) {
      this.templateEditorService.resetUndoState();
    } else {
      this.templateEditorService.saveToHistory = false;
    }

    this.init();
  }

  init() {
    this.openTemplateService.openTemplate(
      this.templateEditorService.templateID,
      this.templateEditorService.versionId,
      this.canvasState
    );
  }

  setDefaultMeasurementUnit() {
    const user = this.userStateService.user;
    if (!user) return;

    this.templateEditorService.setDefaultUnit(user.tedOptions.measurementSettings.unit);
  }

  ngOnDestroy(): void {
    this.subscriptions.forEach((s) => s.unsubscribe());
  }
}
