import { Component, OnDestroy, OnInit } from '@angular/core';
import { OlcTedPublicTemplateEditorService } from '../../services/olc-ted-public-template-editor.service';
import { OlcTedPublicTemplateRefreshService } from '../../services/olc-ted-public-template-refresh.service';
import { ITemplate, ITemplateCondition, VersionStatus } from '../../../../../../views/admin-olc/models/template';
import { Subscription } from 'rxjs';
import { Router } from '@angular/router';
import { FieldDefinition, IFieldOptions } from '../../../../../../../../../../Bamba.Shared/src/models/field-definition';
import { MetaDataType } from '../../../../../../../../../../Bamba.Shared/src/models/metadata-definition';
import { FixedDataSource } from '../../../../../../../../../../Bamba.Shared/src/models/fixed-datasource';
import { UserStateService } from '../../../../../../blocks/services/user-state.service';
import { TranslateService } from '@ngx-translate/core';
import { CanvasState } from '../../models/canvas-state';
import { ConditionalGroup } from '../../models/ted-state';

type OpenedSection = 'none' | 'template' | 'conditions' | 'conditional-contents' | 'versions';

@Component({
  selector: 'app-TED-sidebar',
  templateUrl: './TED-sidebar.component.html',
  styleUrls: ['./TED-sidebar.component.scss'],
})
export class TEDSidebarComponent implements OnInit, OnDestroy {
  currentTemplate: ITemplate;
  currentVersionId: string;

  openedAccordionSection: OpenedSection = 'template';
  conditionalGroups: ConditionalGroup[] = [];
  previewDateField: FieldDefinition = new FieldDefinition();
  previewDate: string;

  versionStatusIcons = {
    [VersionStatus.Draft]: 'note-edit-outline.svg',
    [VersionStatus.PendingApproval]: 'file-certificate-outline.svg',
    [VersionStatus.Approved]: 'file-check-outline.svg',
    [VersionStatus.Rejected]: 'file-remove-outline.svg',
    [VersionStatus.PendingProduction]: 'printer-pos-stop-outline.svg',
    [VersionStatus.InProduction]: 'printer-pos-check-outline.svg',
    [VersionStatus.WasInProduction]: 'printer-pos-remove-outline.svg',
  };

  canvasState: CanvasState = null;

  subscriptions: Subscription[] = [];

  constructor(
    public templateEditorService: OlcTedPublicTemplateEditorService,
    private templateRefreshService: OlcTedPublicTemplateRefreshService,
    private router: Router,
    private userService: UserStateService,
    private translate: TranslateService
  ) {}

  ngOnInit() {
    this.subscriptions.push(
      this.templateEditorService.template$.subscribe((template) => {
        this.currentTemplate = template;
        this.currentVersionId = this.templateEditorService.versionId;

        if (this.currentTemplate) {
          this.initConditionalContents();
          this.initConditions();
        } else {
          this.templateEditorService.conditionalContentSelections = [];
        }
      }),
      this.templateEditorService.canvasState$.subscribe((canvasState) => (this.canvasState = canvasState))
    );

    this.openedAccordionSection =
      this.router.getCurrentNavigation()?.extras?.state?.openedAccordionSection || 'template';

    this.previewDateField = new FieldDefinition({
      type: MetaDataType.Date,
      label: '',
      placeholder: this.translate.instant('admin-olc-templates.preview-date-placeholder'),
      required: false,
      fireChangeEventIfSameValue: false,
      dateFieldExpectedFormat: this.userService.getLocalDateFormat(),
      id: 'previewDateInp',
    });
  }

  initConditionalContents() {
    this.conditionalGroups = [];

    this.templateEditorService.conditionalContentSelections = [];

    this.currentTemplate.conditionalContents.forEach((conditionalContent) => {
      const options: IFieldOptions[] = conditionalContent.groupOptions.map((groupOption) => {
        return {
          name: groupOption.name,
          value: groupOption.name,
        };
      });

      const listField = new FieldDefinition({
        type: MetaDataType.List,
        label: '',
        required: false,
        datasource: new FixedDataSource(options),
        fireChangeEventIfSameValue: false,
      });

      this.conditionalGroups.push({
        title: conditionalContent.group,
        field: listField,
        value: options[0].value,
      });

      this.templateEditorService.conditionalContentSelections.push({
        groupName: conditionalContent.group,
        value: options[0].value,
      });
    });
  }

  onConditionGroupValueChanged(groupName: string, selectedValue: string) {
    if (!this.templateEditorService.conditionalContentSelections) return;

    this.templateEditorService.conditionalContentSelections.find(
      (selection) => selection.groupName === groupName
    ).value = selectedValue;

    this.templateRefreshService.refreshBackground(this.canvasState);
  }

  handlePreviewDateChange() {
    this.removeSelectionAndRefreshBackground();
  }

  templateVersionChanged(versionId: string) {
    if (this.templateEditorService.versionId === versionId) return;

    this.templateEditorService.saveToHistory = false;

    this.router.navigate([this.router.url.split('?')[0]], {
      queryParams: { versionId },
      state: {
        openedAccordionSection: 'versions',
        currentSection: 0,
        currentPage: 0,
        isPageSelected: true,
        isSectionSelected: false,
      },
    });
  }

  toggleSection(section: OpenedSection) {
    this.openedAccordionSection = this.openedAccordionSection !== section ? section : 'none';
  }

  initConditions() {
    this.templateEditorService.templateConditions = [];

    // amend global condition and variable with the one in options
    // also duplicate the WP/ACF structure to harmonize structures
    for (let conditionGroup of this.currentTemplate.conditions) {
      for (let field of conditionGroup.fields) {
        this.templateEditorService.templateConditions.push({
          id: field.name,
          title: field.name,
          group: conditionGroup.group ? conditionGroup.group : false, //radio button
          connectScript: field.connect_script,
        });
      }
    }
  }

  removeSelectionAndRefreshBackground = () => {
    const updatedCanvasState = { ...this.canvasState };
    updatedCanvasState.selection = null;
    this.templateRefreshService.refreshBackground(updatedCanvasState);
  };

  ngOnDestroy(): void {
    this.subscriptions.map((s) => s.unsubscribe());
  }
}
