import { fabric } from 'fabric';
import { UserAction, ItemCorner } from './../models';

type FixedPointType = 'topLeft' | 'topRight' | 'bottomLeft' | 'bottomRight';
type ItemDimension = 'width' | 'height';

const getDistanceBetweenTwoPoints = (point1: fabric.Point, point2: fabric.Point) => {
  return Math.sqrt(Math.pow(point2.x - point1.x, 2) + Math.pow(point2.y - point1.y, 2));
};

const degreesToRadians = (degrees: number) => {
  return degrees * (Math.PI / 180);
};

const getTopLeftPoint = (activeElement: fabric.Object) => {
  return activeElement.getCoords()[0];
};

const getTopRightPoint = (activeElement: fabric.Object) => {
  return activeElement.getCoords()[1];
};

const getBottomRightPoint = (activeElement: fabric.Object) => {
  return activeElement.getCoords()[2];
};

const getBottomLeftPoint = (activeElement: fabric.Object) => {
  return activeElement.getCoords()[3];
};

const CornersOrigins = {
  topLeft: { originX: 'left', originY: 'top' },
  topRight: { originX: 'right', originY: 'top' },
  bottomLeft: { originX: 'left', originY: 'bottom' },
  bottomRight: { originX: 'right', originY: 'bottom' },
};

const setDimension = (
  activeElement: fabric.Object,
  fixedPoint: fabric.Point,
  fixedPointType: FixedPointType,
  intersectionPoint: fabric.Point,
  triangleAngleCosOrSin: number,
  dimensionToSet: ItemDimension
) => {
  if (triangleAngleCosOrSin === 0) return;

  const distance = getDistanceBetweenTwoPoints(fixedPoint, intersectionPoint);
  const newDimension = distance / triangleAngleCosOrSin;

  if (dimensionToSet === 'width') {
    activeElement.set({ width: newDimension, scaleX: 1 });
  } else if (dimensionToSet === 'height') {
    activeElement.set({ height: newDimension, scaleY: 1 });
  }

  activeElement.setPositionByOrigin(
    fixedPoint,
    CornersOrigins[fixedPointType].originX,
    CornersOrigins[fixedPointType].originY
  );
};

const stopScalingInXAndYDirections = (
  activeElement: fabric.Object,
  condition: boolean,
  deltaDiameter: number,
  propToUpdate: { prop: 'top' | 'left'; value: number }
) => {
  if (condition) {
    activeElement.lockScalingX = true;
    activeElement.lockScalingY = true;

    const deltaDiameterAbs = Math.abs(deltaDiameter);
    const deltaWidthAndHeight = deltaDiameterAbs * Math.cos(degreesToRadians(45));

    const newWidth = activeElement.getScaledWidth() - deltaWidthAndHeight;
    const newHeight = activeElement.getScaledHeight() - deltaWidthAndHeight;

    activeElement.set({
      [propToUpdate.prop]: propToUpdate.value,
      width: newWidth,
      scaleX: 1,
      height: newHeight,
      scaleY: 1,
    });
  } else {
    activeElement.lockScalingX = false;
    activeElement.lockScalingY = false;
  }
};

const keepTextOrImageInsideCanvasForScaling = (
  activeElement: fabric.Object,
  action: UserAction,
  corner: ItemCorner,
  canvasWidth: number,
  canvasHeight: number
) => {
  if (![UserAction.ScaleX, UserAction.ScaleY, UserAction.Scale].includes(action)) return;
  if (activeElement.top === undefined || activeElement.left === undefined || activeElement.angle === undefined) return;

  const rotationAngle = activeElement.angle;
  const topLeftPoint = getTopLeftPoint(activeElement);
  const topRightPoint = getTopRightPoint(activeElement);
  const bottomLeftPoint = getBottomLeftPoint(activeElement);
  const bottomRightPoint = getBottomRightPoint(activeElement);

  if (rotationAngle >= 0 && rotationAngle < 90) {
    const thetaInDegrees = 90 - rotationAngle;
    const oppositeToTheta = Math.sin(degreesToRadians(thetaInDegrees)) * activeElement.getScaledWidth();
    const oppositeToRotationAngle = Math.sin(degreesToRadians(rotationAngle)) * activeElement.getScaledHeight();
    const verticalHeightToBottom =
      Math.cos(degreesToRadians(rotationAngle)) * activeElement.getScaledHeight() +
      Math.cos(degreesToRadians(thetaInDegrees)) * activeElement.getScaledWidth();

    if (corner === ItemCorner.MiddleRight) {
      if (activeElement.left + oppositeToTheta > canvasWidth) {
        const intersectionPointWithCanvasRightEdge = new fabric.Point(canvasWidth, topLeftPoint.y);

        setDimension(
          activeElement,
          topLeftPoint,
          'topLeft',
          intersectionPointWithCanvasRightEdge,
          Math.cos(degreesToRadians(rotationAngle)),
          'width'
        );
      }

      if (activeElement.top + verticalHeightToBottom > canvasHeight) {
        const intersectionPointWithCanvasBottomEdge = new fabric.Point(bottomLeftPoint.x, canvasHeight);

        setDimension(
          activeElement,
          bottomLeftPoint,
          'bottomLeft',
          intersectionPointWithCanvasBottomEdge,
          Math.sin(degreesToRadians(rotationAngle)),
          'width'
        );
      }

      return;
    }

    if (corner === ItemCorner.MiddleLeft) {
      if (activeElement.left - oppositeToRotationAngle < 0) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, bottomRightPoint.y);

        setDimension(
          activeElement,
          bottomRightPoint,
          'bottomRight',
          intersectionPointWithCanvasLeftEdge,
          Math.cos(degreesToRadians(rotationAngle)),
          'width'
        );
      }

      if (activeElement.top < 0) {
        const intersectionPointWithCanvasTopEdge = new fabric.Point(topRightPoint.x, 0);

        setDimension(
          activeElement,
          topRightPoint,
          'topRight',
          intersectionPointWithCanvasTopEdge,
          Math.sin(degreesToRadians(rotationAngle)),
          'width'
        );
      }

      return;
    }

    if (corner === ItemCorner.MiddleTop) {
      if (activeElement.top < 0) {
        const intersectionPointWithCanvasTopEdge = new fabric.Point(bottomLeftPoint.x, 0);

        setDimension(
          activeElement,
          bottomLeftPoint,
          'bottomLeft',
          intersectionPointWithCanvasTopEdge,
          Math.cos(degreesToRadians(rotationAngle)),
          'height'
        );
      }

      if (activeElement.left + oppositeToTheta > canvasWidth) {
        const intersectionPointWithCanvasRightEdge = new fabric.Point(canvasWidth, bottomRightPoint.y);

        setDimension(
          activeElement,
          bottomRightPoint,
          'bottomRight',
          intersectionPointWithCanvasRightEdge,
          Math.sin(degreesToRadians(rotationAngle)),
          'height'
        );
      }

      return;
    }

    if (corner === ItemCorner.MiddleBottom) {
      if (activeElement.left - oppositeToRotationAngle < 0) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, topLeftPoint.y);

        setDimension(
          activeElement,
          topLeftPoint,
          'topLeft',
          intersectionPointWithCanvasLeftEdge,
          Math.sin(degreesToRadians(rotationAngle)),
          'height'
        );
      }

      if (activeElement.top + verticalHeightToBottom > canvasHeight) {
        const intersectionPointWithCanvasBottomEdge = new fabric.Point(topRightPoint.x, canvasHeight);

        setDimension(
          activeElement,
          topRightPoint,
          'topRight',
          intersectionPointWithCanvasBottomEdge,
          Math.cos(degreesToRadians(rotationAngle)),
          'height'
        );
      }

      return;
    }

    if (corner === ItemCorner.TopLeft) {
      if (activeElement.left - oppositeToRotationAngle < 0) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, bottomRightPoint.y);

        setDimension(
          activeElement,
          bottomRightPoint,
          'bottomRight',
          intersectionPointWithCanvasLeftEdge,
          Math.cos(degreesToRadians(rotationAngle)),
          'width'
        );
      }

      if (activeElement.left + oppositeToTheta > canvasWidth) {
        const intersectionPointWithCanvasRightEdge = new fabric.Point(canvasWidth, bottomRightPoint.y);

        setDimension(
          activeElement,
          bottomRightPoint,
          'bottomRight',
          intersectionPointWithCanvasRightEdge,
          Math.sin(degreesToRadians(rotationAngle)),
          'height'
        );
      }

      stopScalingInXAndYDirections(activeElement, activeElement.top < 0, activeElement.top, { prop: 'top', value: 0 });

      return;
    }

    if (corner === ItemCorner.TopRight) {
      if (activeElement.top < 0) {
        const intersectionPointWithCanvasTopEdge = new fabric.Point(bottomLeftPoint.x, 0);

        setDimension(
          activeElement,
          bottomLeftPoint,
          'bottomLeft',
          intersectionPointWithCanvasTopEdge,
          Math.cos(degreesToRadians(rotationAngle)),
          'height'
        );
      }

      if (activeElement.top + verticalHeightToBottom > canvasHeight) {
        const intersectionPointWithCanvasBottomEdge = new fabric.Point(bottomLeftPoint.x, canvasHeight);

        setDimension(
          activeElement,
          bottomLeftPoint,
          'bottomLeft',
          intersectionPointWithCanvasBottomEdge,
          Math.sin(degreesToRadians(rotationAngle)),
          'width'
        );
      }

      stopScalingInXAndYDirections(
        activeElement,
        activeElement.left + oppositeToTheta > canvasWidth,
        topRightPoint.x - canvasWidth,
        { prop: 'left', value: canvasWidth - oppositeToTheta }
      );

      return;
    }

    if (corner === ItemCorner.BottomRight) {
      if (activeElement.left + oppositeToTheta > canvasWidth) {
        const intersectionPointWithCanvasRightEdge = new fabric.Point(canvasWidth, topLeftPoint.y);

        setDimension(
          activeElement,
          topLeftPoint,
          'topLeft',
          intersectionPointWithCanvasRightEdge,
          Math.cos(degreesToRadians(rotationAngle)),
          'width'
        );
      }

      if (activeElement.left - oppositeToRotationAngle < 0) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, topLeftPoint.y);

        setDimension(
          activeElement,
          topLeftPoint,
          'topLeft',
          intersectionPointWithCanvasLeftEdge,
          Math.sin(degreesToRadians(rotationAngle)),
          'height'
        );
      }

      stopScalingInXAndYDirections(
        activeElement,
        activeElement.top + verticalHeightToBottom > canvasHeight,
        bottomRightPoint.y - canvasHeight,
        { prop: 'top', value: canvasHeight - verticalHeightToBottom }
      );

      return;
    }

    if (corner === ItemCorner.BottomLeft) {
      if (activeElement.top + verticalHeightToBottom > canvasHeight) {
        const intersectionPointWithCanvasBottomEdge = new fabric.Point(topRightPoint.x, canvasHeight);

        setDimension(
          activeElement,
          topRightPoint,
          'topRight',
          intersectionPointWithCanvasBottomEdge,
          Math.cos(degreesToRadians(rotationAngle)),
          'height'
        );
      }

      if (activeElement.top < 0) {
        const intersectionPointWithCanvasTopEdge = new fabric.Point(topRightPoint.x, 0);

        setDimension(
          activeElement,
          topRightPoint,
          'topRight',
          intersectionPointWithCanvasTopEdge,
          Math.sin(degreesToRadians(rotationAngle)),
          'width'
        );
      }

      stopScalingInXAndYDirections(activeElement, activeElement.left - oppositeToRotationAngle < 0, bottomLeftPoint.x, {
        prop: 'left',
        value: oppositeToRotationAngle,
      });

      return;
    }

    return;
  }

  if (rotationAngle >= 90 && rotationAngle < 180) {
    const thetaInDegrees = rotationAngle - 90;
    const oppositeToTheta = Math.sin(degreesToRadians(thetaInDegrees)) * activeElement.getScaledHeight();
    const neighborToTheta = Math.cos(degreesToRadians(thetaInDegrees)) * activeElement.getScaledHeight();
    const horizontalToLeft =
      neighborToTheta + Math.sin(degreesToRadians(thetaInDegrees)) * activeElement.getScaledWidth();
    const verticalToBottom = Math.cos(degreesToRadians(thetaInDegrees)) * activeElement.getScaledWidth();

    if (corner === ItemCorner.MiddleRight) {
      if (activeElement.left - horizontalToLeft < 0) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, bottomLeftPoint.y);

        setDimension(
          activeElement,
          bottomLeftPoint,
          'bottomLeft',
          intersectionPointWithCanvasLeftEdge,
          Math.cos(degreesToRadians(180 - rotationAngle)),
          'width'
        );
      }

      if (activeElement.top + verticalToBottom > canvasHeight) {
        const intersectionPointWithCanvasBottomEdge = new fabric.Point(topLeftPoint.x, canvasHeight);

        setDimension(
          activeElement,
          topLeftPoint,
          'topLeft',
          intersectionPointWithCanvasBottomEdge,
          Math.sin(degreesToRadians(180 - rotationAngle)),
          'width'
        );
      }

      return;
    }

    if (corner === ItemCorner.MiddleLeft) {
      if (activeElement.top - oppositeToTheta < 0) {
        const intersectionPointWithCanvasTopEdge = new fabric.Point(bottomRightPoint.x, 0);

        setDimension(
          activeElement,
          bottomRightPoint,
          'bottomRight',
          intersectionPointWithCanvasTopEdge,
          Math.sin(degreesToRadians(180 - rotationAngle)),
          'width'
        );
      }

      if (activeElement.left > canvasWidth) {
        const intersectionPointWithCanvasRightEdge = new fabric.Point(canvasWidth, topRightPoint.y);

        setDimension(
          activeElement,
          topRightPoint,
          'topRight',
          intersectionPointWithCanvasRightEdge,
          Math.cos(degreesToRadians(180 - rotationAngle)),
          'width'
        );
      }

      return;
    }

    if (corner === ItemCorner.MiddleTop) {
      if (activeElement.left > canvasWidth) {
        const intersectionPointWithCanvasRightEdge = new fabric.Point(canvasWidth, bottomLeftPoint.y);

        setDimension(
          activeElement,
          bottomLeftPoint,
          'bottomLeft',
          intersectionPointWithCanvasRightEdge,
          Math.sin(degreesToRadians(180 - rotationAngle)),
          'height'
        );
      }

      if (activeElement.top + verticalToBottom > canvasHeight) {
        const intersectionPointWithCanvasBottomEdge = new fabric.Point(bottomRightPoint.x, canvasHeight);

        setDimension(
          activeElement,
          bottomRightPoint,
          'bottomRight',
          intersectionPointWithCanvasBottomEdge,
          Math.cos(degreesToRadians(180 - rotationAngle)),
          'height'
        );
      }

      return;
    }

    if (corner === ItemCorner.MiddleBottom) {
      if (activeElement.top - oppositeToTheta < 0) {
        const intersectionPointWithCanvasTopEdge = new fabric.Point(topLeftPoint.x, 0);

        setDimension(
          activeElement,
          topLeftPoint,
          'topLeft',
          intersectionPointWithCanvasTopEdge,
          Math.cos(degreesToRadians(180 - rotationAngle)),
          'height'
        );
      }

      if (activeElement.left - horizontalToLeft < 0) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, topRightPoint.y);

        setDimension(
          activeElement,
          topRightPoint,
          'topRight',
          intersectionPointWithCanvasLeftEdge,
          Math.sin(degreesToRadians(180 - rotationAngle)),
          'height'
        );
      }

      return;
    }

    if (corner === ItemCorner.TopLeft) {
      if (activeElement.top - oppositeToTheta < 0) {
        const intersectionPointWithCanvasTopEdge = new fabric.Point(bottomRightPoint.x, 0);

        setDimension(
          activeElement,
          bottomRightPoint,
          'bottomRight',
          intersectionPointWithCanvasTopEdge,
          Math.sin(degreesToRadians(180 - rotationAngle)),
          'width'
        );
      }

      if (activeElement.top + verticalToBottom > canvasHeight) {
        const intersectionPointWithCanvasBottomEdge = new fabric.Point(bottomRightPoint.x, canvasHeight);

        setDimension(
          activeElement,
          bottomRightPoint,
          'bottomRight',
          intersectionPointWithCanvasBottomEdge,
          Math.cos(degreesToRadians(180 - rotationAngle)),
          'height'
        );
      }

      stopScalingInXAndYDirections(activeElement, activeElement.left > canvasWidth, topLeftPoint.x - canvasWidth, {
        prop: 'left',
        value: canvasWidth,
      });

      return;
    }

    if (corner === ItemCorner.TopRight) {
      if (activeElement.left - horizontalToLeft < 0) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, bottomLeftPoint.y);

        setDimension(
          activeElement,
          bottomLeftPoint,
          'bottomLeft',
          intersectionPointWithCanvasLeftEdge,
          Math.cos(degreesToRadians(180 - rotationAngle)),
          'width'
        );
      }

      if (activeElement.left > canvasWidth) {
        const intersectionPointWithCanvasRightEdge = new fabric.Point(canvasWidth, bottomLeftPoint.y);

        setDimension(
          activeElement,
          bottomLeftPoint,
          'bottomLeft',
          intersectionPointWithCanvasRightEdge,
          Math.sin(degreesToRadians(180 - rotationAngle)),
          'height'
        );
      }

      stopScalingInXAndYDirections(
        activeElement,
        activeElement.top + verticalToBottom > canvasHeight,
        topRightPoint.y - canvasHeight,
        { prop: 'top', value: canvasHeight - verticalToBottom }
      );

      return;
    }

    if (corner === ItemCorner.BottomRight) {
      if (activeElement.top + verticalToBottom > canvasHeight) {
        const intersectionPointWithCanvasBottomEdge = new fabric.Point(topLeftPoint.x, canvasHeight);

        setDimension(
          activeElement,
          topLeftPoint,
          'topLeft',
          intersectionPointWithCanvasBottomEdge,
          Math.sin(degreesToRadians(180 - rotationAngle)),
          'width'
        );
      }

      if (activeElement.top - oppositeToTheta < 0) {
        const intersectionPointWithCanvasTopEdge = new fabric.Point(topLeftPoint.x, 0);

        setDimension(
          activeElement,
          topLeftPoint,
          'topLeft',
          intersectionPointWithCanvasTopEdge,
          Math.cos(degreesToRadians(180 - rotationAngle)),
          'height'
        );
      }

      stopScalingInXAndYDirections(activeElement, activeElement.left - horizontalToLeft < 0, bottomRightPoint.x, {
        prop: 'left',
        value: horizontalToLeft,
      });

      return;
    }

    if (corner === ItemCorner.BottomLeft) {
      if (activeElement.left - horizontalToLeft < 0) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, topRightPoint.y);

        setDimension(
          activeElement,
          topRightPoint,
          'topRight',
          intersectionPointWithCanvasLeftEdge,
          Math.sin(degreesToRadians(180 - rotationAngle)),
          'height'
        );
      }

      if (activeElement.left > canvasWidth) {
        const intersectionPointWithCanvasRightEdge = new fabric.Point(canvasWidth, topRightPoint.y);

        setDimension(
          activeElement,
          topRightPoint,
          'topRight',
          intersectionPointWithCanvasRightEdge,
          Math.cos(degreesToRadians(180 - rotationAngle)),
          'width'
        );
      }

      stopScalingInXAndYDirections(activeElement, activeElement.top - oppositeToTheta < 0, bottomLeftPoint.y, {
        prop: 'top',
        value: oppositeToTheta,
      });

      return;
    }

    return;
  }

  if (rotationAngle >= 180 && rotationAngle < 270) {
    const horizontalToRight = Math.sin(degreesToRadians(rotationAngle - 180)) * activeElement.getScaledHeight();
    const horizontalToLeft = Math.sin(degreesToRadians(270 - rotationAngle)) * activeElement.getScaledWidth();
    const verticalToTop =
      Math.cos(degreesToRadians(270 - rotationAngle)) * activeElement.getScaledWidth() +
      Math.sin(degreesToRadians(270 - rotationAngle)) * activeElement.getScaledHeight();

    if (corner === ItemCorner.MiddleRight) {
      if (activeElement.left - horizontalToLeft < 0) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, topLeftPoint.y);

        setDimension(
          activeElement,
          topLeftPoint,
          'topLeft',
          intersectionPointWithCanvasLeftEdge,
          Math.sin(degreesToRadians(270 - rotationAngle)),
          'width'
        );
      }

      if (activeElement.top - verticalToTop < 0) {
        const intersectionPointWithCanvasTopEdge = new fabric.Point(bottomLeftPoint.x, 0);

        setDimension(
          activeElement,
          bottomLeftPoint,
          'bottomLeft',
          intersectionPointWithCanvasTopEdge,
          Math.cos(degreesToRadians(270 - rotationAngle)),
          'width'
        );
      }

      return;
    }

    if (corner === ItemCorner.MiddleLeft) {
      if (activeElement.left + horizontalToRight > canvasWidth) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(canvasWidth, bottomRightPoint.y);

        setDimension(
          activeElement,
          bottomRightPoint,
          'bottomRight',
          intersectionPointWithCanvasLeftEdge,
          Math.sin(degreesToRadians(270 - rotationAngle)),
          'width'
        );
      }

      if (activeElement.top > canvasHeight) {
        const intersectionPointWithCanvasBottomEdge = new fabric.Point(topRightPoint.x, canvasHeight);

        setDimension(
          activeElement,
          topRightPoint,
          'topRight',
          intersectionPointWithCanvasBottomEdge,
          Math.cos(degreesToRadians(270 - rotationAngle)),
          'width'
        );
      }

      return;
    }

    if (corner === ItemCorner.MiddleTop) {
      if (activeElement.top > canvasHeight) {
        const intersectionPointWithCanvasBottomEdge = new fabric.Point(bottomLeftPoint.x, canvasHeight);

        setDimension(
          activeElement,
          bottomLeftPoint,
          'bottomLeft',
          intersectionPointWithCanvasBottomEdge,
          Math.sin(degreesToRadians(270 - rotationAngle)),
          'height'
        );
      }

      if (activeElement.left - horizontalToLeft < 0) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, bottomRightPoint.y);

        setDimension(
          activeElement,
          bottomRightPoint,
          'bottomRight',
          intersectionPointWithCanvasLeftEdge,
          Math.cos(degreesToRadians(270 - rotationAngle)),
          'height'
        );
      }

      return;
    }

    if (corner === ItemCorner.MiddleBottom) {
      if (activeElement.top - verticalToTop < 0) {
        const intersectionPointWithCanvasTopEdge = new fabric.Point(topRightPoint.x, 0);

        setDimension(
          activeElement,
          topRightPoint,
          'topRight',
          intersectionPointWithCanvasTopEdge,
          Math.sin(degreesToRadians(270 - rotationAngle)),
          'height'
        );
      }

      if (activeElement.left + horizontalToRight > canvasWidth) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(canvasWidth, topLeftPoint.y);

        setDimension(
          activeElement,
          topLeftPoint,
          'topLeft',
          intersectionPointWithCanvasLeftEdge,
          Math.cos(degreesToRadians(270 - rotationAngle)),
          'height'
        );
      }

      return;
    }

    if (corner === ItemCorner.TopLeft) {
      if (activeElement.left + horizontalToRight > canvasWidth) {
        const intersectionPointWithCanvasRightEdge = new fabric.Point(canvasWidth, bottomRightPoint.y);

        setDimension(
          activeElement,
          bottomRightPoint,
          'bottomRight',
          intersectionPointWithCanvasRightEdge,
          Math.sin(degreesToRadians(270 - rotationAngle)),
          'width'
        );
      }

      if (activeElement.left - horizontalToLeft < 0) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, bottomRightPoint.y);

        setDimension(
          activeElement,
          bottomRightPoint,
          'bottomRight',
          intersectionPointWithCanvasLeftEdge,
          Math.cos(degreesToRadians(270 - rotationAngle)),
          'height'
        );
      }

      stopScalingInXAndYDirections(activeElement, activeElement.top > canvasHeight, topLeftPoint.y - canvasHeight, {
        prop: 'top',
        value: canvasHeight,
      });

      return;
    }

    if (corner === ItemCorner.TopRight) {
      if (activeElement.top - verticalToTop < 0) {
        const intersectionPointWithCanvasTopEdge = new fabric.Point(bottomLeftPoint.x, 0);

        setDimension(
          activeElement,
          bottomLeftPoint,
          'bottomLeft',
          intersectionPointWithCanvasTopEdge,
          Math.cos(degreesToRadians(270 - rotationAngle)),
          'width'
        );
      }

      if (activeElement.top > canvasHeight) {
        const intersectionPointWithCanvasBottomEdge = new fabric.Point(bottomLeftPoint.x, canvasHeight);

        setDimension(
          activeElement,
          bottomLeftPoint,
          'bottomLeft',
          intersectionPointWithCanvasBottomEdge,
          Math.sin(degreesToRadians(270 - rotationAngle)),
          'height'
        );
      }

      stopScalingInXAndYDirections(activeElement, activeElement.left - horizontalToLeft < 0, topRightPoint.x, {
        prop: 'left',
        value: horizontalToLeft,
      });

      return;
    }

    if (corner === ItemCorner.BottomRight) {
      if (activeElement.left + horizontalToRight > canvasWidth) {
        const intersectionPointWithCanvasRightEdge = new fabric.Point(canvasWidth, topLeftPoint.y);

        setDimension(
          activeElement,
          topLeftPoint,
          'topLeft',
          intersectionPointWithCanvasRightEdge,
          Math.cos(degreesToRadians(270 - rotationAngle)),
          'height'
        );
      }

      if (activeElement.left - horizontalToLeft < 0) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, topLeftPoint.y);

        setDimension(
          activeElement,
          topLeftPoint,
          'topLeft',
          intersectionPointWithCanvasLeftEdge,
          Math.sin(degreesToRadians(270 - rotationAngle)),
          'width'
        );
      }

      stopScalingInXAndYDirections(activeElement, activeElement.top - verticalToTop < 0, bottomRightPoint.y, {
        prop: 'top',
        value: verticalToTop,
      });

      return;
    }

    if (corner === ItemCorner.BottomLeft) {
      if (activeElement.top - verticalToTop < 0) {
        const intersectionPointWithCanvasTopEdge = new fabric.Point(topRightPoint.x, 0);

        setDimension(
          activeElement,
          topRightPoint,
          'topRight',
          intersectionPointWithCanvasTopEdge,
          Math.sin(degreesToRadians(270 - rotationAngle)),
          'height'
        );
      }

      if (activeElement.top > canvasHeight) {
        const intersectionPointWithCanvasBottomEdge = new fabric.Point(topRightPoint.x, canvasHeight);

        setDimension(
          activeElement,
          topRightPoint,
          'topRight',
          intersectionPointWithCanvasBottomEdge,
          Math.cos(degreesToRadians(270 - rotationAngle)),
          'width'
        );
      }

      stopScalingInXAndYDirections(
        activeElement,
        activeElement.left + horizontalToRight > canvasWidth,
        bottomLeftPoint.x - canvasWidth,
        { prop: 'left', value: canvasWidth - horizontalToRight }
      );

      return;
    }

    return;
  }

  if (rotationAngle >= 270 && rotationAngle <= 360) {
    const horizontalToRight =
      Math.cos(degreesToRadians(360 - rotationAngle)) * activeElement.getScaledWidth() +
      Math.sin(degreesToRadians(360 - rotationAngle)) * activeElement.getScaledHeight();
    const verticalToTop = Math.sin(degreesToRadians(360 - rotationAngle)) * activeElement.getScaledWidth();
    const verticalToBottom = Math.sin(degreesToRadians(rotationAngle - 270)) * activeElement.getScaledHeight();

    if (corner === ItemCorner.MiddleRight) {
      if (activeElement.top - verticalToTop < 0) {
        const intersectionPointWithCanvasTopEdge = new fabric.Point(topLeftPoint.x, 0);

        setDimension(
          activeElement,
          topLeftPoint,
          'topLeft',
          intersectionPointWithCanvasTopEdge,
          Math.sin(degreesToRadians(360 - rotationAngle)),
          'width'
        );
      }

      if (activeElement.left + horizontalToRight > canvasWidth) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(canvasWidth, bottomLeftPoint.y);

        setDimension(
          activeElement,
          bottomLeftPoint,
          'bottomLeft',
          intersectionPointWithCanvasLeftEdge,
          Math.cos(degreesToRadians(360 - rotationAngle)),
          'width'
        );
      }

      return;
    }

    if (corner === ItemCorner.MiddleLeft) {
      if (activeElement.top + verticalToBottom > canvasHeight) {
        const intersectionPointWithCanvasBottomEdge = new fabric.Point(bottomRightPoint.x, canvasHeight);

        setDimension(
          activeElement,
          bottomRightPoint,
          'bottomRight',
          intersectionPointWithCanvasBottomEdge,
          Math.sin(degreesToRadians(360 - rotationAngle)),
          'width'
        );
      }

      if (activeElement.left < 0) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, topRightPoint.y);

        setDimension(
          activeElement,
          topRightPoint,
          'topRight',
          intersectionPointWithCanvasLeftEdge,
          Math.cos(degreesToRadians(360 - rotationAngle)),
          'width'
        );
      }

      return;
    }

    if (corner === ItemCorner.MiddleTop) {
      if (activeElement.left < 0) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, bottomLeftPoint.y);

        setDimension(
          activeElement,
          bottomLeftPoint,
          'bottomLeft',
          intersectionPointWithCanvasLeftEdge,
          Math.sin(degreesToRadians(360 - rotationAngle)),
          'height'
        );
      }

      if (activeElement.top - verticalToTop < 0) {
        const intersectionPointWithCanvasTopEdge = new fabric.Point(bottomRightPoint.x, 0);

        setDimension(
          activeElement,
          bottomRightPoint,
          'bottomRight',
          intersectionPointWithCanvasTopEdge,
          Math.cos(degreesToRadians(360 - rotationAngle)),
          'height'
        );
      }

      return;
    }

    if (corner === ItemCorner.MiddleBottom) {
      if (activeElement.top + verticalToBottom > canvasHeight) {
        const intersectionPointWithCanvasBottomEdge = new fabric.Point(topLeftPoint.x, canvasHeight);

        setDimension(
          activeElement,
          topLeftPoint,
          'topLeft',
          intersectionPointWithCanvasBottomEdge,
          Math.cos(degreesToRadians(360 - rotationAngle)),
          'height'
        );
      }

      if (activeElement.left + horizontalToRight > canvasWidth) {
        const intersectionPointWithCanvasRightEdge = new fabric.Point(canvasWidth, topRightPoint.y);

        setDimension(
          activeElement,
          topRightPoint,
          'topRight',
          intersectionPointWithCanvasRightEdge,
          Math.sin(degreesToRadians(360 - rotationAngle)),
          'height'
        );
      }

      return;
    }

    if (corner === ItemCorner.TopLeft) {
      if (activeElement.top - verticalToTop < 0) {
        const intersectionPointWithCanvasTopEdge = new fabric.Point(bottomRightPoint.x, 0);

        setDimension(
          activeElement,
          bottomRightPoint,
          'bottomRight',
          intersectionPointWithCanvasTopEdge,
          Math.cos(degreesToRadians(360 - rotationAngle)),
          'height'
        );
      }

      if (activeElement.top + verticalToBottom > canvasHeight) {
        const intersectionPointWithCanvasBottomEdge = new fabric.Point(bottomRightPoint.x, canvasHeight);

        setDimension(
          activeElement,
          bottomRightPoint,
          'bottomRight',
          intersectionPointWithCanvasBottomEdge,
          Math.sin(degreesToRadians(360 - rotationAngle)),
          'width'
        );
      }

      stopScalingInXAndYDirections(activeElement, activeElement.left < 0, topLeftPoint.x, { prop: 'left', value: 0 });

      return;
    }

    if (corner === ItemCorner.TopRight) {
      if (activeElement.left < 0) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, bottomLeftPoint.y);

        setDimension(
          activeElement,
          bottomLeftPoint,
          'bottomLeft',
          intersectionPointWithCanvasLeftEdge,
          Math.sin(degreesToRadians(360 - rotationAngle)),
          'height'
        );
      }

      if (activeElement.left + horizontalToRight > canvasWidth) {
        const intersectionPointWithCanvasRightEdge = new fabric.Point(canvasWidth, bottomLeftPoint.y);

        setDimension(
          activeElement,
          bottomLeftPoint,
          'bottomLeft',
          intersectionPointWithCanvasRightEdge,
          Math.cos(degreesToRadians(360 - rotationAngle)),
          'width'
        );
      }

      stopScalingInXAndYDirections(activeElement, activeElement.top - verticalToTop < 0, topRightPoint.y, {
        prop: 'top',
        value: verticalToTop,
      });

      return;
    }

    if (corner === ItemCorner.BottomLeft) {
      if (activeElement.left < 0) {
        const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, topRightPoint.y);

        setDimension(
          activeElement,
          topRightPoint,
          'topRight',
          intersectionPointWithCanvasLeftEdge,
          Math.cos(degreesToRadians(360 - rotationAngle)),
          'width'
        );
      }

      if (activeElement.left + horizontalToRight > canvasWidth) {
        const intersectionPointWithCanvasRightEdge = new fabric.Point(canvasWidth, topRightPoint.y);

        setDimension(
          activeElement,
          topRightPoint,
          'topRight',
          intersectionPointWithCanvasRightEdge,
          Math.sin(degreesToRadians(360 - rotationAngle)),
          'height'
        );
      }

      stopScalingInXAndYDirections(
        activeElement,
        activeElement.top + verticalToBottom > canvasHeight,
        bottomLeftPoint.y - canvasHeight,
        { prop: 'top', value: canvasHeight - verticalToBottom }
      );

      return;
    }

    if (corner === ItemCorner.BottomRight) {
      if (activeElement.top - verticalToTop < 0) {
        const intersectionPointWithCanvasTopEdge = new fabric.Point(topLeftPoint.x, 0);

        setDimension(
          activeElement,
          topLeftPoint,
          'topLeft',
          intersectionPointWithCanvasTopEdge,
          Math.sin(degreesToRadians(360 - rotationAngle)),
          'width'
        );
      }

      if (activeElement.top + verticalToBottom > canvasHeight) {
        const intersectionPointWithCanvasBottomEdge = new fabric.Point(topLeftPoint.x, canvasHeight);

        setDimension(
          activeElement,
          topLeftPoint,
          'topLeft',
          intersectionPointWithCanvasBottomEdge,
          Math.cos(degreesToRadians(360 - rotationAngle)),
          'height'
        );
      }

      stopScalingInXAndYDirections(
        activeElement,
        activeElement.left + horizontalToRight > canvasWidth,
        bottomRightPoint.x - canvasWidth,
        { prop: 'left', value: canvasWidth - horizontalToRight }
      );

      return;
    }

    return;
  }
};

export {
  degreesToRadians,
  getDistanceBetweenTwoPoints,
  keepTextOrImageInsideCanvasForScaling,
  getTopLeftPoint,
  getTopRightPoint,
  getBottomLeftPoint,
  getBottomRightPoint,
};
