import { Injectable } from '@angular/core';
import { OlcTedPublicTemplateEditorService } from './olc-ted-public-template-editor.service';

import * as jQuery from 'jquery';
import { uniqueID } from '../utils/olc-ted-public-utilities.utils';
import { HydraApiService } from './../../../../../blocks/services/hydra-api.service';
import { ITemplateVersion, Template } from '../../../models/template';
import { ToastrService } from 'ngx-toastr';
import { SpinnerStateService } from './../../../../../blocks/services/spinner-state.service';
import { TranslateService } from '@ngx-translate/core';
import { ITEDItem, ITEDSection, LengthUnit, TEDSection } from '../models/ted-state';
import { ClearZone } from '../models/clear-zone';
import { JsTreeNodeType, Shape, ShapeType } from '../models/shape';
import { Style } from '../../../models/style';
import { Snippet } from '../../../models/snippet';
import { UserStateService } from './../../../../../blocks/services/user-state.service';
import { CanvasState } from '../models/canvas-state';
import { RolePermissions } from '../../../../../../../../../Bamba.Shared/src/models/role';

@Injectable({
  providedIn: 'root',
})
export class OlcTedPublicOpenTemplateService {
  templateId: string;
  versionId: string;

  constructor(
    private templateEditorService: OlcTedPublicTemplateEditorService,
    private hydraApi: HydraApiService,
    private toastr: ToastrService,
    private spinnerState: SpinnerStateService,
    private translateService: TranslateService,
    private userStateService: UserStateService
  ) {}

  /**
   * Open a Connect template in the editor.
   *
   * @param {string} templateId The Id of the template to open.
   * @param {string} version The version of the template to open.
   */
  openTemplate(templateId: string, versionId: string, currentCanvasState: CanvasState) {
    this.templateId = templateId;
    this.versionId = versionId;

    this.spinnerState.show(this.translateService.instant('Common.LoadingData'), document.documentElement);

    this.hydraApi.getOLCTemplate(
      this.templateId,
      (template) => this.templateLoaded(template, currentCanvasState),
      this.templateLoadFailed
    );

    if (this.userStateService.hasRolePermission(RolePermissions.OLCTED_STYLES_APPLY)) {
      this.hydraApi.getOLCTemplateCustomStyles(this.templateId, this.stylesLoaded, this.stylesLoadFailed);
    } else {
      this.templateEditorService.setTemplateCustomStyles([]);
    }

    if (this.userStateService.hasRolePermission(RolePermissions.OLCTED_SNIPPETS_APPLY)) {
      this.hydraApi.getOLCTemplateSnippets(this.templateId, this.snippetsLoaded, this.snippetsLoadFailed);
    } else {
      this.templateEditorService.setTemplateSnippets([]);
    }
  }

  // TODO: This massive function do all initialization for all components in ted which is very bad
  // So it should be divided into smaller function and each small function should be used in its corresponding component
  templateLoaded = (template: Template, currentCanvasState: CanvasState) => {
    const that = this;

    that.spinnerState.hide();

    that.templateEditorService.setCurrentTemplate(template);

    const templateVersions: ITemplateVersion[] = template.versions;
    const versionOptions = JSON.parse(template.optionsJSON);
    const versionPackage = that.mapVersionPackage(JSON.parse(template.indexJSON).package);

    // TODO: mock data should be replaced later
    const templateCustomerName = '';
    //end mock data

    that.templateEditorService.connectTemplate = {
      package: versionPackage,
      options: versionOptions,
      recordCount: template.recordsCount,
    };

    const updatedCanvasState = { ...currentCanvasState };

    updatedCanvasState.shapes = [];
    updatedCanvasState.selection = null;
    updatedCanvasState.clearZones = [];

    // get ordered template's sections

    const printSection = that.templateEditorService.connectTemplate.package.manifest.contexts.context.find(
      (item) => item.type === 'PRINT'
    );

    let orderedSectionsIds: string[] = [];

    if (printSection) {
      const section = printSection.section;
      orderedSectionsIds = Array.isArray(section) ? section : [section];
    }

    const orderedSections = orderedSectionsIds
      .map((id) =>
        that.templateEditorService.connectTemplate.package.manifest.sections.section.find((s) => s['@id'] === id)
      )
      .filter((s) => !!s);

    // If sub customer is set for this template, set the variable
    // This will be used for styles, style groups, snippets and snippet groups
    if (templateCustomerName) {
      that.templateEditorService.templateCustomerName = templateCustomerName;
    } else {
      that.templateEditorService.templateCustomerName = '';
    }

    // Decode through JQuery eventual html entities received from WordPress so template name as well as download link work properly
    that.templateEditorService.templateName = jQuery('<textarea/>').html(template.name).text();

    // populate appropriate field coming from the options.json in the template/datamap package
    if (!that.templateEditorService.connectTemplate.options) {
      // if no options then set to empty arrays
      that.templateEditorService.connectTemplate.options = {
        conditions: [],
        variables: [],
        style_formats: [],
        clear_zones: [],
      };
    } else {
      // make copies of the original values of conditions and variables
      // @todo These appear not to be copies, more so the creation of empty arrays.

      that.templateEditorService.templateVariables = [];
      that.templateEditorService.templateClearZones = [];

      for (let i = 0; i < template.variables.length; i++) {
        that.templateEditorService.templateVariables.push(template.variables[i]);
      }

      that.templateEditorService.templateVariablesHighlight = template.variablesHighlight;

      if (template.clearZones !== undefined) {
        for (let i = 0; i < template.clearZones.length; i++) {
          // Connect rotates shape on its center so we need to define it
          // and will use this point as the origin of the translation to define (x,y) of shape
          var center = that.getIntersectPoint(
            that.inPixel(template.clearZones[i].left),
            that.inPixel(template.clearZones[i].top),
            that.inPixel(template.clearZones[i].left) + that.inPixel(template.clearZones[i].width),
            that.inPixel(template.clearZones[i].top) + that.inPixel(template.clearZones[i].height),
            that.inPixel(template.clearZones[i].left),
            that.inPixel(template.clearZones[i].top) + that.inPixel(template.clearZones[i].height),
            that.inPixel(template.clearZones[i].left) + that.inPixel(template.clearZones[i].width),
            that.inPixel(template.clearZones[i].top)
          );
          if (template.clearZones[i].class == 'content') {
            // Full area
            let origin = this.translate(
              that.inPixel(template.clearZones[i].left),
              that.inPixel(template.clearZones[i].top),
              center?.x,
              center?.y,
              -template.clearZones[i].rotate || 0
            );

            that.templateEditorService.templateClearZones.push({
              id: uniqueID(),
              title: template.clearZones[i].title,
              y: origin.y,
              x: origin.x,
              w: that.inPixel(template.clearZones[i].width),
              h: that.inPixel(template.clearZones[i].height),
              rotate: template.clearZones[i].rotate || 0,
              type: template.clearZones[i].type,
              clearClass: template.clearZones[i].class,
              sections: that.getSections(template.clearZones[i].sections, orderedSections),
              pages: that.getPages(template.clearZones[i].pages),
              page: 0,
              section: 0,
            });
          } else if (template.clearZones[i].class == 'outline') {
            // We break down outlines into 4 areas
            let origin = this.translate(
              that.inPixel(template.clearZones[i].left),
              that.inPixel(template.clearZones[i].top),
              center?.x,
              center?.y,
              -template.clearZones[i].rotate || 0
            );
            that.templateEditorService.templateClearZones.push(
              // Top side
              {
                id: uniqueID(),
                title: template.clearZones[i].title,
                y: origin.y,
                x: origin.x,
                w: that.inPixel(template.clearZones[i].width),
                h: that.inPixel(template.clearZones[i].borderWidth || '0mm'),
                rotate: template.clearZones[i].rotate || 0,
                type: template.clearZones[i].type,
                clearClass: template.clearZones[i].class,
                sections: that.getSections(template.clearZones[i].sections, orderedSections),
                pages: that.getPages(template.clearZones[i].pages),
                page: 0,
                section: 0,
              }
            );
            origin = this.translate(
              that.inPixel(template.clearZones[i].left) +
                that.inPixel(template.clearZones[i].width) -
                that.inPixel(template.clearZones[i].borderWidth || '0mm'),
              that.inPixel(template.clearZones[i].top),
              center?.x,
              center?.y,
              -template.clearZones[i].rotate || 0
            );
            that.templateEditorService.templateClearZones.push(
              // Right side
              {
                id: uniqueID(),
                title: template.clearZones[i].title,
                y: origin.y,
                x: origin.x,
                w: that.inPixel(template.clearZones[i].borderWidth || '0mm'),
                h: that.inPixel(template.clearZones[i].height),
                rotate: template.clearZones[i].rotate || 0,
                type: template.clearZones[i].type,
                clearClass: template.clearZones[i].class,
                sections: that.getSections(template.clearZones[i].sections, orderedSections),
                pages: that.getPages(template.clearZones[i].pages),
                page: 0,
                section: 0,
              }
            );
            origin = this.translate(
              that.inPixel(template.clearZones[i].left),
              that.inPixel(template.clearZones[i].top) +
                that.inPixel(template.clearZones[i].height) -
                that.inPixel(template.clearZones[i].borderWidth || '0mm'),
              center?.x,
              center?.y,
              -template.clearZones[i].rotate || 0
            );
            that.templateEditorService.templateClearZones.push(
              // Bottom side
              {
                id: uniqueID(),
                title: template.clearZones[i].title,
                y: origin.y,
                x: origin.x,
                w: that.inPixel(template.clearZones[i].width),
                h: that.inPixel(template.clearZones[i].borderWidth || '0mm'),
                rotate: template.clearZones[i].rotate || 0,
                type: template.clearZones[i].type,
                clearClass: template.clearZones[i].class,
                sections: that.getSections(template.clearZones[i].sections, orderedSections),
                pages: that.getPages(template.clearZones[i].pages),
                page: 0,
                section: 0,
              }
            );
            origin = this.translate(
              that.inPixel(template.clearZones[i].left),
              that.inPixel(template.clearZones[i].top),
              center?.x,
              center?.y,
              -template.clearZones[i].rotate || 0
            );
            that.templateEditorService.templateClearZones.push(
              // Left side
              {
                id: uniqueID(),
                title: template.clearZones[i].title,
                y: origin.y,
                x: origin.x,
                w: that.inPixel(template.clearZones[i].borderWidth || '0mm'),
                h: that.inPixel(template.clearZones[i].height),
                rotate: template.clearZones[i].rotate || 0,
                type: template.clearZones[i].type,
                clearClass: template.clearZones[i].class,
                sections: that.getSections(template.clearZones[i].sections, orderedSections),
                pages: that.getPages(template.clearZones[i].pages),
                page: 0,
                section: 0,
              }
            );
          }
        }
        // creates shapes for each clear zones
        that.templateEditorService.templateClearZones.forEach(function (zone) {
          zone.sections.forEach(function (_, sectionIndex) {
            zone.pages.forEach(function (_, pageIndex) {
              updatedCanvasState.clearZones.push(
                new ClearZone({
                  ...zone,
                  page: zone.pages[pageIndex],
                  section: zone.sections[sectionIndex],
                  sections: [],
                  pages: [],
                })
              );
            });
          });
        });
      }
    }

    let currentVersionSections: ITEDSection[];
    let currentVersionItems: ITEDItem[];

    if (templateVersions) {
      // there is already a version
      if (that.versionId) {
        const currentVersion = templateVersions.find((v) => v.versionId === that.versionId); // find a specific version

        if (currentVersion) {
          // version exist

          that.templateEditorService.versionId = currentVersion.versionId;

          currentVersionSections = currentVersion.sections;
          currentVersionItems = currentVersion.items;
        } else {
          that.templateEditorService.versionId = templateVersions[0].versionId;

          currentVersionSections = templateVersions[0].sections;
          currentVersionItems = templateVersions[0].items;
        }
      } else {
        that.templateEditorService.versionId = templateVersions[0].versionId;

        currentVersionSections = templateVersions[0].sections;
        currentVersionItems = templateVersions[0].items;
      }
    }

    var newTree: any = [];

    updatedCanvasState.sections = [];

    for (let i = 0; i < orderedSections.length; i++) {
      const id = orderedSections[i]['@id'];
      const currentSection = currentVersionSections.find((s) => s.id === id);

      let aSection: any = {
        name: orderedSections[i].name,
        id: id,
        index: i,
        leftMargin: that.inPixel(orderedSections[i]['left-margin']),
        topMargin: that.inPixel(orderedSections[i]['top-margin']),
        rightMargin: that.inPixel(orderedSections[i]['right-margin']),
        bottomMargin: that.inPixel(orderedSections[i]['bottom-margin']),
        pageSize: orderedSections[i].size.name,
        portrait: orderedSections[i].portrait == 'true',
        pages: parseInt(orderedSections[i]['minPages']),
        backgrounds: currentSection?.backgrounds || [],
        bodies: currentSection?.bodies || [],
      };
      if (aSection.portrait) {
        aSection.width = that.inPixel(orderedSections[i].size.width);
        aSection.height = that.inPixel(orderedSections[i].size.height);
      } else {
        aSection.height = that.inPixel(orderedSections[i].size.width);
        aSection.width = that.inPixel(orderedSections[i].size.height);
      }

      updatedCanvasState.sections.push(aSection);
    }

    // populate tree in the section order
    updatedCanvasState.sections.forEach((s) => {
      newTree.push({
        id: 'S' + s.index,
        parent: '#',
        text: s.name,
        type: JsTreeNodeType.SectionOpened,
        state: { opened: true },
        data: {
          section: s.index,
          sectionName: s.name,
          sectionId: s.id,
        },
      });
      for (let j = 0; j < s.pages; j++) {
        newTree.push({
          id: 'S' + s.index + 'P' + j,
          parent: 'S' + s.index,
          text: this.translateService.instant('admin-olc-templates.page') + ' ' + (j + 1),
          type: JsTreeNodeType.Page,
          state: { opened: true },
          data: {
            section: s.index,
            sectionName: s.name,
            page: j,
          },
        });
      }
    });

    for (let i = 0; i < currentVersionItems.length; i++) {
      updatedCanvasState.shapes.push(
        new Shape({
          id: currentVersionItems[i].id,
          title: currentVersionItems[i].title,
          x: currentVersionItems[i].x,
          y: currentVersionItems[i].y,
          w: currentVersionItems[i].w,
          h: currentVersionItems[i].h,
          page: currentVersionItems[i].page,
          section: currentVersionItems[i].section || 0,
          type: currentVersionItems[i].type,
          texts: currentVersionItems[i].texts,
          images: currentVersionItems[i].images,
          class: currentVersionItems[i].class,
          rotate: currentVersionItems[i].rotate,
        })
      );

      newTree.push({
        id: currentVersionItems[i].id,
        parent: 'S' + (currentVersionItems[i].section || 0) + 'P' + currentVersionItems[i].page,
        text: currentVersionItems[i].title,
        type: currentVersionItems[i].type === ShapeType.Text ? JsTreeNodeType.Text : JsTreeNodeType.Image,
        state: { opened: true },
        data: {
          section: currentVersionItems[i].section,
          page: currentVersionItems[i].page,
        },
      });
    }

    that.templateEditorService.setCanvasState(updatedCanvasState);

    // push the new data in the tree with all open branches
    that.templateEditorService.tree.settings.core.data = newTree;
    that.templateEditorService.tree.refresh();
  };

  templateLoadFailed = () => {
    this.spinnerState.hide();
    this.toastr.error(this.translateService.instant('admin-olc-templates.template-load-failed'));
  };

  stylesLoaded = (styles: Style[]) => {
    this.templateEditorService.setTemplateCustomStyles(styles);
  };

  stylesLoadFailed = () => {
    this.toastr.error(this.translateService.instant('admin-olc-templates.template-styles-load-failed'));
  };

  snippetsLoaded = (snippets: Snippet[]) => {
    this.templateEditorService.setTemplateSnippets(snippets);
  };

  snippetsLoadFailed = () => {
    this.toastr.error(this.translateService.instant('admin-olc-templates.template-snippets-load-failed'));
  };

  mapVersionPackage = (versionPackage) => {
    const section = versionPackage.manifest.sections.section;
    const context = versionPackage.manifest.contexts.context;
    if (!Array.isArray(section)) versionPackage.manifest.sections.section = [section];
    if (!Array.isArray(context)) versionPackage.manifest.contexts.context = [context];

    return versionPackage;
  };

  getOrderedSections = (canvasSections: TEDSection[]) => {
    const printSection = this.templateEditorService.connectTemplate.package.manifest.contexts.context.find(
      (c) => c.type === 'PRINT'
    );

    let orderedSectionsIds = [];

    if (printSection) {
      const section = printSection.section;
      orderedSectionsIds = Array.isArray(section) ? section : [section];
    }

    return orderedSectionsIds.map((id) => canvasSections.find((s) => s.id === id)).filter((s) => !!s);
  };

  /**
   * Get Connect Template sections.
   *
   * @param {Object} list List of clear zone sections.
   * @param {Object} sections Clear zone sections contained with the templates manifest.
   * @returns Consolidated list of sections.
   */
  getSections = (list, sections): number[] => {
    const result = [];

    list.forEach(function (name) {
      sections.forEach(function (item, index) {
        if (item['name'] == name) result.push(index);
      });
    });

    return result;
  };

  /**
   * Get Connect Template pages.
   *
   * @param {Object} list List of clear zone pages.
   * @returns Reindexed pages.
   */
  getPages = (list): number[] => {
    var result = [];

    list.forEach(function (value) {
      result.push(parseInt(value) - 1);
    });

    return result;
  };

  /**
   * Get Connect Template intersect points.
   *
   * @param {Number} x1 Clear zone left position.
   * @param {Number} y1 Clear zone top position.
   * @param {Number} x2 Clear zone left + clear zone wisth.
   * @param {Number} y2 Clear zone top + clear zone height.
   * @param {Number} x3 Clear zone left position.
   * @param {Number} y3 Clear zone top position + clear zone height.
   * @param {Number} x4 Clear zone left position + clear zone width.
   * @param {Number} y4 Clear zone top position.
   * @returns Intersect.
   */
  getIntersectPoint = (
    x1: number,
    y1: number,
    x2: number,
    y2: number,
    x3: number,
    y3: number,
    x4: number,
    y4: number
  ) => {
    let denom = (y4 - y3) * (x2 - x1) - (x4 - x3) * (y2 - y1);
    if (denom == 0) {
      return null;
    }
    let ua = ((x4 - x3) * (y1 - y3) - (y4 - y3) * (x1 - x3)) / denom;
    return {
      x: x1 + ua * (x2 - x1),
      y: y1 + ua * (y2 - y1),
    };
  };

  /**
   * Convert a size into pixels.
   *
   * @param {String} value Definition of size in various formats.
   * @returns
   */
  inPixel = (value: string): number => {
    if (value.endsWith(LengthUnit.IN)) {
      return Number(value.slice(0, -2)) * 96;
    }
    if (value.endsWith(LengthUnit.MM)) {
      return Number(value.slice(0, -2)) * 3.78;
    }
    if (value.endsWith(LengthUnit.CM)) {
      return Number(value.slice(0, -2)) * 37.78;
    }
    if (value.endsWith(LengthUnit.PT)) {
      return (Number(value.slice(0, -2)) / 72) * 96;
    }
    if (value.endsWith(LengthUnit.PC)) {
      return Number(value.slice(0, -2)) / 8;
    }
    if (value.endsWith(LengthUnit.PX)) {
      return Number(value.slice(0, -2));
    }
    return Number(value);
  };

  translate = (Mx: number, My: number, Ox: number, Oy: number, angle: number) => {
    var xM, yM, x, y;
    angle *= Math.PI / 180;
    xM = Mx - Ox;
    yM = My - Oy;
    x = xM * Math.cos(angle) + yM * Math.sin(angle) + Ox;
    y = -xM * Math.sin(angle) + yM * Math.cos(angle) + Oy;
    return { x: Math.round(x), y: Math.round(y) };
  };
}
