import { Component, OnDestroy, OnInit, ViewEncapsulation } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { Subscription, combineLatest } from 'rxjs';
import { TemplateVersion } from '../../models/template';
import { ErrorsService } from './../../../../blocks/services/errors.service';
import { HydraApiService } from './../../../../blocks/services/hydra-api.service';
import { ApiResult, Control } from './../../../../blocks/services/models';
import { SpinnerStateService } from './../../../../blocks/services/spinner-state.service';

@Component({
  selector: 'app-version',
  templateUrl: './version.component.html',
  styleUrls: ['./version.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class VersionComponent implements OnInit, OnDestroy {
  rightControls: Array<Control> = [];

  version: TemplateVersion;
  templateId: string;
  routeDataType: string;

  subscriptions = new Subscription();

  constructor(
    private translate: TranslateService,
    private router: Router,
    private hydraApi: HydraApiService,
    private route: ActivatedRoute,
    private toastr: ToastrService,
    private errorsService: ErrorsService,
    private spinner: SpinnerStateService
  ) {}

  ngOnInit() {
    this.createButtons();
    this.getTemplateVersionData();
  }

  getTemplateVersionData() {
    this.subscriptions.add(
      combineLatest([this.route.params, this.route.data]).subscribe(([params, data]) => {
        this.routeDataType = data.type;
        this.templateId = params.templateId;

        if (['properties'].includes(this.routeDataType)) {
          this.spinner.show(this.translate.instant('Common.Loading'), document.documentElement);

          this.hydraApi.getOLCTemplateVersion(
            this.templateId,
            params.versionId,
            this.versionLoaded,
            this.versionLoadFailed
          );
        }
      })
    );
  }

  private versionLoaded = (version: TemplateVersion) => {
    this.version = version;
    this.spinner.hide();
  };

  private versionLoadFailed = () => {
    this.toastr.error(this.translate.instant('admin-olc-templates.version-load-failed'));
    this.spinner.hide();
  };

  private createButtons() {
    const saveButton = new Control(
      this.onSave,
      this.translate.instant('admin-olc-templates.save'),
      'btn btn-primary btn-minwidth',
      '',
      '',
      'btn',
      false
    );

    const cancelButton = new Control(
      this.onCancel,
      this.translate.instant('admin-olc-templates.cancel'),
      'btn btn-light btn-minwidth',
      '',
      '',
      'btn',
      false
    );

    this.rightControls.push(saveButton);
    this.rightControls.push(cancelButton);
  }

  onSave = () => {
    this.spinner.showSavingSpinner();
    if (this.version.versionId) {
      this.hydraApi.updateOLCTemplateVersion(this.templateId, this.version, this.versionSaved, this.versionSaveFailed);
    }
  };

  onCancel = () => {
    this.returnToGrid();
  };

  versionSaved = (result: ApiResult) => {
    if (result.success) {
      this.toastr.success(this.translate.instant('admin-olc-templates.version-saved'));
      this.returnToGrid();
    } else {
      this.errorsService.showErrorsModal(result.errors, 'admin-olc-templates.version-validation-errors');
    }
    this.spinner.hide();
  };

  versionSaveFailed = (err: any) => {
    this.toastr.error(this.translate.instant('admin-olc-templates.version-save-failed'));
    this.spinner.hide();
  };

  returnToGrid = () => {
    this.router.navigateByUrl(
      `product/settings/BambaOLCTEDApplication/BambaOLCTEDApplication-Upland.Bamba.OLCTed.Templates.VersionsDetailsFolder@${this.templateId}`
    );
  };

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}
