import { fabric } from 'fabric';
import { ShapeType } from '../../models/shape';

export interface IItemRectOptions extends fabric.IRectOptions {
  id: string;
  type: ShapeType;
}

export class ItemRect extends fabric.Rect {
  id: string;
  type: ShapeType;

  constructor(initializer: IItemRectOptions) {
    super(initializer);

    this.id = initializer.id || '';
    this.type = initializer.type;
  }
}

export enum UserAction {
  Drag = 'drag',
  Scale = 'scale',
  ScaleX = 'scaleX',
  ScaleY = 'scaleY',
}

export enum ItemCorner {
  TopLeft = 'tl',
  MiddleTop = 'mt',
  TopRight = 'tr',
  MiddleLeft = 'ml',
  MiddleRight = 'mr',
  BottomLeft = 'bl',
  BottomRight = 'br',
  MiddleBottom = 'mb',
}

export enum ItemUpdateMode {
  Add = 'add',
  Edit = 'edit',
  Delete = 'delete',
}

export interface IItemUpdate {
  left: number;
  top: number;
  width: number;
  height: number;
  angle: number;
}

export interface IItemUpdateWithMode extends IItemUpdate {
  mode: ItemUpdateMode;
}

export interface IITemLimits {
  minLeft: number;
  maxLeft: number;
  minTop: number;
  maxTop: number;
  minWidth: number;
  maxWidth: number;
  minHeight: number;
  maxHeight: number;
}
