import { Location } from '@angular/common';
import { Component, OnDestroy, OnInit, ViewEncapsulation } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { Subscription, combineLatest } from 'rxjs';
import { FieldDefinition } from '../../../../../../../Bamba.Shared/src/models/field-definition';
import { MetaDataType } from '../../../../../../../Bamba.Shared/src/models/metadata-definition';
import { ErrorsService } from '../../../blocks/services/errors.service';
import { HydraApiService } from '../../../blocks/services/hydra-api.service';
import { ApiResult, Control } from '../../../blocks/services/models';
import { SpinnerStateService } from '../../../blocks/services/spinner-state.service';
import { Template, TemplateType } from './../models/template';

@Component({
  selector: 'app-templates',
  templateUrl: './templates.component.html',
  styleUrls: ['./templates.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class TemplatesComponent implements OnInit, OnDestroy {
  rightControls: Array<Control> = [];
  fieldName: FieldDefinition;
  fieldDescription: FieldDefinition;

  template: Template;
  TemplateType = TemplateType;
  routeDataType: string;

  subscriptions = new Subscription();

  constructor(
    private translate: TranslateService,
    private hydraApi: HydraApiService,
    private route: ActivatedRoute,
    private toastr: ToastrService,
    private errorsService: ErrorsService,
    private spinner: SpinnerStateService,
    private location: Location
  ) {}

  ngOnInit() {
    this.createButtons();
    this.createFields();
    this.getTemplateData();
  }

  getTemplateData() {
    this.subscriptions.add(
      combineLatest([this.route.params, this.route.data]).subscribe(([params, data]) => {
        this.routeDataType = data.type;

        if (['properties'].includes(this.routeDataType)) {
          this.spinner.show(this.translate.instant('Common.Loading'), document.documentElement);
          this.hydraApi.getOLCTemplate(params.templateId, this.templateLoaded, this.templateLoadFailed);
        }
      })
    );
  }

  private templateLoaded = (template: Template) => {
    this.template = template;
    this.spinner.hide();
  };

  private templateLoadFailed = () => {
    this.toastr.error(this.translate.instant('admin-olc-templates.template-load-failed'));
    this.spinner.hide();
  };

  private createFields = () => {
    this.fieldName = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('admin-olc-templates.name'),
      placeholder: this.translate.instant('admin-olc-templates.name-placeholder'),
      required: true,
    });

    this.fieldDescription = new FieldDefinition({
      type: MetaDataType.LargeText,
      label: this.translate.instant('admin-olc-templates.description'),
      placeholder: this.translate.instant('admin-olc-templates.description-placeholder'),
      required: false,
    });
  };

  private createButtons() {
    const saveButton = new Control(
      this.onSave,
      this.translate.instant('admin-olc-templates.save'),
      'btn btn-primary btn-minwidth',
      '',
      '',
      'btn',
      false
    );

    const cancelButton = new Control(
      this.onCancel,
      this.translate.instant('admin-olc-templates.cancel'),
      'btn btn-light btn-minwidth',
      '',
      '',
      'btn',
      false
    );

    this.rightControls.push(saveButton);
    this.rightControls.push(cancelButton);
  }

  onSave = () => {
    this.spinner.showSavingSpinner();
    if (this.template.id) {
      this.hydraApi.updateOLCTemplate(this.template, this.templateSaved, this.templateSaveFailed);
    }
  };

  onCancel = () => {
    this.returnToGrid();
  };

  templateSaved = (result: ApiResult) => {
    if (result.success) {
      this.toastr.success(this.translate.instant('admin-olc-templates.template-saved'));
      this.returnToGrid();
    } else {
      this.errorsService.showErrorsModal(result.errors, 'admin-olc-templates.template-validation-errors');
    }
    this.spinner.hide();
  };

  templateSaveFailed = (err: any) => {
    this.toastr.error(this.translate.instant('admin-olc-templates.template-save-failed'));
    this.spinner.hide();
  };

  returnToGrid = () => this.location.back();

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}
