import { Injectable } from '@angular/core';
import { OlcTedPublicPayloadsService } from './olc-ted-public-payloads.service';
import { OlcTedPublicTemplateEditorService } from './olc-ted-public-template-editor.service';

import { ApiResult } from './../../../../../blocks/services/models';
import { HydraApiService } from './../../../../../blocks/services/hydra-api.service';
import { SpinnerStateService } from './../../../../../blocks/services/spinner-state.service';
import { ToastrService } from 'ngx-toastr';
import { IRefreshBackgroundPayload } from '../models/ted-state';
import { CanvasState } from '../models/canvas-state';
import { TranslateService } from '@ngx-translate/core';
import { UserStateService } from './../../../../../blocks/services/user-state.service';
import moment from 'moment';
import * as jQuery from 'jquery';

@Injectable({
  providedIn: 'root',
})
export class OlcTedPublicTemplateRefreshService {
  state: CanvasState;

  constructor(
    private templateEditorService: OlcTedPublicTemplateEditorService,
    private payloadsService: OlcTedPublicPayloadsService,
    private hydraApi: HydraApiService,
    private spinnerStateService: SpinnerStateService,
    private toastr: ToastrService,
    private translateService: TranslateService,
    private userStateService: UserStateService
  ) {}

  refreshBackground(state: CanvasState) {
    this.state = state;
    const pageIndex = this.templateEditorService.currentDisplayPage;
    const sectionIndex = this.templateEditorService.currentSection;

    this.spinnerStateService.show(this.translateService.instant('Common.LoadingData'), document.documentElement);

    const versionPayload = this.payloadsService.prepareJsonPayload(state);

    const section = versionPayload.sections[sectionIndex];
    section.bodies = section.bodies.filter((body) => this.isItemVisible(body.from, body.to, body.condition));
    section.backgrounds = section.backgrounds.filter((background) =>
      this.isItemVisible(background.from, background.to, background.condition)
    );

    versionPayload.items = versionPayload.items.filter((i) => i.section == sectionIndex && i.page == pageIndex);

    for (let item of versionPayload.items) {
      item.texts = item.texts.filter((text) => this.isItemVisible(text.from, text.to, text.condition));
      item.images = item.images.filter((image) => this.isItemVisible(image.from, image.to, image.condition));
      item.images = item.images.filter((image) => this.isItemVisible(image.from, image.to, image.condition));
      item.images = item.images.filter((image) => this.isItemVisible(image.from, image.to, image.condition));
    }

    const refreshBackgroundPayload: IRefreshBackgroundPayload = {
      page: pageIndex + 1,
      section: section,
      items: versionPayload.items,
      conditionalContentSelections: this.templateEditorService.conditionalContentSelections,
    };

    this.hydraApi.refreshBackground(
      this.templateEditorService.templateID,
      refreshBackgroundPayload,
      this.refreshBackgroundSucceeded,
      this.refreshBackgroundFailed
    );
  }

  private isItemVisible(from: string | number = '', to = '', condition = ''): boolean {
    if (!from && !to && !condition) return true;

    from = from || 0;
    to = to || '9999-12-31';

    const today = new Date().toISOString().slice(0, 10);
    const previewDate = jQuery('#previewDateInp').val() as string;
    const datelocaleFormat = this.userStateService.getLocalDateFormat();

    const previewDateInMilliSeconds = previewDate
      ? moment.utc(previewDate, datelocaleFormat).toDate().getTime()
      : new Date(today).getTime();
    const fromInMilliSeconds = new Date(from).getTime();
    const toInMilliSeconds = new Date(to).getTime();

    let conditionOverrides = {};

    jQuery('#condition-override input.condition').each(function () {
      // @ts-ignore
      if (this.value !== '0') {
        // @ts-ignore
        conditionOverrides[this.value] = jQuery(this).is(':checked') ? true : false;
      }
    });

    return (
      fromInMilliSeconds <= toInMilliSeconds &&
      previewDateInMilliSeconds >= fromInMilliSeconds &&
      previewDateInMilliSeconds <= toInMilliSeconds &&
      (!condition || conditionOverrides[condition])
    );
  }

  private refreshBackgroundSucceeded = (response: ApiResult) => {
    if (!response.success) {
      this.toastr.error(response.errors[0]);
      this.spinnerStateService.hide();
      return;
    }

    this.state.backgroundImage.onload = () => {
      this.templateEditorService.setCanvasState(this.state, true);
      this.spinnerStateService.hide();
    };

    this.state.backgroundImage.src = response.object;
  };

  private refreshBackgroundFailed = (error: any) => {
    this.toastr.error(error);
    this.spinnerStateService.hide();
  };
}
