import { AfterViewInit, Component, OnDestroy, OnInit, ViewEncapsulation } from '@angular/core';
import { Router } from '@angular/router';
import { OlcTedPublicTemplateEditorService } from './../../services/olc-ted-public-template-editor.service';

import { TranslateService } from '@ngx-translate/core';
import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';
import { Subscription } from 'rxjs';
import { FieldDefinition } from '../../../../../../../../../../Bamba.Shared/src/models/field-definition';
import { MetaDataType } from '../../../../../../../../../../Bamba.Shared/src/models/metadata-definition';
import { JsTreeNodeType, Shape, ShapeType } from '../../models/shape';
import {
  IPdfPreviewPayload,
  ISaveVersionPayload,
  ISetTemplatesToProductionPayload,
  ItemToAddOrEdit,
  MediaPreviewData,
  TEDItem,
  TEDSection,
} from '../../models/ted-state';
import { uniqueID } from '../../utils/olc-ted-public-utilities.utils';
import { HydraApiService } from './../../../../../../blocks/services/hydra-api.service';
import { ApiResult } from './../../../../../../blocks/services/models';
import { SpinnerStateService } from './../../../../../../blocks/services/spinner-state.service';
import { OlcTedPublicPayloadsService } from './../../services/olc-ted-public-payloads.service';

import { OlcTedPublicLoadPayloadDataService } from '../../services/olc-ted-public-load-payload-data.service';
import { OlcTedPublicTemplateRefreshService } from '../../services/olc-ted-public-template-refresh.service';

import { UserStateService } from './../../../../../../blocks/services/user-state.service';
import { ITemplateVersion, Template, VersionStatus } from './../../../../../../views/admin-olc/models/template';

import { isEqual, sortBy } from 'lodash';
import { RolePermissions } from '../../../../../../../../../../Bamba.Shared/src/models/role';
import { CanvasState } from '../../models/canvas-state';
import { ApprovalSelection } from './../../../../../../views/admin-olc/models/approvals';

@Component({
  selector: 'app-TED-menu',
  templateUrl: './TED-menu.component.html',
  styleUrls: ['./TED-menu.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class TEDMenuComponent implements OnInit, AfterViewInit, OnDestroy {
  saveCommentField: FieldDefinition;
  saveComment = '';

  saveTemplateVersionModal: NgxSmartModalComponent;
  pdfPreviewModal: NgxSmartModalComponent;
  createApprovalModal: NgxSmartModalComponent;
  approveTemplateModal: NgxSmartModalComponent;
  rejectTemplateModal: NgxSmartModalComponent;
  submitTemplateToProductionModal: NgxSmartModalComponent;
  pdfPreviewObjectURL = '';
  currentRecord = 1;
  previewDate = '';

  textType = ItemToAddOrEdit.Text;
  imageType = ItemToAddOrEdit.Image;
  backgroundType = ItemToAddOrEdit.Background;
  bodyTextType = ItemToAddOrEdit.BodyText;

  selectedMediaPreviewData: MediaPreviewData = null;

  draftStatus = VersionStatus.Draft;
  pendingApprovalStatus = VersionStatus.PendingApproval;
  approvedStatus = VersionStatus.Approved;
  pendingProductionStatus = VersionStatus.PendingProduction;
  wasInProductionStatus = VersionStatus.WasInProduction;

  template: Template;
  currentVersion: ITemplateVersion;

  canRequestApproval = false;
  canApproveTemplate = false;
  canRejectTemplate = false;
  canSendTemplateToProduction = false;
  canSetTemplateToProduction = false;
  canApplyMedia = false;

  copiedElement: TEDItem = null;

  canvasState: CanvasState = null;

  subscriptions: Subscription[] = [];

  get selectedItem() {
    return this.canvasState.selection;
  }

  constructor(
    public templateEditorService: OlcTedPublicTemplateEditorService,
    private templateRefreshService: OlcTedPublicTemplateRefreshService,
    private payloadsService: OlcTedPublicPayloadsService,
    private loadPayloadDataService: OlcTedPublicLoadPayloadDataService,
    private toastr: ToastrService,
    private hydraApiService: HydraApiService,
    private spinnerService: SpinnerStateService,
    private ngxSmartModalService: NgxSmartModalService,
    private translateService: TranslateService,
    private router: Router,
    private userStateService: UserStateService
  ) {}

  ngOnInit() {
    this.subscriptions.push(
      this.templateEditorService.template$.subscribe((template) => {
        this.template = template;
        this.currentVersion = this.template?.versions.find((v) => v.versionId === this.templateEditorService.versionId);
      }),
      this.templateEditorService.onEditText.subscribe(() =>
        this.templateEditorService.openAddOrEditItemModal(ItemToAddOrEdit.Text, true)
      ),
      this.templateEditorService.onEditImage.subscribe(() =>
        this.templateEditorService.openAddOrEditItemModal(ItemToAddOrEdit.Image, true)
      ),
      this.templateEditorService.onEditBackground.subscribe(() =>
        this.templateEditorService.openAddOrEditItemModal(ItemToAddOrEdit.Background, true)
      ),
      this.templateEditorService.onEditBodyText.subscribe(() =>
        this.templateEditorService.openAddOrEditItemModal(ItemToAddOrEdit.BodyText, true)
      ),
      this.templateEditorService.canvasState$.subscribe((canvasState) => (this.canvasState = canvasState))
    );

    this.createFields();

    this.canRequestApproval = this.userStateService.hasRolePermission(RolePermissions.OLCTED_APPROVALS_CREATE);
    this.canApproveTemplate = this.userStateService.hasRolePermission(RolePermissions.OLCTED_APPROVALS_APPROVE);
    this.canRejectTemplate = this.userStateService.hasRolePermission(RolePermissions.OLCTED_APPROVALS_REJECT);
    this.canSendTemplateToProduction = this.userStateService.hasRolePermission(RolePermissions.OLCTED_PRODUCTION_SEND);
    this.canSetTemplateToProduction = this.userStateService.hasRolePermission(RolePermissions.OLCTED_PRODUCTION_SET);
    this.canApplyMedia = this.userStateService.hasRolePermission(RolePermissions.OLCTED_MEDIA_APPLY);
  }

  ngAfterViewInit() {
    this.saveTemplateVersionModal = this.ngxSmartModalService.get('saveTemplateVersionModal');
    this.pdfPreviewModal = this.ngxSmartModalService.get('pdfPreviewModal');
    this.createApprovalModal = this.ngxSmartModalService.get('createApprovalModal');
    this.approveTemplateModal = this.ngxSmartModalService.get('approveTemplateModal');
    this.rejectTemplateModal = this.ngxSmartModalService.get('rejectTemplateModal');
    this.submitTemplateToProductionModal = this.ngxSmartModalService.get('submitTemplateToProductionModal');
  }

  createFields() {
    this.saveCommentField = new FieldDefinition({
      type: MetaDataType.LargeText,
      label: this.translateService.instant('admin-olc-templates.version-comment-label'),
      placeholder: this.translateService.instant('admin-olc-templates.version-comment-placeholder'),
      required: true,
    });
  }

  openSaveVersionModal() {
    this.saveTemplateVersionModal.open();
  }

  saveTemplateVersion() {
    if (!this.saveComment) return;

    this.templateEditorService.saveToHistory = false;
    this.payloadsService.prepareJsonPayload(this.canvasState);

    const payload: ISaveVersionPayload = {
      comment: this.saveComment,
      items: this.templateEditorService.payload.items,
      sections: this.templateEditorService.payload.sections,
    };

    this.spinnerService.show(
      this.translateService.instant('admin-olc-templates.saving-version'),
      document.documentElement
    );

    this.hydraApiService.saveOLCTemplateVersion(
      this.templateEditorService.templateID,
      payload,
      this.versionSaved,
      this.versionSavingFailed
    );
  }

  closeSaveTemplateVersion = () => {
    this.saveTemplateVersionModal.close();
    this.saveComment = '';
  };

  versionSaved = (result: ApiResult) => {
    this.spinnerService.hide();

    if (!result.success) {
      this.toastr.error(result.errors[0]);
      return;
    }

    this.closeSaveTemplateVersion();

    this.toastr.success(this.translateService.instant('admin-olc-templates.version-saved'));

    const createdVersion = result.object;

    this.router.navigate([this.router.url.split('?')[0]], {
      queryParams: { versionId: createdVersion.versionId },
      state: {
        openedAccordionSection: 'template',
        currentSection: this.templateEditorService.currentSection,
        currentPage: this.templateEditorService.currentDisplayPage,
        isPageSelected: this.templateEditorService.isPageSelected,
        isSectionSelected: this.templateEditorService.isSectionSelected,
        keepUndoRedoStateHistory: true,
      },
    });
  };

  versionSavingFailed = () => {
    this.spinnerService.hide();
    this.toastr.error(this.translateService.instant('admin-olc-templates.version-save-failed'));
  };

  updateSaveComment(comment: string) {
    this.saveComment = comment;
  }

  openPdfPreviewModal() {
    this.pdfPreviewModal.open();
    this.previewCurrentRecord();
  }

  closePdfPreviewModal = () => {
    this.currentRecord = 1;
    this.pdfPreviewModal.close();
  };

  previewFirstRecord() {
    this.currentRecord = 1;
    this.previewCurrentRecord();
  }

  previewPreviousRecord() {
    --this.currentRecord;
    this.previewCurrentRecord();
  }

  previewNextRecord() {
    ++this.currentRecord;
    this.previewCurrentRecord();
  }

  previewLastRecord() {
    this.currentRecord = this.template?.recordsCount;
    this.previewCurrentRecord();
  }

  previewCurrentRecord() {
    if (this.currentRecord < 1 || this.currentRecord > this.template?.recordsCount) {
      this.toastr.error(this.translateService.instant('admin-olc-templates.invalid-record-number'));
      return;
    }

    this.getPDFPreviewFile();
  }

  getPDFPreviewFile() {
    const versionPayload = this.payloadsService.prepareJsonPayload(this.canvasState);

    const payload: IPdfPreviewPayload = {
      recordNumber: this.currentRecord,
      items: versionPayload.items,
      sections: versionPayload.sections,
    };

    this.spinnerService.show(
      this.translateService.instant('admin-olc-templates.loading-pdf'),
      document.querySelector('.olc-pdf-preview-modal')
    );

    this.hydraApiService.getPDFPreviewFile(
      this.templateEditorService.templateID,
      payload,
      this.getPDFPreviewFileSucceed,
      this.getPDFPreviewFileFailed
    );
  }

  getPDFPreviewFileSucceed = (pdfBlob: Blob) => {
    this.pdfPreviewObjectURL = URL.createObjectURL(pdfBlob);
    this.spinnerService.hide();
  };

  getPDFPreviewFileFailed = () => {
    this.toastr.error(this.translateService.instant('admin-olc-templates.pdf-preview-failed'));
    this.spinnerService.hide();
  };

  undo() {
    if (this.templateEditorService.undoIndex > 0) {
      this.templateEditorService.saveToHistory = false;
      this.templateEditorService.undoIndex = this.templateEditorService.undoIndex - 1;
      this.loadPayloadDataService.loadPayloadData(
        this.templateEditorService.undo[this.templateEditorService.undoIndex],
        this.canvasState
      );
    }
  }

  redo() {
    if (this.templateEditorService.undoIndex < this.templateEditorService.undo.length - 1) {
      this.templateEditorService.saveToHistory = false;
      this.templateEditorService.undoIndex = this.templateEditorService.undoIndex + 1;
      this.loadPayloadDataService.loadPayloadData(
        this.templateEditorService.undo[this.templateEditorService.undoIndex],
        this.canvasState
      );
    }
  }

  zoomIn() {
    this.templateEditorService.zoomIn();
  }

  zoomOut() {
    this.templateEditorService.zoomOut();
  }

  resetZoom() {
    this.templateEditorService.onReset.next();
  }

  showAddOrEditItemModal = () => {
    const addOrEditItemModal = this.ngxSmartModalService.get('addOrEditItemModal');
    return addOrEditItemModal.visible;
  };

  showSelectMediaModal() {
    const selectMediaModal = this.ngxSmartModalService.get('selectMediaModal');
    return selectMediaModal.visible;
  }

  setSelectedMediaPreviewUrl(mediaPreviewData: MediaPreviewData) {
    this.selectedMediaPreviewData = { ...mediaPreviewData };
  }

  editSelectedItem() {
    const selectedItem = this.canvasState.selection;

    const isText = selectedItem?.type === ShapeType.Text;
    const isImage = selectedItem?.type === ShapeType.Image;

    if (isText) {
      this.templateEditorService.onEditText.next();
      return;
    }

    if (isImage) {
      this.templateEditorService.onEditImage.next();
      return;
    }

    if (this.templateEditorService.isPageSelected) {
      this.templateEditorService.onEditBodyText.next();
      return;
    }

    if (this.templateEditorService.isSectionSelected) this.templateEditorService.onEditBackground.next();
  }

  /**
   * Delete a selected section.
   *
   * @since 1.1.0
   *
   * @param {e} e The observable event.
   */
  deleteSelection() {
    this.templateEditorService.deleteSelection(this.templateRefreshService);
  }

  copySelected() {
    const selectedNode = this.templateEditorService.tree.get_selected(true)[0];

    if (!selectedNode) {
      this.toastr.error(this.translateService.instant('admin-olc-menu.no-selected-element'));
      return;
    }

    if (![JsTreeNodeType.Text, JsTreeNodeType.Image].includes(selectedNode.type)) return;

    this.copiedElement = this.canvasState.selection;

    this.toastr.success(this.translateService.instant('admin-olc-menu.selected-element-copied-successfully'));
  }

  pasteSelection() {
    if (!this.copiedElement) {
      this.toastr.error(this.translateService.instant('admin-olc-menu.no-copied-element'));
      return;
    }

    const updatedCanvasState = { ...this.canvasState };

    updatedCanvasState.shapes.push(
      new Shape({
        id: uniqueID(),
        title: this.copiedElement.title,
        x: +this.copiedElement.x.toFixed(2),
        y: +this.copiedElement.y.toFixed(2),
        w: +this.copiedElement.w.toFixed(2),
        h: +this.copiedElement.h.toFixed(2),
        page: this.templateEditorService.currentDisplayPage,
        section: this.templateEditorService.currentSection,
        type: this.copiedElement.type,
        texts: this.copiedElement.texts,
        images: this.copiedElement.images,
        class: this.copiedElement.class,
        rotate: this.copiedElement.rotate,
      })
    );

    updatedCanvasState.selection = updatedCanvasState.shapes[updatedCanvasState.shapes.length - 1];

    this.templateEditorService.tree.create_node(
      'S' + this.templateEditorService.currentSection + 'P' + this.templateEditorService.currentDisplayPage,
      {
        id: updatedCanvasState.selection.id,
        text: updatedCanvasState.selection.title,
        type: updatedCanvasState.selection.type == ShapeType.Text ? JsTreeNodeType.Text : JsTreeNodeType.Image,
        state: {
          opened: true,
        },
        data: {
          section: this.templateEditorService.currentSection,
          page: this.templateEditorService.currentDisplayPage,
        },
      },
      'last'
    );

    this.templateEditorService.tree.deselect_all();
    this.templateEditorService.tree.select_node(updatedCanvasState.selection.id);
    this.templateRefreshService.refreshBackground(updatedCanvasState);

    this.toastr.success(this.translateService.instant('admin-olc-menu.selected-element-pasted-successfully'));
  }

  requestApproval() {
    if (!this.currentVersion) return;

    if (this.currentVersion.status !== this.draftStatus) return;

    if (this.versionChanged(this.currentVersion)) {
      this.toastr.error(this.translateService.instant('admin-olc-menu.version-has-unsaved-changes'));
      return;
    }

    if (this.currentVersion.status === VersionStatus.PendingApproval) {
      this.toastr.error(this.translateService.instant('admin-olc-menu.version-already-submitted-for-review'));
      return;
    }

    this.openCreateApprovalModal();
  }

  versionChanged = (version: ITemplateVersion) => {
    let newItems = this.canvasState.shapes.map(this.itemMapper);

    let newSections = this.canvasState.sections.map(this.sectionMapper).filter(this.sectionFilter);

    const oldItems = version.items.map(this.itemMapper);

    const oldSections = version.sections.map(this.sectionMapper).filter(this.sectionFilter);

    const itemsChanged = !this.isArrayEqual(oldItems, newItems);
    const sectionsChanged = !this.isArrayEqual(oldSections, newSections);

    return itemsChanged || sectionsChanged;
  };

  itemMapper = (i: TEDItem) => {
    const filteredTexts = i.texts.filter((t) => !(!t.condition && !t.from && !t.to && !t.text));
    const filteredImages = i.images.filter((img) => !(!img.condition && !img.from && !img.to && !img.image));
    return {
      w: i.w,
      h: i.h,
      x: i.x,
      y: i.y,
      class: i.class,
      page: i.page,
      rotate: i.rotate,
      section: i.section,
      title: i.title,
      type: i.type,
      texts: filteredTexts,
      images: filteredImages,
    };
  };

  sectionMapper = (s: TEDSection) => {
    const filteredBackgrounds = s.backgrounds.filter((bg) => !(!bg.condition && !bg.from && !bg.to && !bg.pdfURL));
    const filteredBodies = s.bodies.filter((bd) => !(!bd.condition && !bd.from && !bd.to && !bd.text));

    return {
      backgrounds: filteredBackgrounds,
      bodies: filteredBodies,
    };
  };

  sectionFilter = (s) => !(!s.backgrounds.length && !s.bodies.length);

  isArrayEqual = (arr1, arr2) => {
    if (arr1.length !== arr2.length) {
      return false;
    }

    const sortedArr1 = sortBy(arr1);
    const sortedArr2 = sortBy(arr2);

    for (let i = 0; i < sortedArr1.length; i++) {
      const element1 = sortedArr1[i];
      const element2 = sortedArr2[i];

      if (!isEqual(element1, element2)) {
        return false;
      }
    }

    return true;
  };

  openCreateApprovalModal() {
    this.createApprovalModal.open();
  }

  approveTemplate() {
    if (!this.currentVersion) return;

    if (this.currentVersion.status !== this.pendingApprovalStatus) return;

    if (this.currentVersion.status === VersionStatus.Approved) {
      this.toastr.error(this.translateService.instant('admin-olc-menu.version-already-approved'));
      return;
    }

    this.openApproveTemplateModal();
  }

  openApproveTemplateModal() {
    this.approveTemplateModal.open();
  }

  rejectTemplate() {
    if (!this.currentVersion) return;

    if (this.currentVersion.status !== this.pendingApprovalStatus) return;

    if (this.currentVersion.status === VersionStatus.Rejected) {
      this.toastr.error(this.translateService.instant('admin-olc-menu.version-already-rejected'));
      return;
    }

    this.openRejectTemplateModal();
  }

  openRejectTemplateModal() {
    this.rejectTemplateModal.open();
  }

  submitTemplateToProduction() {
    if (!this.currentVersion) return;

    if (this.currentVersion.status !== this.approvedStatus) return;

    if (this.currentVersion.status === VersionStatus.PendingProduction) {
      this.toastr.error(this.translateService.instant('admin-olc-menu.version-already-submitted-for-production'));
      return;
    }

    this.openSubmitTemplateToProductionModal();
  }

  openSubmitTemplateToProductionModal() {
    this.submitTemplateToProductionModal.open();
  }

  setTemplateToProduction() {
    if (!this.currentVersion) return;

    if (![this.pendingProductionStatus, this.wasInProductionStatus].includes(this.currentVersion.status)) return;

    if (this.currentVersion.status === VersionStatus.InProduction) {
      this.toastr.error(this.translateService.instant('admin-olc-menu.version-already-set-to-production'));
      return;
    }

    this.spinnerService.show(
      this.translateService.instant('admin-olc-menu.setting-template-to-production'),
      document.body
    );

    const payload: ISetTemplatesToProductionPayload = {
      selectedApprovals: [
        new ApprovalSelection({
          approvalId: null,
          templateId: this.templateEditorService.templateID,
          versionId: this.templateEditorService.versionId,
        }),
      ],
    };

    this.hydraApiService.setTemplateToProduction(
      payload,
      this.setTemplateToProductionSuccess,
      this.setTemplateToProductionFailure
    );
  }

  setTemplateToProductionSuccess = (result: ApiResult) => {
    this.spinnerService.hide();

    const error = result.errors[0];

    if (error) {
      this.toastr.error(error);
      return;
    }

    this.toastr.success(this.translateService.instant('admin-olc-menu.set-template-to-production-succeeded'));

    if (this.template) {
      const versionIndex = this.template.versions.findIndex(
        (v) => v.versionId === this.templateEditorService.versionId
      );

      if (versionIndex !== 1) this.template.versions[versionIndex].status = VersionStatus.InProduction;

      this.templateEditorService.setCurrentTemplate(this.template);
    }
  };

  setTemplateToProductionFailure = () => {
    this.spinnerService.hide();
    this.toastr.error(this.translateService.instant('admin-olc-menu.set-template-to-production-failed'));
  };

  ngOnDestroy(): void {
    this.subscriptions.forEach((s) => s.unsubscribe());
  }
}
