import { Component, Input, OnInit, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { HydraApiService } from '../../../../blocks/services/hydra-api.service';
import { SpinnerStateService } from '../../../../blocks/services/spinner-state.service';
import { IStyle, Style } from '../../models/style';
import { Template } from '../../models/template';

@Component({
  selector: 'app-properties-styles',
  templateUrl: './properties-styles.component.html',
  styleUrls: ['./properties-styles.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class PropertiesStylesComponent implements OnInit {
  @Input() template: Template;

  availableStyles: IStyle[] = [];
  selectedStyles: IStyle[] = [];

  constructor(
    private hydraApi: HydraApiService,
    private toastr: ToastrService,
    private translate: TranslateService,
    private spinner: SpinnerStateService
  ) {}

  ngOnInit() {
    this.loadPickListItems();
  }

  currentChanged = (styles: IStyle[]) => {
    this.template.customStyles = styles.map((style) => style.id);
  };

  loadPickListItems = () => {
    this.spinner.show(this.translate.instant('admin-olc-templates.loading-styles'), document.documentElement);
    this.hydraApi.getStyles(this.stylesLoaded, this.stylesLoadFailed);
  };

  stylesLoaded = (styles: Style[]) => {
    this.availableStyles = styles;
    this.selectedStyles = this.template.customStyles.map((styleId) => styles.find((s) => s.id === styleId)!);
    this.spinner.hide();
  };

  stylesLoadFailed = () => {
    this.spinner.hide();
    this.toastr.error(this.translate.instant('admin-olc-templates.styles-load-failed'));
  };
}
