import { Component, OnInit, Input, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { Tab } from 'shared-code-lib';
import { Template } from '../../models/template';

@Component({
  selector: 'app-properties-form',
  templateUrl: './properties-form.component.html',
  styleUrls: ['./properties-form.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class PropertiesFormComponent implements OnInit {
  @Input() template: Template;

  activeTab = 'snippets';
  tabs = new Array<Tab>();

  constructor(private translateService: TranslateService) {}

  ngOnInit() {
    this.createTabs();
  }

  createTabs() {
    this.tabs.push(new Tab('snippets', this.translateService.instant('admin-olc-templates.snippets')));
    this.tabs.push(new Tab('styles', this.translateService.instant('admin-olc-templates.styles')));
    this.tabs.push(
      new Tab('conditional-contents', this.translateService.instant('admin-olc-templates.conditional-contents'))
    );
  }

  activateTab = (tab) => {
    this.activeTab = tab;
  };
}
