import { Injectable } from '@angular/core';
import { Subject } from 'rxjs';
import { IITemLimits, IItemUpdateWithMode } from '../models';

@Injectable({
  providedIn: 'root',
})
export class TedCanvasService {
  onUpdate = new Subject<IItemUpdateWithMode>();
  onValidateBoundaries = new Subject<boolean>();
  onCalculateLimits = new Subject<IITemLimits>();

  constructor() {}
}
