import { CdkDrag, CdkDragMove } from '@angular/cdk/drag-drop';
import { Component, OnDestroy, OnInit, ViewChild, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { fabric } from 'fabric';
import { cloneDeep } from 'lodash';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { Subscription, fromEvent } from 'rxjs';
import { CanvasState } from '../../models/canvas-state';
import { ClearZone } from '../../models/clear-zone';
import { Shape, ShapeType } from '../../models/shape';
import { ITEDSection, ItemToAddOrEdit } from '../../models/ted-state';
import { OlcTedPublicTemplateEditorService } from '../../services/olc-ted-public-template-editor.service';
import { OlcTedPublicTemplateRefreshService } from '../../services/olc-ted-public-template-refresh.service';
import { uniqueID } from '../../utils/olc-ted-public-utilities.utils';
import { ModalsUtilitiesService } from './../../../../../../blocks/services/modals-utilities.service';
import { clearZonesAndAlertsColors } from './../../constants/clear-zones-and-alerts-colors';
import { IItemUpdateWithMode, ItemCorner, ItemRect, ItemUpdateMode, UserAction } from './models';
import { TedCanvasService } from './services/ted-canvas.service';
import {
  degreesToRadians,
  getBottomLeftPoint,
  getBottomRightPoint,
  getDistanceBetweenTwoPoints,
  getTopLeftPoint,
  getTopRightPoint,
  keepTextOrImageInsideCanvasForScaling,
} from './utils';

@Component({
  selector: 'app-TED-canvas',
  templateUrl: './TED-canvas.component.html',
  styleUrls: ['./TED-canvas.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class TEDCanvasComponent implements OnInit, OnDestroy {
  @ViewChild(PerfectScrollbarDirective) perfectScrollbar: PerfectScrollbarDirective;
  @ViewChild(CdkDrag) ckdDrag: CdkDrag;

  canvasState: CanvasState = null;
  fabricCanvas: fabric.Canvas = null;

  allowCanvasDragging = true;

  magnetMarginInPx = 10;

  cursorPosition = { left: '0px', top: '0px' };
  editingTextParts: string[] = [];

  outOfBoundsThresholdInPx = 96;

  temporaryITem: Shape = null;

  subscriptions: Subscription[] = [];

  constructor(
    private templateEditorService: OlcTedPublicTemplateEditorService,
    private templateRefreshService: OlcTedPublicTemplateRefreshService,
    private translateService: TranslateService,
    private tedCanvasService: TedCanvasService,
    private modalsUtilitiesService: ModalsUtilitiesService
  ) {}

  ngOnInit() {
    this.subscriptions.push(
      this.templateEditorService.canvasState$.subscribe(async (canvasState) => {
        this.canvasState = canvasState;
        await this.draw(this.canvasState);
      }),
      this.templateEditorService.onReset.subscribe(() => this.resetZoomingDraggingAndScrolling()),
      this.tedCanvasService.onUpdate.subscribe(async (itemUpdate: IItemUpdateWithMode) => {
        await this.updateCurrentItemTemporarily(itemUpdate);

        if (itemUpdate.mode === ItemUpdateMode.Delete) return;

        const selectedItem = this.fabricCanvas.getActiveObject();

        this.calculateMinAndMaxItemDimensions(selectedItem);

        const itemCrossesCanvasBoundaries = this.itemCrossesCanvasBoundaries(selectedItem);
        this.tedCanvasService.onValidateBoundaries.next(!itemCrossesCanvasBoundaries);
      })
    );

    this.initFabricCanvas();
    this.addFabricCanvasEvents();
    this.addShortcutsKeyboardAndMouseEvent();
  }

  initFabricCanvas() {
    this.fabricCanvas = new fabric.Canvas('template-canvas', {
      selection: false,
      skipOffscreen: true,
      uniformScaling: false,
      uniScaleKey: 'shiftKey',
    });
    this.correctCanvasWidthAndHeight();
    this.moveRotationControlToTopLeft();
  }

  correctCanvasWidthAndHeight() {
    this.fabricCanvas.getWidth = () => {
      const pageGroup = this.getPageGroup();
      if (!pageGroup) return 0;

      return this.addOutOfBoundsThresholdTo(pageGroup.getScaledWidth(), 2);
    };

    this.fabricCanvas.getHeight = () => {
      const pageGroup = this.getPageGroup();
      if (!pageGroup) return 0;

      return this.addOutOfBoundsThresholdTo(pageGroup.getScaledHeight(), 2);
    };
  }

  moveRotationControlToTopLeft() {
    fabric.Object.prototype.controls.mtr.x = -0.5;
    fabric.Object.prototype.controls.mtr.y = -0.5;
  }

  itemCrossesCanvasBoundaries(item: fabric.Object): boolean {
    const coordsPoints = item.getCoords();
    const checkingMarginInPx = 1;

    const canvasBoundariesObject = new ItemRect({
      left: -checkingMarginInPx,
      top: -checkingMarginInPx,
      width: this.fabricCanvas.getWidth() + checkingMarginInPx,
      height: this.fabricCanvas.getHeight() + checkingMarginInPx,
      originX: 'left',
      originY: 'top',
      scaleX: this.canvasState.scale,
      scaleY: this.canvasState.scale,
      transparentCorners: true,
      id: null,
      type: ShapeType.Text,
    });

    return !coordsPoints.every((point) => canvasBoundariesObject.containsPoint(point));
  }

  async updateCurrentItemTemporarily(itemUpdate: IItemUpdateWithMode) {
    const updatedCanvasState = cloneDeep(this.canvasState);

    if (itemUpdate.mode === ItemUpdateMode.Edit) {
      const selectedShapeId = (this.fabricCanvas.getActiveObject() as ItemRect)?.id;
      const selectedShapeIndex = updatedCanvasState.shapes.findIndex((shape) => shape.id === selectedShapeId);

      if (selectedShapeIndex !== -1) {
        updatedCanvasState.shapes[selectedShapeIndex].x = itemUpdate.left;
        updatedCanvasState.shapes[selectedShapeIndex].y = itemUpdate.top;
        updatedCanvasState.shapes[selectedShapeIndex].w = itemUpdate.width;
        updatedCanvasState.shapes[selectedShapeIndex].h = itemUpdate.height;
        updatedCanvasState.shapes[selectedShapeIndex].rotate = itemUpdate.angle;

        updatedCanvasState.selection = updatedCanvasState.shapes[selectedShapeIndex];
      } else {
        this.temporaryITem.x = itemUpdate.left;
        this.temporaryITem.y = itemUpdate.top;
        this.temporaryITem.w = itemUpdate.width;
        this.temporaryITem.h = itemUpdate.height;
        this.temporaryITem.rotate = itemUpdate.angle;

        updatedCanvasState.shapes.push(this.temporaryITem);

        updatedCanvasState.selection = this.temporaryITem;
      }
    } else if (itemUpdate.mode === ItemUpdateMode.Add) {
      this.temporaryITem = new Shape({
        x: itemUpdate.left,
        y: itemUpdate.top,
        w: itemUpdate.width,
        h: itemUpdate.height,
        rotate: itemUpdate.angle,
        id: uniqueID(),
        title: '',
        page: this.templateEditorService.currentDisplayPage,
        section: this.templateEditorService.currentSection,
        type: ShapeType.Text,
        texts: [],
        images: [],
        class: '',
      });

      updatedCanvasState.shapes.push(this.temporaryITem);
      updatedCanvasState.selection = this.temporaryITem;
    } else if (itemUpdate.mode === ItemUpdateMode.Delete) {
      updatedCanvasState.shapes = updatedCanvasState.shapes.filter((shape) => shape.id !== this.temporaryITem?.id);
      updatedCanvasState.selection = null;
    }

    updatedCanvasState.isClean = false;

    await this.draw(updatedCanvasState);
  }

  calculateMinAndMaxItemDimensions(activeElement: fabric.Object | null) {
    if (!activeElement) return;

    const { top, left, angle } = activeElement;
    const width = activeElement.getScaledWidth();
    const height = activeElement.getScaledHeight();

    const canvasWidth = this.fabricCanvas.getWidth();
    const canvasHeight = this.fabricCanvas.getHeight();

    const topLeftPoint = getTopLeftPoint(activeElement);
    const topRightPoint = getTopRightPoint(activeElement);
    const bottomLeftPoint = getBottomLeftPoint(activeElement);

    if (angle === 0 || angle === 360) {
      this.setMinAndMaxItemDimensionsInShape(
        0,
        canvasWidth - width,
        0,
        canvasHeight - height,
        0,
        canvasWidth - left,
        0,
        canvasHeight - top
      );

      return;
    }

    if (angle === 90) {
      this.setMinAndMaxItemDimensionsInShape(
        height,
        canvasWidth,
        0,
        canvasHeight - width,
        0,
        canvasHeight - top,
        0,
        left
      );

      return;
    }

    if (angle === 180) {
      this.setMinAndMaxItemDimensionsInShape(width, canvasWidth, height, canvasHeight, 0, left, 0, top);

      return;
    }

    if (angle === 270) {
      this.setMinAndMaxItemDimensionsInShape(
        0,
        canvasWidth - height,
        width,
        canvasHeight,
        0,
        top,
        0,
        canvasWidth - left
      );

      return;
    }

    if (angle > 0 && angle < 90) {
      const thetaInDegrees = 90 - angle;
      const oppositeToTheta = Math.sin(degreesToRadians(thetaInDegrees)) * width;
      const oppositeToRotationAngle = Math.sin(degreesToRadians(angle)) * height;
      const verticalHeightToBottom =
        Math.cos(degreesToRadians(angle)) * height + Math.cos(degreesToRadians(thetaInDegrees)) * width;

      const intersectionPointWithCanvasRightEdge = new fabric.Point(canvasWidth, topLeftPoint.y);

      const distanceToRightEdge = getDistanceBetweenTwoPoints(topLeftPoint, intersectionPointWithCanvasRightEdge);
      const maxWidthForUpperEdge = distanceToRightEdge / Math.sin(degreesToRadians(90 - angle));

      const intersectionPointWithCanvasBottomEdge = new fabric.Point(bottomLeftPoint.x, canvasHeight);

      const distanceToBottomEdge = getDistanceBetweenTwoPoints(bottomLeftPoint, intersectionPointWithCanvasBottomEdge);
      const maxWidthForLowerEdge = distanceToBottomEdge / Math.cos(degreesToRadians(90 - angle));

      const maxWidth = Math.min(maxWidthForUpperEdge, maxWidthForLowerEdge);

      const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, topLeftPoint.y);
      const distanceToLeftEdge = getDistanceBetweenTwoPoints(topLeftPoint, intersectionPointWithCanvasLeftEdge);
      const maxHeightForLeftEdge = distanceToLeftEdge / Math.cos(degreesToRadians(90 - angle));

      const topRightProjectionOnCanvasBottomEdge = new fabric.Point(topRightPoint.x, canvasHeight);
      const distanceToBottomEdgeForHeight = getDistanceBetweenTwoPoints(
        topRightPoint,
        topRightProjectionOnCanvasBottomEdge
      );

      const maxHeightForRightEdge = distanceToBottomEdgeForHeight / Math.sin(degreesToRadians(90 - angle));

      const maxHeight = Math.min(maxHeightForLeftEdge, maxHeightForRightEdge);

      this.setMinAndMaxItemDimensionsInShape(
        oppositeToRotationAngle,
        canvasWidth - oppositeToTheta,
        0,
        canvasHeight - verticalHeightToBottom,
        0,
        maxWidth,
        0,
        maxHeight
      );

      return;
    }

    if (angle > 90 && angle < 180) {
      const thetaInDegrees = angle - 90;
      const oppositeToTheta = Math.sin(degreesToRadians(thetaInDegrees)) * height;
      const neighborToTheta = Math.cos(degreesToRadians(thetaInDegrees)) * height;
      const horizontalToLeft = neighborToTheta + Math.sin(degreesToRadians(thetaInDegrees)) * width;
      const verticalToBottom = Math.cos(degreesToRadians(thetaInDegrees)) * width;

      const topLeftPointProjectionOnCanvasBottomEdge = new fabric.Point(topLeftPoint.x, canvasHeight);

      const distanceToBottomEdge = getDistanceBetweenTwoPoints(topLeftPoint, topLeftPointProjectionOnCanvasBottomEdge);
      const maxWidthForLowerEdge = distanceToBottomEdge / Math.sin(degreesToRadians(180 - angle));

      const intersectionPointWithCanvasLeftEdge = new fabric.Point(0, bottomLeftPoint.y);

      const distanceToLeftEdge = getDistanceBetweenTwoPoints(bottomLeftPoint, intersectionPointWithCanvasLeftEdge);
      const maxWidthForUpperEdge = distanceToLeftEdge / Math.cos(degreesToRadians(180 - angle));

      const maxWidth = Math.min(maxWidthForUpperEdge, maxWidthForLowerEdge);

      const topRightProjectionOnCanvasLeftEdge = new fabric.Point(0, topRightPoint.y);
      const distanceToLeftEdgeForTopRightPoint = getDistanceBetweenTwoPoints(
        topRightPoint,
        topRightProjectionOnCanvasLeftEdge
      );

      const maxHeightForLeftEdge = distanceToLeftEdgeForTopRightPoint / Math.sin(degreesToRadians(180 - angle));

      const topLeftProjectionOnCanvasTopEdge = new fabric.Point(topLeftPoint.x, 0);

      const distanceToTopEdgeForHeight = getDistanceBetweenTwoPoints(topLeftPoint, topLeftProjectionOnCanvasTopEdge);

      const maxHeightForRightEdge = distanceToTopEdgeForHeight / Math.cos(degreesToRadians(180 - angle));

      const maxHeight = Math.min(maxHeightForLeftEdge, maxHeightForRightEdge);

      this.setMinAndMaxItemDimensionsInShape(
        horizontalToLeft,
        canvasWidth,
        oppositeToTheta,
        canvasHeight - verticalToBottom,
        0,
        maxWidth,
        0,
        maxHeight
      );

      return;
    }

    if (angle > 180 && angle < 270) {
      const horizontalToRight = Math.sin(degreesToRadians(angle - 180)) * height;
      const horizontalToLeft = Math.sin(degreesToRadians(270 - angle)) * width;
      const verticalToTop =
        Math.cos(degreesToRadians(270 - angle)) * width + Math.sin(degreesToRadians(270 - angle)) * height;

      const topLeftPointProjectionOnCanvasLeftEdge = new fabric.Point(0, topLeftPoint.y);

      const distanceToLeftEdge = getDistanceBetweenTwoPoints(topLeftPoint, topLeftPointProjectionOnCanvasLeftEdge);
      const maxWidthForLowerEdge = distanceToLeftEdge / Math.sin(degreesToRadians(270 - angle));

      const bottomLeftPointProjectionOnCanvasTopEdge = new fabric.Point(bottomLeftPoint.x, 0);

      const distanceToTopEdge = getDistanceBetweenTwoPoints(bottomLeftPoint, bottomLeftPointProjectionOnCanvasTopEdge);
      const maxWidthForUpperEdge = distanceToTopEdge / Math.cos(degreesToRadians(270 - angle));

      const maxWidth = Math.min(maxWidthForUpperEdge, maxWidthForLowerEdge);

      const topLeftProjectionOnCanvasRightEdge = new fabric.Point(canvasWidth, topLeftPoint.y);

      const distanceToRightEdgeForTopLeftPoint = getDistanceBetweenTwoPoints(
        topLeftPoint,
        topLeftProjectionOnCanvasRightEdge
      );

      const maxHeightForLeftEdge = distanceToRightEdgeForTopLeftPoint / Math.cos(degreesToRadians(270 - angle));

      const topRightProjectionOnCanvasTopEdge = new fabric.Point(topRightPoint.x, 0);

      const distanceToTopEdgeForHeight = getDistanceBetweenTwoPoints(topRightPoint, topRightProjectionOnCanvasTopEdge);

      const maxHeightForRightEdge = distanceToTopEdgeForHeight / Math.sin(degreesToRadians(270 - angle));

      const maxHeight = Math.min(maxHeightForLeftEdge, maxHeightForRightEdge);

      this.setMinAndMaxItemDimensionsInShape(
        horizontalToLeft,
        canvasWidth - horizontalToRight,
        verticalToTop,
        canvasHeight,
        0,
        maxWidth,
        0,
        maxHeight
      );

      return;
    }

    if (angle > 270 && angle < 360) {
      const horizontalToRight =
        Math.cos(degreesToRadians(360 - angle)) * width + Math.sin(degreesToRadians(360 - angle)) * height;
      const verticalToTop = Math.sin(degreesToRadians(360 - angle)) * width;
      const verticalToBottom = Math.sin(degreesToRadians(angle - 270)) * height;

      const topLeftPointProjectionOnCanvasTopEdge = new fabric.Point(topLeftPoint.x, 0);

      const distanceToLeftEdge = getDistanceBetweenTwoPoints(topLeftPoint, topLeftPointProjectionOnCanvasTopEdge);
      const maxWidthForUpperEdge = distanceToLeftEdge / Math.sin(degreesToRadians(360 - angle));

      const bottomLeftPointProjectionOnCanvasRightEdge = new fabric.Point(canvasWidth, bottomLeftPoint.y);

      const distanceToRightEdge = getDistanceBetweenTwoPoints(
        bottomLeftPoint,
        bottomLeftPointProjectionOnCanvasRightEdge
      );
      const maxWidthForLowerEdge = distanceToRightEdge / Math.cos(degreesToRadians(360 - angle));

      const maxWidth = Math.min(maxWidthForUpperEdge, maxWidthForLowerEdge);

      const topLeftProjectionOnCanvasBottomEdge = new fabric.Point(topLeftPoint.x, canvasHeight);

      const distanceToBottomEdgeForTopLeftPoint = getDistanceBetweenTwoPoints(
        topLeftPoint,
        topLeftProjectionOnCanvasBottomEdge
      );

      const maxHeightForLeftEdge = distanceToBottomEdgeForTopLeftPoint / Math.cos(degreesToRadians(360 - angle));

      const topRightProjectionOnCanvasRightEdge = new fabric.Point(canvasWidth, topRightPoint.y);

      const distanceToRightEdgeForHeight = getDistanceBetweenTwoPoints(
        topRightPoint,
        topRightProjectionOnCanvasRightEdge
      );

      const maxHeightForRightEdge = distanceToRightEdgeForHeight / Math.sin(degreesToRadians(360 - angle));

      const maxHeight = Math.min(maxHeightForLeftEdge, maxHeightForRightEdge);

      this.setMinAndMaxItemDimensionsInShape(
        0,
        canvasWidth - horizontalToRight,
        verticalToTop,
        canvasHeight - verticalToBottom,
        0,
        maxWidth,
        0,
        maxHeight
      );

      return;
    }
  }

  setMinAndMaxItemDimensionsInShape(
    minX: number,
    maxX: number,
    minY: number,
    maxY: number,
    minW: number,
    maxW: number,
    minH: number,
    maxH: number
  ) {
    this.tedCanvasService.onCalculateLimits.next({
      minLeft: this.removeOutOfBoundsThresholdFrom(minX),
      maxLeft: this.removeOutOfBoundsThresholdFrom(maxX),
      minTop: this.removeOutOfBoundsThresholdFrom(minY),
      maxTop: this.removeOutOfBoundsThresholdFrom(maxY),
      minWidth: minW,
      maxWidth: maxW,
      minHeight: minH,
      maxHeight: maxH,
    });
  }

  addFabricCanvasEvents() {
    this.fabricCanvas.on('selection:created', (options: fabric.IEvent<MouseEvent>) => {
      const selectedElement = options.selected[0] as ItemRect;
      this.updateSelectedItem(selectedElement.id);
      this.allowCanvasDragging = false;
    });

    this.fabricCanvas.on('selection:updated', (options: fabric.IEvent<MouseEvent>) => {
      const selectedElement = options.selected[0] as ItemRect;
      this.updateSelectedItem(selectedElement.id);
      this.allowCanvasDragging = false;
    });

    this.fabricCanvas.on('selection:cleared', () => {
      this.removeSelectedItem();
      this.allowCanvasDragging = true;
    });

    this.fabricCanvas.on('object:modified', (options: fabric.IEvent<MouseEvent>) => {
      this.saveAndApplyChangesForModifiedTextOrImage(options.target as ItemRect);
      this.resetEditingTextData();
    });

    this.fabricCanvas.on('object:moving', (options: fabric.IEvent<MouseEvent>) => {
      const { target, transform } = options;
      const { action, corner } = transform;

      this.handleDraggingWithShiftKey(options);

      this.drawAlignmentLinesAndApplyMagnet(target, action as UserAction, corner as ItemCorner);

      this.keepTextOrImageInsideCanvasForDragging(target);

      this.drawMovingText(target, options.e);

      this.fabricCanvas.renderAll();
    });

    this.fabricCanvas.on('object:scaling', (options: fabric.IEvent<MouseEvent>) => {
      const { target, transform } = options;
      const { action, corner, shiftKey } = transform;

      this.drawAlignmentLinesAndApplyMagnet(target, action as UserAction, corner as ItemCorner, shiftKey);

      keepTextOrImageInsideCanvasForScaling(
        target,
        action as UserAction,
        corner as ItemCorner,
        this.fabricCanvas.getWidth(),
        this.fabricCanvas.getHeight()
      );

      this.drawScalingText(target, options.e);

      this.fabricCanvas.renderAll();
    });

    this.fabricCanvas.on('object:rotating', (options: fabric.IEvent<MouseEvent>) => {
      const { target } = options;

      this.keepTextOrImageInsideCanvasForRotating(target);

      this.drawRotatingText(target, options.e);

      this.fabricCanvas.renderAll();
    });

    this.fabricCanvas.on('mouse:dblclick', (options: fabric.IEvent<MouseEvent>) => {
      const item = options.target as ItemRect;
      this.editItem(item.type);
    });

    this.fabricCanvas.on('mouse:wheel', this.handleZoomingByWheel);
  }

  updateSelectedItem(selectedItemId: string) {
    const selectedItem = this.canvasState.shapes.find((shape) => shape.id === selectedItemId);
    if (!selectedItem) return;

    const updatedCanvasState = { ...this.canvasState };
    updatedCanvasState.selection = selectedItem;
    this.templateEditorService.setCanvasState(updatedCanvasState);

    this.updateSelectionInTree(selectedItemId);
  }

  updateSelectionInTree(itemId: string) {
    this.templateEditorService.tree.deselect_all();
    this.templateEditorService.tree.select_node(itemId);
  }

  removeSelectedItem() {
    const updatedCanvasState = { ...this.canvasState };
    updatedCanvasState.selection = null;
    this.templateEditorService.setCanvasState(updatedCanvasState);

    this.removeSelectionFromTree();
  }

  removeSelectionFromTree() {
    this.templateEditorService.tree.deselect_all();
  }

  handleDraggingWithShiftKey(options: fabric.IEvent<MouseEvent>) {
    if (!options.e.shiftKey) return;

    const movementX = Math.abs(options.e.movementX);
    const movementY = Math.abs(options.e.movementY);

    if (movementX > movementY) {
      options.target.lockMovementY = true;
    } else if (movementY > movementX) {
      options.target.lockMovementX = true;
    }
  }

  saveAndApplyChangesForModifiedTextOrImage(activeElement: ItemRect) {
    const { id, left, top, angle } = activeElement;

    const indexToUpdate = this.canvasState.shapes.findIndex((shape) => shape.id === id);
    if (indexToUpdate === -1) return;

    const updatedCanvasState = { ...this.canvasState };
    updatedCanvasState.shapes[indexToUpdate].x = this.removeOutOfBoundsThresholdFrom(left);
    updatedCanvasState.shapes[indexToUpdate].y = this.removeOutOfBoundsThresholdFrom(top);
    updatedCanvasState.shapes[indexToUpdate].w = activeElement.getScaledWidth();
    updatedCanvasState.shapes[indexToUpdate].h = activeElement.getScaledHeight();
    updatedCanvasState.shapes[indexToUpdate].rotate = angle;
    updatedCanvasState.selection = updatedCanvasState.shapes[indexToUpdate];

    this.templateRefreshService.refreshBackground(updatedCanvasState);
  }

  drawMovingText(activeElement: fabric.Object, event: MouseEvent) {
    const { left, top } = activeElement;

    const convertedTop = this.templateEditorService.convertPixelTo(
      this.removeOutOfBoundsThresholdFrom(top),
      this.templateEditorService.defaultUnit
    );

    const convertedLeft = this.templateEditorService.convertPixelTo(
      this.removeOutOfBoundsThresholdFrom(left),
      this.templateEditorService.defaultUnit
    );

    this.editingTextParts = [
      `${this.translateService.instant('admin-olc-templates.add-item-top-label-abbreviation')}: ${convertedTop} ${
        this.templateEditorService.defaultUnit
      }`,
      `${this.translateService.instant('admin-olc-templates.add-item-left-label-abbreviation')}: ${convertedLeft} ${
        this.templateEditorService.defaultUnit
      }`,
    ];

    this.cursorPosition = { left: event.clientX + 10 + 'px', top: event.clientY + 10 + 'px' };
  }

  drawScalingText(activeElement: fabric.Object, event: MouseEvent) {
    this.editingTextParts = [
      `${this.translateService.instant(
        'admin-olc-templates.add-item-width-label-abbreviation'
      )}: ${this.templateEditorService.convertPixelTo(
        activeElement.getScaledWidth(),
        this.templateEditorService.defaultUnit
      )} ${this.templateEditorService.defaultUnit}`,
      `${this.translateService.instant(
        'admin-olc-templates.add-item-height-label-abbreviation'
      )}: ${this.templateEditorService.convertPixelTo(
        activeElement.getScaledHeight(),
        this.templateEditorService.defaultUnit
      )} ${this.templateEditorService.defaultUnit}`,
    ];

    this.cursorPosition = { left: event.clientX + 10 + 'px', top: event.clientY + 10 + 'px' };
  }

  drawRotatingText(activeElement: fabric.Object, event: MouseEvent) {
    this.editingTextParts = [`${activeElement.angle.toFixed(2)}°`];
    this.cursorPosition = { left: event.clientX + 10 + 'px', top: event.clientY + 10 + 'px' };
  }

  resetEditingTextData() {
    this.editingTextParts = [];
    this.cursorPosition = { top: '0px', left: '0px' };
  }

  editItem(itemType: ShapeType | undefined) {
    const isText = itemType === ShapeType.Text;
    const isImage = itemType === ShapeType.Image;

    if (isText) {
      this.templateEditorService.onEditText.next();
      return;
    }

    if (isImage) {
      this.templateEditorService.onEditImage.next();
      return;
    }

    if (this.templateEditorService.isPageSelected) {
      this.templateEditorService.onEditBodyText.next();
      return;
    }

    if (this.templateEditorService.isSectionSelected) this.templateEditorService.onEditBackground.next();
  }

  addShortcutsKeyboardAndMouseEvent() {
    this.subscriptions.push(fromEvent(document, 'keydown').subscribe(this.handleKeyDown));
  }

  handleKeyDown = (event: KeyboardEvent) => {
    if (this.modalsUtilitiesService.isAnyModalOpened()) return;

    const key = event.key.toLowerCase();

    if (event.ctrlKey || event.metaKey) {
      if (event.shiftKey && key === 'z') {
        this.preventEventDefaultsAndPropagation(event);
        document.getElementById('olcted-redo')?.click();
      }

      if (!event.shiftKey && key === 'z') {
        this.preventEventDefaultsAndPropagation(event);
        document.getElementById('olcted-undo')?.click();
      }

      if (key === 's') {
        this.preventEventDefaultsAndPropagation(event);
        document.getElementById('olcted-save-template')?.click();
      }

      if (key === 'y') {
        this.preventEventDefaultsAndPropagation(event);
        document.getElementById('olcted-redo')?.click();
      }

      if (key === 'c') {
        this.preventEventDefaultsAndPropagation(event);
        document.getElementById('copy-selected')?.click();
      }

      if (key === 'v') {
        this.preventEventDefaultsAndPropagation(event);
        document.getElementById('paste-selected')?.click();
      }

      if (key === 'arrowleft') {
        if (!this.canvasState.selection) return;

        this.preventEventDefaultsAndPropagation(event);

        const updatedCanvasState = { ...this.canvasState };
        updatedCanvasState.selection.x -= 2.83;
        this.templateRefreshService.refreshBackground(updatedCanvasState);
      }

      if (key === 'arrowright') {
        if (!this.canvasState.selection) return;

        this.preventEventDefaultsAndPropagation(event);

        const updatedCanvasState = { ...this.canvasState };
        updatedCanvasState.selection.x += 2.83;
        this.templateRefreshService.refreshBackground(updatedCanvasState);
      }

      if (key === 'arrowup') {
        if (!this.canvasState.selection) return;

        this.preventEventDefaultsAndPropagation(event);

        const updatedCanvasState = { ...this.canvasState };
        updatedCanvasState.selection.y -= 2.83;
        this.templateRefreshService.refreshBackground(updatedCanvasState);
      }

      if (key === 'arrowdown') {
        if (!this.canvasState.selection) return;

        this.preventEventDefaultsAndPropagation(event);

        const updatedCanvasState = { ...this.canvasState };
        updatedCanvasState.selection.y += 2.83;
        this.templateRefreshService.refreshBackground(updatedCanvasState);
      }
    }

    if (key === 'enter') {
      this.preventEventDefaultsAndPropagation(event);

      const selectedItemType = this.canvasState.selection?.type;
      this.editItem(selectedItemType);
    }

    if (key === 'delete') {
      this.preventEventDefaultsAndPropagation(event);
      this.templateEditorService.deleteSelection(this.templateRefreshService);
    }

    if (key === 't') {
      this.preventEventDefaultsAndPropagation(event);
      this.templateEditorService.openAddOrEditItemModal(ItemToAddOrEdit.Text, false);
    }

    if (key === 'i') {
      this.preventEventDefaultsAndPropagation(event);
      this.templateEditorService.openAddOrEditItemModal(ItemToAddOrEdit.Image, false);
    }

    if (key === 'b') {
      this.preventEventDefaultsAndPropagation(event);
      this.templateEditorService.openAddOrEditItemModal(ItemToAddOrEdit.Background, false);
    }

    if (key === 'a') {
      this.preventEventDefaultsAndPropagation(event);
      document.getElementById('olcted-pdf-preview')?.click();
    }

    if (key === 'pageup') {
      if (this.templateEditorService.currentDisplayPage <= 0) return;

      this.preventEventDefaultsAndPropagation(event);

      this.templateEditorService.currentDisplayPage -= 1;

      this.templateEditorService.tree.deselect_all();

      this.templateEditorService.tree.select_node(
        `S${this.templateEditorService.currentSection}P${this.templateEditorService.currentDisplayPage}`
      );

      this.templateRefreshService.refreshBackground(this.canvasState);
    }

    if (key === 'pagedown') {
      if (
        this.templateEditorService.currentDisplayPage >=
        this.canvasState.sections[this.templateEditorService.currentSection].pages - 1
      )
        return;

      this.preventEventDefaultsAndPropagation(event);

      this.templateEditorService.currentDisplayPage += 1;

      this.templateEditorService.tree.deselect_all();

      this.templateEditorService.tree.select_node(
        `S${this.templateEditorService.currentSection}P${this.templateEditorService.currentDisplayPage}`
      );

      this.templateRefreshService.refreshBackground(this.canvasState);
    }

    if (key === '+') {
      this.preventEventDefaultsAndPropagation(event);

      this.templateEditorService.zoomIn();
    }

    if (key === '-') {
      this.preventEventDefaultsAndPropagation(event);

      this.templateEditorService.zoomOut();
    }

    if (key === 'home') {
      this.preventEventDefaultsAndPropagation(event);

      this.templateEditorService.onReset.next();
    }
  };

  handleZoomingByWheel = (options: fabric.IEvent<WheelEvent>) => {
    if (this.modalsUtilitiesService.isAnyModalOpened()) return;

    if (!options.e.ctrlKey && !options.e.metaKey) return;

    this.preventEventDefaultsAndPropagation(options.e);

    if (options.e.deltaY < 0) {
      this.templateEditorService.zoomIn();
      return;
    }

    this.templateEditorService.zoomOut();
  };

  preventEventDefaultsAndPropagation(event: Event) {
    event.preventDefault();
    event.stopPropagation();
  }

  resetZoomingDraggingAndScrolling() {
    const updatedCanvasState = { ...this.canvasState };
    updatedCanvasState.scale = 1;

    this.templateEditorService.setCanvasState(updatedCanvasState, true);

    this.ckdDrag.reset();

    this.perfectScrollbar.scrollToTop();
    this.perfectScrollbar.scrollToLeft();
  }

  onDragMoved(event: CdkDragMove) {
    this.perfectScrollbar.update();
    this.preventDraggingInNegativeXAndYDirections(event);
  }

  preventDraggingInNegativeXAndYDirections(event: CdkDragMove) {
    const draggableElement = event.source.element.nativeElement;

    const currentTransform = draggableElement.style.transform;
    const match = currentTransform.match(/translate3d\(([^,]+),([^,]+),[^,]+\)/);

    const translateXValue = match ? parseFloat(match[1]) : 0;
    const translateYValue = match ? parseFloat(match[2]) : 0;

    if (translateXValue >= 0 && translateYValue >= 0) return;

    draggableElement.style.transform = `translate3d(${translateXValue >= 0 ? translateXValue : 0}px, ${
      translateYValue >= 0 ? translateYValue : 0
    }px, 0px)`;
  }

  onDragStarted() {
    this.setPageGroupHoverCursor('grabbing');
  }

  onDragEnded() {
    this.setPageGroupHoverCursor('default');
  }

  setPageGroupHoverCursor(value: string) {
    const pageGroup = this.getPageGroup();
    if (!pageGroup) return;

    pageGroup.hoverCursor = value;
  }

  async draw(canvasState: CanvasState) {
    if (!canvasState || !this.perfectScrollbar || canvasState.isClean) return;

    const currentSection = canvasState.sections[this.templateEditorService.currentSection];

    if (!currentSection) return;

    const canvasWidth = this.addOutOfBoundsThresholdTo(currentSection.width, 2) + 15;
    const canvasHeight = this.addOutOfBoundsThresholdTo(currentSection.height, 2) + 15;

    this.fabricCanvas.clear();

    this.fabricCanvas.setWidth(canvasWidth * canvasState.scale);
    this.fabricCanvas.setHeight(canvasHeight * canvasState.scale);
    this.fabricCanvas.setZoom(canvasState.scale);

    const pageGroup = new fabric.Group([], {
      name: 'pageGroup',
      left: this.addOutOfBoundsThresholdTo(0),
      top: this.addOutOfBoundsThresholdTo(0),
      selectable: false,
      hasControls: false,
      hasRotatingPoint: false,
      hasBorders: false,
      hoverCursor: 'default',
    });

    const pageBoundary = new fabric.Rect({
      left: this.addOutOfBoundsThresholdTo(0),
      top: this.addOutOfBoundsThresholdTo(0),
      width: currentSection.width,
      height: currentSection.height,
      fill: 'transparent',
      stroke: '#000000',
      strokeWidth: 1,
      shadow: new fabric.Shadow({ color: '#000', blur: 10, offsetX: 6, offsetY: 6 }),
      selectable: false,
    });

    pageGroup.addWithUpdate(pageBoundary);

    const backgroundImage = await this.loadFabricImageFromURL(canvasState.backgroundImage.src);
    backgroundImage.set({
      left: this.addOutOfBoundsThresholdTo(0),
      top: this.addOutOfBoundsThresholdTo(0),
      selectable: false,
    });
    pageGroup.addWithUpdate(backgroundImage);

    this.createPageMarginLines(pageGroup, currentSection);

    const selectedPageClearZones: ClearZone[] = [];

    canvasState.clearZones.forEach((clearZone) => {
      if (clearZone.section != this.templateEditorService.currentSection) return;
      if (clearZone.page != this.templateEditorService.currentDisplayPage) return;

      selectedPageClearZones.push(clearZone);

      const clearZoneRect = this.createClearZoneRect(clearZone);
      pageGroup.addWithUpdate(clearZoneRect);
    });

    this.fabricCanvas.add(pageGroup);

    canvasState.shapes.forEach((shape) => {
      if (shape.page != this.templateEditorService.currentDisplayPage) return;
      if (shape.section != this.templateEditorService.currentSection) return;

      const shapeRect = this.createShapeRectAndCheckIntersectingClearZones(shape, selectedPageClearZones);

      this.fabricCanvas.add(shapeRect);

      const selectedShape = canvasState.selection;
      if (selectedShape && selectedShape.id === shape.id) this.fabricCanvas.setActiveObject(shapeRect);
    });

    this.fabricCanvas.renderAll();
  }

  getPageGroup() {
    return this.fabricCanvas.getObjects('group').find((group) => group.name === 'pageGroup');
  }

  createPageMarginLines(pageGroup, currentSection) {
    const left = this.addOutOfBoundsThresholdTo(currentSection.leftMargin);
    const top = this.addOutOfBoundsThresholdTo(currentSection.topMargin);
    const right = this.addOutOfBoundsThresholdTo(currentSection.width - currentSection.rightMargin);
    const bottom = this.addOutOfBoundsThresholdTo(currentSection.height - currentSection.bottomMargin);
    const height = this.addOutOfBoundsThresholdTo(currentSection.height);
    const width = this.addOutOfBoundsThresholdTo(currentSection.width);
    const zero = this.addOutOfBoundsThresholdTo(0);

    pageGroup.addWithUpdate(this.createMarginLine(left, zero, left, height));

    pageGroup.addWithUpdate(this.createMarginLine(right, zero, right, height));

    pageGroup.addWithUpdate(this.createMarginLine(zero, top, width, top));

    pageGroup.addWithUpdate(this.createMarginLine(zero, bottom, width, bottom));
  }

  createPageMarginsRect(currentSection: ITEDSection) {
    return new fabric.Rect({
      left: this.addOutOfBoundsThresholdTo(currentSection.leftMargin),
      top: this.addOutOfBoundsThresholdTo(currentSection.topMargin),
      width: currentSection.width - currentSection.leftMargin - currentSection.rightMargin,
      height: currentSection.height - currentSection.topMargin - currentSection.bottomMargin,
      fill: 'rgba(214, 248, 255, 0.3)',
      selectable: false,
    });
  }

  createShapeRectAndCheckIntersectingClearZones(shape: Shape, activeClearZones: ClearZone[]) {
    const shapeRect = this.createShapeRect(shape);

    const intersectingClearZones = this.getClearZonesIntersectingWithShape(shapeRect, activeClearZones);

    const isForbidden = !!intersectingClearZones.find((c) => c.type === 'forbidden-zone');

    if (isForbidden) {
      shapeRect.set({
        fill: clearZonesAndAlertsColors['forbidden-zone-alert']['background-color'],
        stroke: clearZonesAndAlertsColors['forbidden-zone-alert']['border-color'],
      });

      return shapeRect;
    }

    const isWarning = !!intersectingClearZones.find((c) => c.type === 'warning-zone');

    if (isWarning) {
      shapeRect.set({
        fill: clearZonesAndAlertsColors['warning-zone-alert']['background-color'],
        stroke: clearZonesAndAlertsColors['warning-zone-alert']['border-color'],
      });

      return shapeRect;
    }

    shapeRect.set({
      fill: clearZonesAndAlertsColors['no-issue-zone-alert']['background-color'],
      stroke: clearZonesAndAlertsColors['no-issue-zone-alert']['border-color'],
    });

    return shapeRect;
  }

  createShapeRect(shape: Shape) {
    return new ItemRect({
      left: this.addOutOfBoundsThresholdTo(shape.x),
      top: this.addOutOfBoundsThresholdTo(shape.y),
      width: shape.w,
      height: shape.h,
      fill: shape.fillStyle,
      stroke: shape.strokeStyle,
      strokeWidth: 0.5,
      strokeDashArray: [5, 3],
      selectable: true,
      hasControls: true,
      hasRotatingPoint: true,
      lockScalingFlip: true,
      lockSkewingX: true,
      lockSkewingY: true,
      originX: 'left',
      originY: 'top',
      scaleX: 1,
      scaleY: 1,
      transparentCorners: false,
      cornerStrokeColor: '#0c63e4',
      cornerColor: '#e2eefd',
      cornerSize: 8,
      id: shape.id,
      type: shape.type,
      objectCaching: false,
      angle: shape.rotate,
      data: { lastValidAngle: shape.rotate },
      centeredRotation: false,
      borderScaleFactor: 1,
    });
  }

  createClearZoneRect(clearZoneInstance: ClearZone) {
    return new fabric.Rect({
      left: this.addOutOfBoundsThresholdTo(clearZoneInstance.x),
      top: this.addOutOfBoundsThresholdTo(clearZoneInstance.y),
      width: clearZoneInstance.w,
      height: clearZoneInstance.h,
      fill: clearZonesAndAlertsColors[clearZoneInstance.type]['background-color'],
      stroke: clearZonesAndAlertsColors[clearZoneInstance.type]['border-color'],
      strokeWidth: 2,
      strokeDashArray: [5, 3],
      selectable: false,
      angle: clearZoneInstance.rotate,
      data: { lastValidAngle: clearZoneInstance.rotate },
      originX: 'left',
      originY: 'top',
      scaleX: 1,
      scaleY: 1,
    });
  }

  getClearZonesIntersectingWithShape(shapeRect: fabric.Rect, clearZones: ClearZone[]) {
    return clearZones.filter((clearZone) => {
      const clearZoneRect = this.createClearZoneRect(clearZone);
      return shapeRect.intersectsWithObject(clearZoneRect);
    });
  }

  keepTextOrImageInsideCanvasForDragging(activeElement: fabric.Object) {
    const rotationAngle = activeElement.angle;

    const canvasWidth = this.fabricCanvas.getWidth();
    const canvasHeight = this.fabricCanvas.getHeight();

    if (rotationAngle >= 0 && rotationAngle <= 90) {
      const thetaInDegrees = 90 - rotationAngle;
      const oppositeToTheta = Math.sin(degreesToRadians(thetaInDegrees)) * activeElement.getScaledWidth();
      const oppositeToRotationAngle = Math.sin(degreesToRadians(rotationAngle)) * activeElement.getScaledHeight();
      const verticalHeightToBottom =
        Math.cos(degreesToRadians(rotationAngle)) * activeElement.getScaledHeight() +
        Math.cos(degreesToRadians(thetaInDegrees)) * activeElement.getScaledWidth();

      if (activeElement.left + oppositeToTheta > canvasWidth) {
        activeElement.set({ left: canvasWidth - oppositeToTheta });
      }

      if (activeElement.left - oppositeToRotationAngle < 0) {
        activeElement.set({ left: oppositeToRotationAngle });
      }

      if (activeElement.top < 0) {
        activeElement.set({ top: 0 });
      }

      if (activeElement.top + verticalHeightToBottom > canvasHeight) {
        activeElement.set({ top: canvasHeight - verticalHeightToBottom });
      }

      return;
    }

    if (rotationAngle > 90 && rotationAngle <= 180) {
      const thetaInDegrees = rotationAngle - 90;
      const oppositeToTheta = Math.sin(degreesToRadians(thetaInDegrees)) * activeElement.getScaledHeight();
      const neighborToTheta = Math.cos(degreesToRadians(thetaInDegrees)) * activeElement.getScaledHeight();
      const horizontalToLeft =
        neighborToTheta + Math.sin(degreesToRadians(thetaInDegrees)) * activeElement.getScaledWidth();
      const verticalToBottom = Math.cos(degreesToRadians(thetaInDegrees)) * activeElement.getScaledWidth();

      if (activeElement.left > canvasWidth) {
        activeElement.set({ left: canvasWidth });
      }

      if (activeElement.left - horizontalToLeft < 0) {
        activeElement.set({ left: horizontalToLeft });
      }

      if (activeElement.top - oppositeToTheta < 0) {
        activeElement.set({ top: oppositeToTheta });
      }

      if (activeElement.top + verticalToBottom > canvasHeight) {
        activeElement.set({ top: canvasHeight - verticalToBottom });
      }

      return;
    }

    if (activeElement.angle > 180 && activeElement.angle <= 270) {
      const horizontalToRight = Math.sin(degreesToRadians(rotationAngle - 180)) * activeElement.getScaledHeight();
      const horizontalToLeft = Math.sin(degreesToRadians(270 - rotationAngle)) * activeElement.getScaledWidth();
      const verticalToTop =
        Math.cos(degreesToRadians(270 - rotationAngle)) * activeElement.getScaledWidth() +
        Math.sin(degreesToRadians(270 - rotationAngle)) * activeElement.getScaledHeight();

      if (activeElement.left + horizontalToRight > canvasWidth) {
        activeElement.set({ left: canvasWidth - horizontalToRight });
      }

      if (activeElement.left - horizontalToLeft < 0) {
        activeElement.set({ left: horizontalToLeft });
      }

      if (activeElement.top > canvasHeight) {
        activeElement.set({ top: canvasHeight });
      }

      if (activeElement.top - verticalToTop < 0) {
        activeElement.set({ top: verticalToTop });
      }

      return;
    }

    if (activeElement.angle > 270 && activeElement.angle <= 360) {
      const horizontalToRight =
        Math.cos(degreesToRadians(360 - rotationAngle)) * activeElement.getScaledWidth() +
        Math.sin(degreesToRadians(360 - rotationAngle)) * activeElement.getScaledHeight();
      const verticalToTop = Math.sin(degreesToRadians(360 - rotationAngle)) * activeElement.getScaledWidth();
      const verticalToBottom = Math.sin(degreesToRadians(rotationAngle - 270)) * activeElement.getScaledHeight();

      if (activeElement.left < 0) {
        activeElement.set({ left: 0 });
      }

      if (activeElement.left + horizontalToRight > canvasWidth) {
        activeElement.set({ left: canvasWidth - horizontalToRight });
      }

      if (activeElement.top - verticalToTop < 0) {
        activeElement.set({ top: verticalToTop });
      }

      if (activeElement.top + verticalToBottom > canvasHeight) {
        activeElement.set({ top: canvasHeight - verticalToBottom });
      }

      return;
    }
  }

  keepTextOrImageInsideCanvasForRotating(activeElement: fabric.Object) {
    const rotationAngle = activeElement.angle;

    const canvasWidth = this.fabricCanvas.getWidth();
    const canvasHeight = this.fabricCanvas.getHeight();

    if (rotationAngle >= 0 && rotationAngle <= 90) {
      const thetaInDegrees = 90 - rotationAngle;
      const oppositeToTheta = Math.sin(degreesToRadians(thetaInDegrees)) * activeElement.getScaledWidth();
      const oppositeToRotationAngle = Math.sin(degreesToRadians(rotationAngle)) * activeElement.getScaledHeight();
      const verticalHeightToBottom =
        Math.cos(degreesToRadians(rotationAngle)) * activeElement.getScaledHeight() +
        Math.cos(degreesToRadians(thetaInDegrees)) * activeElement.getScaledWidth();

      this.handleElementRotation(
        activeElement,
        activeElement.left + oppositeToTheta > canvasWidth ||
          activeElement.left - oppositeToRotationAngle < 0 ||
          activeElement.top < 0 ||
          activeElement.top + verticalHeightToBottom > canvasHeight
      );
      return;
    }

    if (rotationAngle > 90 && rotationAngle <= 180) {
      const thetaInDegrees = rotationAngle - 90;
      const oppositeToTheta = Math.sin(degreesToRadians(thetaInDegrees)) * activeElement.getScaledHeight();
      const neighborToTheta = Math.cos(degreesToRadians(thetaInDegrees)) * activeElement.getScaledHeight();
      const horizontalToLeft =
        neighborToTheta + Math.sin(degreesToRadians(thetaInDegrees)) * activeElement.getScaledWidth();
      const verticalToBottom = Math.cos(degreesToRadians(thetaInDegrees)) * activeElement.getScaledWidth();

      this.handleElementRotation(
        activeElement,
        activeElement.left > canvasWidth ||
          activeElement.left - horizontalToLeft < 0 ||
          activeElement.top - oppositeToTheta < 0 ||
          activeElement.top + verticalToBottom > canvasHeight
      );
      return;
    }

    if (activeElement.angle > 180 && activeElement.angle <= 270) {
      const horizontalToRight = Math.sin(degreesToRadians(rotationAngle - 180)) * activeElement.getScaledHeight();
      const horizontalToLeft = Math.sin(degreesToRadians(270 - rotationAngle)) * activeElement.getScaledWidth();
      const verticalToTop =
        Math.cos(degreesToRadians(270 - rotationAngle)) * activeElement.getScaledWidth() +
        Math.sin(degreesToRadians(270 - rotationAngle)) * activeElement.getScaledHeight();

      this.handleElementRotation(
        activeElement,
        activeElement.left + horizontalToRight > canvasWidth ||
          activeElement.left - horizontalToLeft < 0 ||
          activeElement.top > canvasHeight ||
          activeElement.top - verticalToTop < 0
      );
      return;
    }

    if (activeElement.angle > 270 && activeElement.angle <= 360) {
      const horizontalToRight =
        Math.cos(degreesToRadians(360 - rotationAngle)) * activeElement.getScaledWidth() +
        Math.sin(degreesToRadians(360 - rotationAngle)) * activeElement.getScaledHeight();
      const verticalToTop = Math.sin(degreesToRadians(360 - rotationAngle)) * activeElement.getScaledWidth();
      const verticalToBottom = Math.sin(degreesToRadians(rotationAngle - 270)) * activeElement.getScaledHeight();

      this.handleElementRotation(
        activeElement,
        activeElement.left < 0 ||
          activeElement.left + horizontalToRight > canvasWidth ||
          activeElement.top - verticalToTop < 0 ||
          activeElement.top + verticalToBottom > canvasHeight
      );
      return;
    }
  }

  handleElementRotation(activeElement: fabric.Object, lockRotation: boolean) {
    if (lockRotation) {
      activeElement.lockRotation = true;
      activeElement.set({ angle: activeElement.data.lastValidAngle });
    }

    activeElement.data.lastValidAngle = activeElement.angle;
  }

  drawAlignmentLinesAndApplyMagnet(
    activeElement: fabric.Object,
    action: UserAction,
    corner: ItemCorner,
    shiftKey = false
  ) {
    this.removeOldAlignmentLinesFromCanvas();

    const ActiveElementRects = this.createMagnetRectanglesForActiveElement(activeElement);
    const activeItemPointsRanges = this.createMagnetRangesForActiveElement(activeElement);

    const elementsLinesExceptActiveElement = this.createLinesForTextsAndImagesExceptActiveObject(
      activeElement as ItemRect
    );

    const pageMarginsRectLines = this.createLinesForPageMarginsRect();

    const magnetLines = elementsLinesExceptActiveElement.concat(pageMarginsRectLines);

    const intersectionLines: fabric.Line[] = [];

    ActiveElementRects.forEach((activeElementRect) => {
      magnetLines.forEach((elementLine) => {
        const bothVerticalLines = activeElementRect.data.isVertical && this.isVerticalLine(elementLine);
        const bothHorizontalLines = activeElementRect.data.isHorizontal && this.isHorizontalLine(elementLine);
        const shouldShowLine =
          (bothVerticalLines || bothHorizontalLines) && activeElementRect.intersectsWithObject(elementLine);

        if (!shouldShowLine) return;

        this.applyMagnetOnActiveElement(
          activeElement,
          activeItemPointsRanges,
          elementLine,
          bothVerticalLines,
          action,
          corner,
          shiftKey
        );

        intersectionLines.push(elementLine);
      });
    });

    intersectionLines.forEach((line) => this.fabricCanvas.add(line));
  }

  removeOldAlignmentLinesFromCanvas() {
    this.fabricCanvas.getObjects('line').forEach((line) => this.fabricCanvas.remove(line));
  }

  applyMagnetOnActiveElement(
    activeElement: fabric.Object,
    activeItemPointsRanges,
    elementLine: fabric.Line,
    isVerticalEdge: boolean,
    action: UserAction,
    corner: ItemCorner,
    shiftKey = false
  ) {
    let shouldUpdateLeftX = false;
    let shouldUpdateCenterX = false;
    let shouldUpdateRightX = false;
    let shouldUpdateTopY = false;
    let shouldUpdateCenterY = false;
    let shouldUpdateBottomY = false;

    if (isVerticalEdge) {
      shouldUpdateLeftX =
        elementLine.x1 >= activeItemPointsRanges.leftXRange.minLeftX &&
        elementLine.x1 <= activeItemPointsRanges.leftXRange.maxLeftX;

      shouldUpdateCenterX =
        elementLine.x1 >= activeItemPointsRanges.centerXRange.minCenterX &&
        elementLine.x1 <= activeItemPointsRanges.centerXRange.maxCenterX;

      shouldUpdateRightX =
        elementLine.x1 >= activeItemPointsRanges.rightXRange.minRightX &&
        elementLine.x1 <= activeItemPointsRanges.rightXRange.maxRightX;
    } else {
      shouldUpdateTopY =
        elementLine.y1 >= activeItemPointsRanges.topYRange.minTopY &&
        elementLine.y1 <= activeItemPointsRanges.topYRange.maxTopY;

      shouldUpdateCenterY =
        elementLine.y1 >= activeItemPointsRanges.centerYRange.minCenterY &&
        elementLine.y1 <= activeItemPointsRanges.centerYRange.maxCenterY;

      shouldUpdateBottomY =
        elementLine.y1 >= activeItemPointsRanges.bottomYRange.minBottomY &&
        elementLine.y1 <= activeItemPointsRanges.bottomYRange.maxBottomY;
    }

    if (action === UserAction.Drag) {
      if (isVerticalEdge) {
        if (shouldUpdateCenterX) {
          activeElement.set({
            left: elementLine.x1 - 0.5 * activeElement.getScaledWidth(),
          });
        }

        if (shouldUpdateRightX) {
          activeElement.set({
            left: elementLine.x1 - activeElement.getScaledWidth(),
          });
        }

        if (shouldUpdateLeftX) {
          activeElement.set({
            left: elementLine.x1,
          });
        }
      } else {
        if (shouldUpdateCenterY) {
          activeElement.set({
            top: elementLine.y1 - 0.5 * activeElement.getScaledHeight(),
          });
        }

        if (shouldUpdateBottomY) {
          activeElement.set({
            top: elementLine.y1 - activeElement.getScaledHeight(),
          });
        }

        if (shouldUpdateTopY) {
          activeElement.set({
            top: elementLine.y1,
          });
        }
      }

      return;
    }

    if (action === UserAction.ScaleX) {
      if (corner === ItemCorner.MiddleLeft) {
        if (isVerticalEdge) {
          if (shouldUpdateLeftX) {
            const topRightPoint = this.getScaledPoint(getTopRightPoint(activeElement));
            const newWidth = topRightPoint.x - elementLine.x1;

            activeElement.set({ width: newWidth, scaleX: 1 });
            activeElement.setPositionByOrigin(topRightPoint, 'right', 'top');
          }
        }

        return;
      }

      if (corner === ItemCorner.MiddleRight) {
        if (isVerticalEdge) {
          if (shouldUpdateRightX) {
            const topLeftPoint = this.getScaledPoint(getTopLeftPoint(activeElement));
            const newWidth = elementLine.x1 - topLeftPoint.x;

            activeElement.set({ width: newWidth, scaleX: 1 });
            activeElement.setPositionByOrigin(topLeftPoint, 'left', 'top');
          }
        }

        return;
      }

      return;
    }

    if (action === UserAction.ScaleY) {
      if (corner === ItemCorner.MiddleBottom) {
        if (!isVerticalEdge) {
          if (shouldUpdateBottomY) {
            const topLeftPoint = this.getScaledPoint(getTopLeftPoint(activeElement));
            const newHeight = elementLine.y1 - topLeftPoint.y;

            activeElement.set({ height: newHeight, scaleY: 1 });
            activeElement.setPositionByOrigin(topLeftPoint, 'left', 'top');
          }
        }

        return;
      }

      if (corner === ItemCorner.MiddleTop) {
        if (!isVerticalEdge) {
          if (shouldUpdateTopY) {
            const bottomLeftPoint = this.getScaledPoint(getBottomLeftPoint(activeElement));
            const newHeight = bottomLeftPoint.y - elementLine.y1;

            activeElement.set({ height: newHeight, scaleY: 1 });
            activeElement.setPositionByOrigin(bottomLeftPoint, 'left', 'bottom');
          }
        }

        return;
      }

      return;
    }

    if (action === UserAction.Scale && !shiftKey) {
      if (corner === ItemCorner.BottomRight) {
        if (isVerticalEdge) {
          if (shouldUpdateRightX) {
            const topLeftPoint = this.getScaledPoint(getTopLeftPoint(activeElement));
            const newWidth = elementLine.x1 - topLeftPoint.x;

            activeElement.set({ width: newWidth, scaleX: 1 });
            activeElement.setPositionByOrigin(topLeftPoint, 'left', 'top');
          }
        } else {
          if (shouldUpdateBottomY) {
            const topLeftPoint = this.getScaledPoint(getTopLeftPoint(activeElement));
            const newHeight = elementLine.y1 - topLeftPoint.y;

            activeElement.set({ height: newHeight, scaleY: 1 });
            activeElement.setPositionByOrigin(topLeftPoint, 'left', 'top');
          }
        }

        return;
      }

      if (corner === ItemCorner.TopRight) {
        if (isVerticalEdge) {
          if (shouldUpdateRightX) {
            const bottomLeftPoint = this.getScaledPoint(getBottomLeftPoint(activeElement));
            const newWidth = elementLine.x1 - bottomLeftPoint.x;

            activeElement.set({ width: newWidth, scaleX: 1 });
            activeElement.setPositionByOrigin(bottomLeftPoint, 'left', 'bottom');
          }
        } else {
          if (shouldUpdateTopY) {
            const bottomLeftPoint = this.getScaledPoint(getBottomLeftPoint(activeElement));
            const newHeight = bottomLeftPoint.y - elementLine.y1;

            activeElement.set({ height: newHeight, scaleY: 1 });
            activeElement.setPositionByOrigin(bottomLeftPoint, 'left', 'bottom');
          }
        }

        return;
      }

      if (corner === ItemCorner.BottomLeft) {
        if (isVerticalEdge) {
          if (shouldUpdateLeftX) {
            const topRightPoint = this.getScaledPoint(getTopRightPoint(activeElement));
            const newWidth = topRightPoint.x - elementLine.x1;

            activeElement.set({ width: newWidth, scaleX: 1 });
            activeElement.setPositionByOrigin(topRightPoint, 'right', 'top');
          }
        } else {
          if (shouldUpdateBottomY) {
            const topRightPoint = this.getScaledPoint(getTopRightPoint(activeElement));
            const newHeight = elementLine.y1 - topRightPoint.y;

            activeElement.set({ height: newHeight, scaleY: 1 });
            activeElement.setPositionByOrigin(topRightPoint, 'right', 'top');
          }
        }

        return;
      }

      if (corner === ItemCorner.TopLeft) {
        if (isVerticalEdge) {
          if (shouldUpdateLeftX) {
            const bottomRightPoint = this.getScaledPoint(getBottomRightPoint(activeElement));
            const newWidth = bottomRightPoint.x - elementLine.x1;

            activeElement.set({ width: newWidth, scaleX: 1 });
            activeElement.setPositionByOrigin(bottomRightPoint, 'right', 'bottom');
          }
        } else {
          if (shouldUpdateTopY) {
            const bottomRightPoint = this.getScaledPoint(getBottomRightPoint(activeElement));
            const newHeight = bottomRightPoint.y - elementLine.y1;

            activeElement.set({ height: newHeight, scaleY: 1 });
            activeElement.setPositionByOrigin(bottomRightPoint, 'right', 'bottom');
          }
        }

        return;
      }

      return;
    }
  }

  getScaledPoint(point: fabric.Point) {
    return new fabric.Point(point.x / this.canvasState.scale, point.y / this.canvasState.scale);
  }

  createLinesForTextsAndImagesExceptActiveObject(activeElement: ItemRect): fabric.Line[] {
    return this.fabricCanvas
      .getObjects()
      .filter((obj: ItemRect) => [ShapeType.Text, ShapeType.Image].includes(obj.type) && obj.id !== activeElement.id)
      .reduce((acc, obj: ItemRect) => {
        return acc.concat(this.createItemLines(obj));
      }, []);
  }

  createLinesForPageMarginsRect(): fabric.Line[] {
    const currentSection = this.canvasState.sections[this.templateEditorService.currentSection];
    if (!currentSection) return [];

    const pageMarginsRect = this.createPageMarginsRect(currentSection);
    return this.createItemLines(pageMarginsRect);
  }

  createItemLines(item: fabric.Object) {
    const canvasWidth = this.fabricCanvas.getWidth();
    const canvasHeight = this.fabricCanvas.getHeight();

    const { leftX, centerX, rightX, topY, centerY, bottomY } = this.createItemEdgesPoints(item);

    const lines: fabric.Line[] = [];

    lines.push(this.createLine(leftX, 0, leftX, canvasHeight));
    lines.push(this.createLine(centerX, 0, centerX, canvasHeight));
    lines.push(this.createLine(rightX, 0, rightX, canvasHeight));

    lines.push(this.createLine(0, topY, canvasWidth, topY));
    lines.push(this.createLine(0, centerY, canvasWidth, centerY));
    lines.push(this.createLine(0, bottomY, canvasWidth, bottomY));

    return lines;
  }

  createLine(x1: number, y1: number, x2: number, y2: number) {
    return new fabric.Line([x1, y1, x2, y2], {
      stroke: 'red',
      strokeDashArray: [5, 3],
      strokeWidth: 1,
      selectable: false,
    });
  }

  createMarginLine(x1: number, y1: number, x2: number, y2: number) {
    return new fabric.Line([x1, y1, x2, y2], {
      stroke: '#BFDBFF',
      strokeWidth: 1,
      selectable: false,
    });
  }

  createMagnetRectanglesForActiveElement(item: fabric.Object) {
    const canvasWidth = this.fabricCanvas.getWidth();
    const canvasHeight = this.fabricCanvas.getHeight();

    const { leftX, centerX, rightX, topY, centerY, bottomY } = this.createItemEdgesPoints(item);

    const rects: fabric.Rect[] = [];

    rects.push(this.createRectangleAroundLine(leftX, 0, leftX, canvasHeight));
    rects.push(this.createRectangleAroundLine(centerX, 0, centerX, canvasHeight));
    rects.push(this.createRectangleAroundLine(rightX, 0, rightX, canvasHeight));

    rects.push(this.createRectangleAroundLine(0, topY, canvasWidth, topY));
    rects.push(this.createRectangleAroundLine(0, centerY, canvasWidth, centerY));
    rects.push(this.createRectangleAroundLine(0, bottomY, canvasWidth, bottomY));

    return rects;
  }

  createMagnetRangesForActiveElement(item: fabric.Object) {
    const { leftX, centerX, rightX, topY, centerY, bottomY } = this.createItemEdgesPoints(item);

    const halfMagnetMargin = 0.5 * this.magnetMarginInPx;

    return {
      leftXRange: { minLeftX: leftX - halfMagnetMargin, maxLeftX: leftX + halfMagnetMargin },
      centerXRange: { minCenterX: centerX - halfMagnetMargin, maxCenterX: centerX + halfMagnetMargin },
      rightXRange: { minRightX: rightX - halfMagnetMargin, maxRightX: rightX + halfMagnetMargin },
      topYRange: { minTopY: topY - halfMagnetMargin, maxTopY: topY + halfMagnetMargin },
      centerYRange: { minCenterY: centerY - halfMagnetMargin, maxCenterY: centerY + halfMagnetMargin },
      bottomYRange: { minBottomY: bottomY - halfMagnetMargin, maxBottomY: bottomY + halfMagnetMargin },
    };
  }

  createItemEdgesPoints(item: fabric.Object) {
    const leftX = item.left;
    const centerX = item.left + item.getScaledWidth() / 2;
    const rightX = item.left + item.getScaledWidth();

    const topY = item.top;
    const centerY = item.top + item.getScaledHeight() / 2;
    const bottomY = item.top + item.getScaledHeight();

    return {
      leftX,
      centerX,
      rightX,
      topY,
      centerY,
      bottomY,
    };
  }

  createRectangleAroundLine(x1, y1, x2, y2, magnetMarginInPx = this.magnetMarginInPx) {
    const centerX = (x1 + x2) / 2;
    const centerY = (y1 + y2) / 2;

    const isVertical = x1 === x2;
    const isHorizontal = y1 === y2;

    const width = isVertical ? magnetMarginInPx : Math.abs(x2 - x1);
    const height = isVertical ? Math.abs(y2 - y1) : magnetMarginInPx;

    const left = centerX - width / 2;
    const top = centerY - height / 2;

    const rectangle = new fabric.Rect({
      left: left,
      top: top,
      width: width,
      height: height,
      fill: 'transparent',
      strokeWidth: 0,
      selectable: false,
      data: { isVertical, isHorizontal },
    });

    return rectangle;
  }

  isVerticalLine(line: fabric.Line) {
    return line.x1 === line.x2;
  }

  isHorizontalLine(line: fabric.Line) {
    return line.y1 === line.y2;
  }

  loadFabricImageFromURL(url): Promise<fabric.Image> {
    return new Promise((resolve) => {
      fabric.Image.fromURL(url, (fImg) => {
        resolve(fImg);
      });
    });
  }

  clearFabricCanvas() {
    if (!this.fabricCanvas) return;

    this.fabricCanvas.clear();
    this.fabricCanvas.dispose();
    this.fabricCanvas = null;
  }

  addOutOfBoundsThresholdTo(valueInPx: number, multipliedBy = 1, scale = 1) {
    return valueInPx + this.outOfBoundsThresholdInPx * multipliedBy * scale;
  }

  removeOutOfBoundsThresholdFrom(valueInPx: number, multipliedBy = 1, scale = 1) {
    return valueInPx - this.outOfBoundsThresholdInPx * multipliedBy * scale;
  }

  ngOnDestroy(): void {
    this.subscriptions.forEach((s) => s.unsubscribe());
    this.clearFabricCanvas();
  }
}
