import { Injectable } from '@angular/core';
import { ITEDPayloadState } from '../models/ted-state';
import { OlcTedPublicTemplateEditorService } from './olc-ted-public-template-editor.service';
import { JsTreeNodeType, Shape, ShapeType } from '../models/shape';
import { MediaFileType } from '../../../models/media';
import { CanvasState } from '../models/canvas-state';
import { TranslateService } from '@ngx-translate/core';

@Injectable({
  providedIn: 'root',
})
export class OlcTedPublicLoadPayloadDataService {
  constructor(
    private templateEditorService: OlcTedPublicTemplateEditorService,
    private translateService: TranslateService
  ) {}

  /**
   * Take data in the param and populate the current template vars.
   *
   * @param {Object} openData Currently loaded data object.
   */
  loadPayloadData = (payloadData: ITEDPayloadState, canvasState: CanvasState) => {
    canvasState.shapes = [];
    canvasState.selection = null;
    var newTree: any = [];

    for (let i = 0; i < canvasState.sections.length; i++) {
      canvasState.sections[i].backgrounds = [];
      canvasState.sections[i].bodies = [];

      newTree.push({
        id: 'S' + i,
        parent: '#',
        text: canvasState.sections[i].name,
        type: JsTreeNodeType.SectionOpened,
        state: { opened: true },
        data: {
          section: i,
          sectionName: canvasState.sections[i].name,
        },
      });

      for (let j = 0; j < canvasState.sections[i].pages; j++) {
        newTree.push({
          id: 'S' + i + 'P' + j,
          parent: 'S' + i,
          text: this.translateService.instant('admin-olc-templates.page') + ' ' + (j + 1),
          type: JsTreeNodeType.Page,
          state: { opened: true },
          data: {
            section: i,
            sectionName: canvasState.sections[i].name,
            page: j,
          },
        });
      }
    }

    // load backgrounds and bodies
    for (let j = 0; j < canvasState.sections.length; j++) {
      if (payloadData?.sections[j]?.backgrounds) {
        canvasState.sections[j].backgrounds = payloadData?.sections[j].backgrounds.length
          ? payloadData?.sections[j].backgrounds
          : [
              {
                group: '',
                condition: '',
                from: '',
                to: '',
                pdfURL: '',
                pdfName: '',
                type: MediaFileType.PDF,
              },
            ];
      }

      if (payloadData?.sections[j]?.bodies) {
        canvasState.sections[j].bodies = payloadData?.sections[j].bodies.length
          ? payloadData?.sections[j].bodies
          : [
              {
                text: '',
                group: '',
                condition: '',
                from: '',
                to: '',
              },
            ];
      }
    }

    for (let i = 0; i < payloadData?.items.length; i++) {
      canvasState.shapes.push(
        new Shape({
          id: payloadData?.items[i].id,
          title: payloadData?.items[i].title,
          x: payloadData?.items[i].x,
          y: payloadData?.items[i].y,
          w: payloadData?.items[i].w,
          h: payloadData?.items[i].h,
          page: payloadData?.items[i].page,
          section: payloadData?.items[i].section || 0,
          type: payloadData?.items[i].type,
          texts: payloadData?.items[i].texts,
          images: payloadData?.items[i].images,
          class: payloadData?.items[i].class,
          rotate: payloadData?.items[i].rotate,
        })
      );

      newTree.push({
        id: payloadData?.items[i].id,
        parent: 'S' + (payloadData?.items[i].section || 0) + 'P' + payloadData?.items[i].page,
        text: payloadData?.items[i].title,
        type: payloadData?.items[i].type === ShapeType.Text ? JsTreeNodeType.Text : JsTreeNodeType.Image,
        state: { opened: true },
        data: {
          section: payloadData?.items[i].section,
          page: payloadData?.items[i].page,
        },
      });
    }

    this.templateEditorService.setCanvasState(canvasState);

    this.templateEditorService.tree.settings.core.data = newTree;
    this.templateEditorService.tree.refresh();
  };
}
