import { Component, Input, OnInit, ViewEncapsulation } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { ToastrService } from 'ngx-toastr';
import { HydraApiService } from '../../../../blocks/services/hydra-api.service';
import { SpinnerStateService } from '../../../../blocks/services/spinner-state.service';
import { ISnippet, Snippet } from '../../models/snippet';
import { Template } from '../../models/template';

@Component({
  selector: 'app-properties-snippets',
  templateUrl: './properties-snippets.component.html',
  styleUrls: ['./properties-snippets.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class PropertiesSnippetsComponent implements OnInit {
  @Input() template: Template;

  availableSnippets: ISnippet[] = [];
  selectedSnippets: ISnippet[] = [];

  constructor(
    private hydraApi: HydraApiService,
    private toastr: ToastrService,
    private translate: TranslateService,
    private spinner: SpinnerStateService
  ) {}

  ngOnInit() {
    this.loadPickListItems();
  }

  currentChanged = (snippets: ISnippet[]) => {
    this.template.snippets = snippets.map((snippet) => snippet.id);
  };

  loadPickListItems = () => {
    this.spinner.show(this.translate.instant('admin-olc-templates.loading-snippets'), document.documentElement);
    this.hydraApi.getSnippets(this.snippetsLoaded, this.snippetsLoadFailed);
  };

  snippetsLoaded = (snippets: Snippet[]) => {
    this.availableSnippets = snippets;
    this.selectedSnippets = this.template.snippets.map((snippetId) => snippets.find((s) => s.id === snippetId)!);
    this.spinner.hide();
  };

  snippetsLoadFailed = () => {
    this.spinner.hide();
    this.toastr.error(this.translate.instant('admin-olc-templates.snippets-load-failed'));
  };
}
