export type ClearZoneType = 'warning-zone' | 'forbidden-zone';

export class ClearZone {
  id: string;
  title: string;
  x: number;
  y: number;
  w: number;
  h: number;
  rotate: number;
  page: number;
  section: number;
  clearClass: string;
  type: ClearZoneType;
  sections: number[] = [];
  pages: number[] = [];

  constructor(clearZone: ClearZone) {
    this.id = clearZone.id;
    this.title = clearZone.title;
    this.x = clearZone.x || 0;
    this.y = clearZone.y || 0;
    this.w = clearZone.w || 10;
    this.h = clearZone.h || 10;
    this.rotate = clearZone.rotate || 0;
    this.page = clearZone.page || 0;
    this.section = clearZone.section || 0;
    this.clearClass = clearZone.clearClass;
    this.type = clearZone.type;
    this.sections = clearZone.sections || [];
    this.pages = clearZone.pages || [];
  }
}
