import {
  AfterViewInit,
  Component,
  Input,
  OnDestroy,
  OnInit,
  QueryList,
  ViewChildren,
  ViewEncapsulation,
} from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { ToastrService } from 'ngx-toastr';
import { Subscription } from 'rxjs';
import { FieldDefinition } from '../../../../../../../../Bamba.Shared/src/models/field-definition';
import { MetaDataType } from '../../../../../../../../Bamba.Shared/src/models/metadata-definition';
import { RolePermissions } from '../../../../../../../../Bamba.Shared/src/models/role';
import { HydraApiService } from '../../../../blocks/services/hydra-api.service';
import { ApiResult } from '../../../../blocks/services/models';
import { SpinnerStateService } from '../../../../blocks/services/spinner-state.service';
import { UserStateService } from '../../../../blocks/services/user-state.service';
import { Style } from '../../models/style';
import { IGroupOption, ITemplateConditionalContent, Template, TemplateStyle } from '../../models/template';
import { OlcTemplateStylesService } from '../../shared/services/olc-template-styles.service';

@Component({
  selector: 'app-properties-conditional-contents',
  templateUrl: './properties-conditional-contents.component.html',
  styleUrls: ['./properties-conditional-contents.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class PropertiesConditionalContentsComponent implements OnInit, AfterViewInit, OnDestroy {
  @ViewChildren(PerfectScrollbarDirective) scrollbarDirectives: QueryList<PerfectScrollbarDirective>;

  @Input() template: Template;
  templateStyles: TemplateStyle[] = [];

  selectedConditionalContent: ITemplateConditionalContent;
  selectedGroupOption: IGroupOption;
  nameField: FieldDefinition;
  name: string;

  contentValue = '';

  conditionalContentFormattingModal: NgxSmartModalComponent;

  canApplyMedia = false;

  subscriptions = new Subscription();

  constructor(
    private hydraApi: HydraApiService,
    private toastr: ToastrService,
    private translateService: TranslateService,
    private spinner: SpinnerStateService,
    private olcTemplateStylesService: OlcTemplateStylesService,
    private ngxSmartModalService: NgxSmartModalService,
    private userStateService: UserStateService
  ) {}

  ngOnInit() {
    this.createFields();
    this.loadTemplateStyles();
    this.canApplyMedia = this.userStateService.hasRolePermission(RolePermissions.OLCTED_MEDIA_APPLY);
  }

  ngAfterViewInit(): void {
    this.conditionalContentFormattingModal = this.ngxSmartModalService.get('conditionalContentFormattingModal');
    this.subscriptions.add(
      this.conditionalContentFormattingModal.onClose.subscribe(() => this.resetSelectedGroupOption())
    );
  }

  createFields() {
    this.nameField = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translateService.instant('admin-olc-templates.content-name-label'),
      placeholder: this.translateService.instant('admin-olc-templates.content-name-placeholder'),
      required: false,
    });
  }

  loadTemplateStyles() {
    this.spinner.show(this.translateService.instant('admin-olc-templates.loading-conditional-contents'), document.body);
    this.hydraApi.getOLCTemplateCustomStyles(this.template.id, this.customStylesLoaded, this.customStylesLoadFailed);
  }

  customStylesLoaded = (customStyles: Style[]) => {
    this.templateStyles = this.olcTemplateStylesService.getOlcTemplateStyles(this.template, customStyles);
    this.spinner.hide();
  };

  customStylesLoadFailed = () => {
    this.spinner.hide();
    this.toastr.error(this.translateService.instant('admin-olc-templates.template-custom-styles-loading-failed'));
  };

  setSelectedConditionalContent(content: ITemplateConditionalContent) {
    this.selectedConditionalContent = content;
    this.scrollbarDirectives.last.scrollToTop();
    this.scrollbarDirectives.last.update();
  }

  openConditionalContentFormattingModal(groupOption: IGroupOption) {
    this.selectedGroupOption = groupOption;
    this.contentValue = this.selectedGroupOption.value;
    this.conditionalContentFormattingModal.open();
  }

  closeConditionalContentFormattingModal = () => {
    this.conditionalContentFormattingModal.close();
  };

  resetSelectedGroupOption() {
    this.selectedGroupOption = null;
    this.contentValue = '';
  }

  onConditionalContentChange(text: string) {
    this.contentValue = text;
  }

  saveConditionalContent() {
    this.spinner.show(this.translateService.instant('admin-olc-templates.saving-content'), document.body);
    this.hydraApi.saveConditionalContent(
      this.template.id,
      this.selectedConditionalContent.group,
      this.selectedGroupOption.name,
      this.contentValue,
      this.contentSaved,
      this.savingContentFailed
    );
  }

  contentSaved = (apiResult: ApiResult) => {
    this.spinner.hide();

    if (!apiResult.success) {
      this.toastr.error(apiResult.errors[0]);
      return;
    }

    this.template.conditionalContents = apiResult.object.conditionalContents;
    this.template.templateIdInOLConnectServer = apiResult.object.templateIdInOLConnectServer;

    this.selectedConditionalContent.groupOptions = this.template.conditionalContents.find(
      (c) => c.group.toLowerCase() === this.selectedConditionalContent.group.toLowerCase()
    ).groupOptions;

    this.toastr.success(this.translateService.instant('admin-olc-templates.content-saved-successfully'));
    this.closeConditionalContentFormattingModal();
  };

  savingContentFailed = () => {
    this.spinner.hide();
    this.toastr.error(this.translateService.instant('admin-olc-templates.failed-to-save-content'));
  };

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }
}
