import {
  AfterViewInit,
  ChangeDetectorRef,
  Component,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  SimpleChanges,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { PerfectScrollbarDirective } from 'ngx-perfect-scrollbar-portable';
import { NgxSmartModalComponent, NgxSmartModalService } from 'ngx-smart-modal';
import { Subscription, combineLatest } from 'rxjs';
import { Tab } from '../../../../../../../../../../../Bamba.Shared/src/form/tab-bar/tab-bar.component';
import {
  FieldDefinition,
  IFieldOptions,
} from '../../../../../../../../../../../Bamba.Shared/src/models/field-definition';
import { FixedDataSource } from '../../../../../../../../../../../Bamba.Shared/src/models/fixed-datasource';
import { MetaDataValidity } from '../../../../../../../../../../../Bamba.Shared/src/models/metadata';
import { MetaDataType } from '../../../../../../../../../../../Bamba.Shared/src/models/metadata-definition';
import { RolePermissions } from '../../../../../../../../../../../Bamba.Shared/src/models/role';
import { DelayService } from '../../../../../../../../../../../Bamba.Shared/src/utils/delay.service';
import {
  ITemplateConditionalContent,
  ITemplateVariable,
  TemplateStyle,
} from '../../../../../../../views/admin-olc/models/template';
import { DragData } from '../../../../../../../views/document-capture/capture-models';
import { OlcTemplateStylesService } from '../../../../../shared/services/olc-template-styles.service';
import { CanvasState } from '../../../models/canvas-state';
import { JsTreeNodeType, Shape, ShapeDimension, ShapeType } from '../../../models/shape';
import {
  Background,
  IBackground,
  IImageItem,
  ITEDBody,
  ITEDSection,
  ITextItem,
  ImageItem,
  ItemToAddOrEdit,
  LengthUnit,
  MediaPreviewData,
} from '../../../models/ted-state';
import { OlcTedPublicOpenTemplateService } from '../../../services/olc-ted-public-open-template.service';
import { OlcTedPublicTemplateEditorService } from '../../../services/olc-ted-public-template-editor.service';
import { OlcTedPublicTemplateRefreshService } from '../../../services/olc-ted-public-template-refresh.service';
import { uniqueID } from '../../../utils/olc-ted-public-utilities.utils';
import { IITemLimits, IItemUpdate, ItemUpdateMode } from '../../TED-canvas/models';
import { isHtmlEmpty } from './../../../../../../../blocks/components/html-editor/utils/utils';
import { SpinnerStateService } from './../../../../../../../blocks/services/spinner-state.service';
import { UserStateService } from './../../../../../../../blocks/services/user-state.service';
import { MediaFileType } from './../../../../../../../views/admin-olc/models/media';
import { Snippet } from './../../../../../../../views/admin-olc/models/snippet';
import { TedCanvasService } from './../../TED-canvas/services/ted-canvas.service';

type Item = ITextItem | IImageItem | IBackground | ITEDBody;

@Component({
  selector: 'app-add-or-edit-item-modal',
  templateUrl: './add-or-edit-item-modal.component.html',
  styleUrls: ['./add-or-edit-item-modal.component.scss'],
  encapsulation: ViewEncapsulation.None,
})
export class AddOrEditItemModalComponent implements OnInit, AfterViewInit, OnChanges, OnDestroy {
  @Input() selectedMediaPreviewData: MediaPreviewData = null;

  titleField: FieldDefinition = new FieldDefinition();
  sectionField: FieldDefinition = new FieldDefinition();
  leftField = new FieldDefinition();
  leftFieldValidity: MetaDataValidity;
  topField = new FieldDefinition();
  topFieldValidity: MetaDataValidity;
  widthField = new FieldDefinition();
  widthFieldValidity: MetaDataValidity;
  heightField = new FieldDefinition();
  heightFieldValidity: MetaDataValidity;
  classField = new FieldDefinition();
  rotationField = new FieldDefinition();
  fromField = new FieldDefinition();
  toField = new FieldDefinition();
  conditionField = new FieldDefinition();
  conditionGroupField = new FieldDefinition();
  conditionsDatasource = new FixedDataSource([]);
  metaDataValidity = MetaDataValidity;
  leftFieldValidityError = '';
  topFieldValidityError = '';
  widthFieldValidityError = '';
  heightFieldValidityError = '';
  rotationFieldValidityError = '';
  rotationFieldValidity: MetaDataValidity;

  title = '';
  sectionId = '';
  left = '3.5cm';
  top = '3.5cm';
  width = '8cm';
  height = '3cm';
  class = '';
  rotation = '0';

  addOrEditItemModal: NgxSmartModalComponent;
  edit = false;

  selectMediaModal: NgxSmartModalComponent;

  activeTab = 'content';
  tabs: Tab[] = [];

  items: Item[] = [];
  currentItemIndex = 0;
  currentItem: Item;

  selectedItemType = ItemToAddOrEdit.Text;

  templateVariables: ITemplateVariable[] = [];
  templateStyles: TemplateStyle[] = [];
  templateSnippets: Snippet[] = [];
  templateSections: ITEDSection[] = [];
  templateConditionalContents: ITemplateConditionalContent[] = [];
  conditionGroups: Record<string, IFieldOptions[]> = {};
  emptyConditionOptions: IFieldOptions[] = [];
  sharedConditionGroup = '';

  @ViewChild(PerfectScrollbarDirective) directiveRef?: PerfectScrollbarDirective;
  autoScrollStep = 20;

  fromDate = '';
  toDate = '';
  maxFromDate = '';
  minToDate = '';

  unit = LengthUnit.CM;

  textType = ItemToAddOrEdit.Text;
  imageType = ItemToAddOrEdit.Image;
  backgroundType = ItemToAddOrEdit.Background;
  bodyTextType = ItemToAddOrEdit.BodyText;

  pdfType = MediaFileType.PDF;

  errors: string[] = [];
  loading = false;

  canvasState: CanvasState = null;

  itemLimits: IITemLimits = null;

  canApplyMedia = false;

  subscriptions: Subscription[] = [];

  get currentItemText(): string {
    return (this.currentItem as ITextItem)?.text;
  }
  get currentItemImage(): string {
    return (this.currentItem as IImageItem)?.image;
  }
  get currentItemType(): MediaFileType {
    return (this.currentItem as IImageItem)?.type;
  }
  get currentItemPdfURL(): string {
    return (this.currentItem as IBackground)?.pdfURL;
  }

  constructor(
    private templateEditorService: OlcTedPublicTemplateEditorService,
    private templateRefreshService: OlcTedPublicTemplateRefreshService,
    private openTemplateService: OlcTedPublicOpenTemplateService,
    private spinnerService: SpinnerStateService,
    private ngxSmartModalService: NgxSmartModalService,
    private translateService: TranslateService,
    private olcTemplateStylesService: OlcTemplateStylesService,
    private cdr: ChangeDetectorRef,
    private delayService: DelayService,
    private userStateService: UserStateService,
    private tedCanvasService: TedCanvasService
  ) {}

  ngOnChanges(changes: SimpleChanges): void {
    const selectedMediaData = changes.selectedMediaPreviewData.currentValue as MediaPreviewData;

    if (selectedMediaData && this.selectedItemType === ItemToAddOrEdit.Image) {
      const item = this.items[this.currentItemIndex] as ImageItem;

      item.image = selectedMediaData.url;
      item.imageName = selectedMediaData.name;
      item.type = selectedMediaData.type;
      this.setCurrentItem();
    }

    if (selectedMediaData && this.selectedItemType === ItemToAddOrEdit.Background) {
      const item = this.items[this.currentItemIndex] as Background;

      item.pdfURL = selectedMediaData.url;
      item.pdfName = selectedMediaData.name;
      item.type = selectedMediaData.type as MediaFileType.PDF;
      this.setCurrentItem();
    }
  }

  ngOnInit() {
    this.adjustNewShapeDimensions();

    this.subscriptions.push(
      combineLatest([this.templateEditorService.template$, this.templateEditorService.templateCustomStyles$]).subscribe(
        ([template, customStyles]) => {
          this.templateStyles = this.olcTemplateStylesService.getOlcTemplateStyles(template, customStyles);
        }
      ),
      this.templateEditorService.canvasState$.subscribe((canvasState) => (this.canvasState = canvasState)),
      this.templateEditorService.templateSnippet$.subscribe((snippets) => (this.templateSnippets = snippets)),
      this.templateEditorService.template$.subscribe(
        (template) => (this.templateConditionalContents = template.conditionalContents)
      ),
      this.tedCanvasService.onValidateBoundaries.subscribe((valid) => {
        this.validateRotation();

        if (this.rotationFieldValidity === this.metaDataValidity.notValid) return;

        if (valid) return;

        this.rotationFieldValidity = this.metaDataValidity.notValid;
        this.rotationFieldValidityError = this.translateService.instant('admin-olc-templates.item-crosses-boundaries');
      }),
      this.tedCanvasService.onCalculateLimits.subscribe((limits: IITemLimits) => (this.itemLimits = limits))
    );

    this.templateVariables = this.templateEditorService.templateVariables;
    this.templateSections = this.openTemplateService.getOrderedSections(this.canvasState.sections);
    this.sectionId = this.templateSections[this.templateEditorService.currentSection]?.id || '';

    this.emptyConditionOptions = [
      {
        name: this.translateService.instant('admin-olc-templates.default-condition-option-label'),
        value: '',
      },
    ];

    this.buildConditionsGroupDictionary();

    this.canApplyMedia = this.userStateService.hasRolePermission(RolePermissions.OLCTED_MEDIA_APPLY);
  }

  ngAfterViewInit() {
    this.addOrEditItemModal = this.ngxSmartModalService.get('addOrEditItemModal');
    this.selectMediaModal = this.ngxSmartModalService.get('selectMediaModal');

    this.selectedItemType = (this.addOrEditItemModal.getData() as any).itemType;

    this.initializeItems();
    this.createFields();
    this.createTabs();

    this.edit = !!(this.addOrEditItemModal.getData() as any).edit;

    if (this.edit) this.setInitialValuesForEdit();

    this.setInitialSharedConditionGroup();

    this.setCurrentItem();

    this.cdr.detectChanges();

    this.spinnerService.visibilityChanged.subscribe((visible) => (this.loading = visible));

    this.notifyCanvasWithUpdates(null, this.edit ? ItemUpdateMode.Edit : ItemUpdateMode.Add);
  }

  setInitialSharedConditionGroup() {
    for (let item of this.items) {
      if (!item.group || !item.condition) continue;

      if (!this.sharedConditionGroup) {
        this.sharedConditionGroup = item.group;
      } else if (this.sharedConditionGroup != item.group) {
        this.resetItemsConditions();
        this.sharedConditionGroup = '';
        break;
      }
    }
  }

  createFields() {
    if (this.selectedItemType === ItemToAddOrEdit.Text || this.selectedItemType === ItemToAddOrEdit.Image) {
      this.titleField = new FieldDefinition({
        type: MetaDataType.Text,
        label: this.translateService.instant('admin-olc-templates.add-item-title-label'),
        placeholder: this.translateService.instant('admin-olc-templates.add-item-title-placeholder'),
        required: false,
      });

      this.leftField = new FieldDefinition({
        type: MetaDataType.Text,
        label: `${this.translateService.instant('admin-olc-templates.add-item-left-label')}`,
        placeholder: this.translateService.instant('admin-olc-templates.add-item-left-placeholder'),
        required: true,
      });

      this.topField = new FieldDefinition({
        type: MetaDataType.Text,
        label: `${this.translateService.instant('admin-olc-templates.add-item-top-label')}`,
        placeholder: this.translateService.instant('admin-olc-templates.add-item-top-placeholder'),
        required: true,
      });

      this.widthField = new FieldDefinition({
        type: MetaDataType.Text,
        label: `${this.translateService.instant('admin-olc-templates.add-item-width-label')}`,
        placeholder: this.translateService.instant('admin-olc-templates.add-item-width-placeholder'),
        required: true,
      });

      this.heightField = new FieldDefinition({
        type: MetaDataType.Text,
        label: `${this.translateService.instant('admin-olc-templates.add-item-height-label')}`,
        placeholder: this.translateService.instant('admin-olc-templates.add-item-height-placeholder'),
        required: true,
      });

      this.classField = new FieldDefinition({
        type: MetaDataType.Text,
        label: this.translateService.instant('admin-olc-templates.add-item-class-label'),
        placeholder: this.translateService.instant('admin-olc-templates.add-item-class-placeholder'),
        required: false,
      });

      this.rotationField = new FieldDefinition({
        type: MetaDataType.Text,
        label: `${this.translateService.instant(
          'admin-olc-templates.add-item-rotation-label'
        )} (${this.translateService.instant('admin-olc-templates.degree')})`,
        placeholder: this.translateService.instant('admin-olc-templates.add-item-rotation-placeholder'),
        required: false,
      });
    }

    if (this.isBackgroundOrBody()) {
      const sectionOptions: IFieldOptions[] = this.templateSections.map((s) => ({
        name: s.name,
        value: s.id,
      }));

      this.sectionField = new FieldDefinition({
        type: MetaDataType.List,
        label: this.translateService.instant('admin-olc-templates.add-item-section-label'),
        placeholder: this.translateService.instant('admin-olc-templates.add-item-section-placeholder'),
        datasource: new FixedDataSource(sectionOptions),
        required: true,
      });
    }

    this.createItemConditionsFields();
  }

  isBackgroundOrBody() {
    return this.selectedItemType === ItemToAddOrEdit.Background || this.selectedItemType === ItemToAddOrEdit.BodyText;
  }

  adjustNewShapeDimensions() {
    if (this.templateEditorService.defaultUnit == LengthUnit.CM) return;

    this.left = this.convertValueToDefaultUnit(this.left);
    this.top = this.convertValueToDefaultUnit(this.top);
    this.width = this.convertValueToDefaultUnit(this.width);
    this.height = this.convertValueToDefaultUnit(this.height);
  }

  createItemConditionsFields() {
    const datelocaleFormat = this.userStateService.getLocalDateFormat();

    this.fromField = new FieldDefinition({
      type: MetaDataType.Date,
      label: this.translateService.instant('admin-olc-templates.add-item-condition-from-label'),
      placeholder: this.translateService.instant('admin-olc-templates.add-item-condition-from-placeholder'),
      required: false,
      dateFieldExpectedFormat: datelocaleFormat,
    });

    this.toField = new FieldDefinition({
      type: MetaDataType.Date,
      label: this.translateService.instant('admin-olc-templates.add-item-condition-to-label'),
      placeholder: this.translateService.instant('admin-olc-templates.add-item-condition-to-placeholder'),
      required: false,
      dateFieldExpectedFormat: datelocaleFormat,
    });

    this.conditionField = new FieldDefinition({
      type: MetaDataType.List,
      label: ' ',
      datasource: this.conditionsDatasource,
      required: false,
    });

    const conditionGroupsOptions: IFieldOptions[] = Object.keys(this.conditionGroups).map((g) => ({
      name: g,
      value: g,
    }));

    conditionGroupsOptions.unshift({
      name: this.translateService.instant('admin-olc-templates.default-condition-option-label'),
      value: '',
    });

    this.conditionGroupField = new FieldDefinition({
      type: MetaDataType.List,
      label: this.translateService.instant('admin-olc-templates.add-item-condition-label'),
      datasource: new FixedDataSource(conditionGroupsOptions),
      required: false,
    });
  }

  buildConditionsGroupDictionary() {
    this.templateEditorService.templateConditions.forEach((condition) => {
      const group = condition.group?.toString() ?? '';

      if (!this.conditionGroups[group]) this.conditionGroups[group] = [];

      this.conditionGroups[group].push({
        name: condition.title,
        value: condition.id,
      });
    });
  }

  createTabs() {
    this.tabs.push(
      new Tab('content', this.translateService.instant('admin-olc-templates.add-or-edit-item-modal-content'))
    );

    if (this.selectedItemType === ItemToAddOrEdit.Text || this.selectedItemType === ItemToAddOrEdit.Image)
      this.tabs.push(
        new Tab('item-box', this.translateService.instant('admin-olc-templates.add-or-edit-item-modal-advanced'))
      );
  }

  initializeItems() {
    this.currentItem =
      this.selectedItemType === ItemToAddOrEdit.Text || this.selectedItemType === ItemToAddOrEdit.BodyText
        ? {
            text: '',
            group: '',
            condition: '',
            from: '',
            to: '',
          }
        : this.selectedItemType === ItemToAddOrEdit.Image
        ? {
            image: '',
            imageName: '',
            type: MediaFileType.PNG,
            group: '',
            condition: '',
            from: '',
            to: '',
          }
        : this.selectedItemType === ItemToAddOrEdit.Background
        ? {
            pdfURL: '',
            pdfName: '',
            type: MediaFileType.PDF,
            group: '',
            condition: '',
            from: '',
            to: '',
          }
        : null;

    this.items = [this.currentItem];
  }

  getModalTitle() {
    return this.translateService.instant(
      `admin-olc-templates.${
        this.selectedItemType === ItemToAddOrEdit.Text
          ? 'text-modal-title'
          : this.selectedItemType === ItemToAddOrEdit.Image
          ? 'image-modal-title'
          : this.selectedItemType === ItemToAddOrEdit.Background
          ? 'background-modal-title'
          : this.selectedItemType === ItemToAddOrEdit.BodyText
          ? 'body-text-modal-title'
          : ''
      }`
    );
  }

  activateTab = (tab) => {
    this.activeTab = tab;
  };

  updateSection(sectionId: string) {
    if (!sectionId || !this.isBackgroundOrBody()) return;

    if (sectionId != this.sectionId) {
      const previousSection = this.templateSections.find((s) => s.id === this.sectionId);

      if (this.selectedItemType === ItemToAddOrEdit.BodyText) {
        previousSection.bodies = this.deepCopyForItems(this.items);
      } else {
        previousSection.backgrounds = this.deepCopyForItems(this.items);
      }
    }

    this.sectionId = sectionId;
    const selectedSection = this.templateSections.find((s) => s.id === this.sectionId);

    if (this.selectedItemType === ItemToAddOrEdit.Background) {
      this.items = selectedSection?.backgrounds.length
        ? this.deepCopyForItems(selectedSection.backgrounds)
        : [
            {
              group: '',
              condition: '',
              from: '',
              to: '',
              pdfURL: '',
              pdfName: '',
            },
          ];
    }

    if (this.selectedItemType === ItemToAddOrEdit.BodyText) {
      this.items = selectedSection?.bodies.length
        ? this.deepCopyForItems(selectedSection.bodies)
        : [{ text: '', group: '', condition: '', from: '', to: '' }];
    }

    this.currentItemIndex = 0;
    this.setCurrentItem();
  }

  setInitialValuesForEdit() {
    if (this.selectedItemType === ItemToAddOrEdit.Text || this.selectedItemType === ItemToAddOrEdit.Image) {
      const selectedShape = this.canvasState.selection;

      this.title = selectedShape.title;
      this.left = this.templateEditorService.convertPixelTo(selectedShape.x) + this.templateEditorService.defaultUnit;
      this.top = this.templateEditorService.convertPixelTo(selectedShape.y) + this.templateEditorService.defaultUnit;
      this.width = this.templateEditorService.convertPixelTo(selectedShape.w) + this.templateEditorService.defaultUnit;
      this.height = this.templateEditorService.convertPixelTo(selectedShape.h) + this.templateEditorService.defaultUnit;
      this.class = selectedShape.class;
      this.rotation = selectedShape.rotate.toFixed(2) + '';

      if (this.selectedItemType === ItemToAddOrEdit.Text && selectedShape.texts.length)
        this.items = this.deepCopyForItems(selectedShape.texts);
      if (this.selectedItemType === ItemToAddOrEdit.Image && selectedShape.images.length)
        this.items = this.deepCopyForItems(selectedShape.images);
    }

    if (this.selectedItemType === ItemToAddOrEdit.Image)
      this.selectedMediaPreviewData = {
        url: (this.items[this.currentItemIndex] as ImageItem).image,
        name: (this.items[this.currentItemIndex] as ImageItem).imageName,
        type: (this.items[this.currentItemIndex] as ImageItem).type,
      };

    if (this.selectedItemType === ItemToAddOrEdit.Background) {
      const selectedSection = this.templateSections[this.templateEditorService.currentSection];
      this.sectionId = selectedSection?.id;
      if (selectedSection?.backgrounds.length) this.items = this.deepCopyForItems(selectedSection.backgrounds);
      this.selectedMediaPreviewData = {
        url: (this.items[this.currentItemIndex] as Background).pdfURL,
        name: (this.items[this.currentItemIndex] as Background).pdfName,
        type: (this.items[this.currentItemIndex] as Background).type,
      };
    }

    if (this.selectedItemType === ItemToAddOrEdit.BodyText) {
      const selectedSection = this.templateSections[this.templateEditorService.currentSection];
      this.sectionId = selectedSection?.id;
      if (selectedSection?.bodies.length) this.items = this.deepCopyForItems(selectedSection.bodies);
    }

    this.items.forEach(this.setItemGroup);
  }

  setItemGroup = (item: Item) => {
    if (!item.condition || item.group) return;
    item.group = this.getItemConditionGroup(item);
  };

  deepCopyForItems(items: Item[]) {
    const newItems = [];
    items.forEach((i) => {
      newItems.push({ ...i });
    });
    return newItems;
  }

  deleteItem(index: number) {
    if (
      this.items.length <= 1 &&
      ![ItemToAddOrEdit.Background, ItemToAddOrEdit.BodyText].includes(this.selectedItemType)
    )
      return;

    this.items = this.items.filter((_, i) => i !== index);

    if (this.currentItemIndex > this.items.length - 1) this.currentItemIndex = this.items.length - 1;
    if (this.currentItemIndex < 0) this.currentItemIndex = 0;
    this.setCurrentItem();
  }

  activateItem(index: number) {
    if (this.currentItemIndex === index) return;

    this.currentItemIndex = index;
    this.setCurrentItem();
  }

  getConditionSummary(item: Item) {
    return `${this.translateService.instant('admin-olc-templates.add-item-condition-label')}: ${
      item.condition || this.translateService.instant('admin-olc-templates.default-condition-option-label')
    } ${
      item.from
        ? '| ' + this.translateService.instant('admin-olc-templates.add-item-condition-from-label') + ': ' + item.from
        : ''
    } ${
      item.to
        ? '| ' + this.translateService.instant('admin-olc-templates.add-item-condition-to-label') + ': ' + item.to
        : ''
    }`;
  }

  addItem() {
    const itemToAdd =
      this.selectedItemType === ItemToAddOrEdit.Text || this.selectedItemType === ItemToAddOrEdit.BodyText
        ? ({
            text: '',
            group: '',
            condition: '',
            from: '',
            to: '',
          } as ITextItem | ITEDBody)
        : this.selectedItemType === ItemToAddOrEdit.Image
        ? ({
            image: '',
            imageName: '',
            type: MediaFileType.PNG,
            group: '',
            condition: '',
            from: '',
            to: '',
          } as IImageItem)
        : this.selectedItemType === ItemToAddOrEdit.Background
        ? ({
            pdfURL: '',
            pdfName: '',
            type: MediaFileType.PDF,
            group: '',
            condition: '',
            from: '',
            to: '',
          } as IBackground)
        : null;

    this.items = [...this.items, itemToAdd];

    this.currentItemIndex = this.items.length - 1;
    this.setCurrentItem();
  }

  setCurrentItem() {
    this.currentItem = undefined;
    const timeoutId = setTimeout(() => {
      this.currentItem = this.items[this.currentItemIndex];
      this.setItemGroup(this.currentItem);
      this.changeGroupConditions(this.currentItem.group);
      this.setFromToDatesValuesAndLimits(this.currentItem.from, this.currentItem.to);
      clearTimeout(timeoutId);
    }, 0);
  }

  setFromToDatesValuesAndLimits(fromDate: string, toDate: string) {
    this.fromDate = fromDate;
    this.toDate = toDate;
    this.maxFromDate = toDate;
    this.minToDate = fromDate;
  }

  getItemConditionGroup(item: Item) {
    return (
      this.templateEditorService.templateConditions
        .filter((c) => c.id === item?.condition ?? '')[0]
        ?.group?.toString() ?? ''
    );
  }

  updateItemText = (text: string) => {
    (this.items[this.currentItemIndex] as ITextItem | ITEDBody).text = text;
  };

  updateFromDate(fromDate: string) {
    this.items[this.currentItemIndex].from = fromDate;
    const { from, to } = this.items[this.currentItemIndex];
    this.setFromToDatesValuesAndLimits(from, to);
  }

  updateToDate(toDate: string) {
    this.items[this.currentItemIndex].to = toDate;
    const { from, to } = this.items[this.currentItemIndex];
    this.setFromToDatesValuesAndLimits(from, to);
  }

  changeGroupConditions(group?: string) {
    // when Always is selected as group
    if (!group) {
      this.conditionsDatasource.updateOptions(this.emptyConditionOptions);
      this.currentItem.group = '';
      this.currentItem.condition = '';
      return;
    }

    // when the first condition is applied
    if (this.sharedConditionGroup == '') {
      this.sharedConditionGroup = group;
      this.conditionsDatasource.updateOptions(this.conditionGroups[group]);
      return;
    }

    // when the same group is selected
    if (this.sharedConditionGroup == group) {
      this.conditionsDatasource.updateOptions(this.conditionGroups[group]);

      if (!this.currentItem.condition) {
        this.currentItem.condition = this.conditionGroups[group]?.[0]?.value ?? '';
      }

      return;
    }

    // when a different group is selected
    if (this.getConditionedItemsCount() >= 1) {
      this.showDiffGroupConfirmModal(group);
    } else {
      this.differentConditionGroupSelected(group);
    }
  }

  getConditionedItemsCount() {
    return this.items.filter((item, index) => this.currentItemIndex != index && item.condition).length;
  }

  showDiffGroupConfirmModal(group: string) {
    this.ngxSmartModalService.setModalData(
      {
        title: 'MainHeader.ActionConfirmation',
        text: this.translateService.instant('admin-olc-templates.condition-group-changed-confirm-text'),
        buttonText: this.translateService.instant('MainHeader.ActionConfirmationApply'),
        confirm: () => {
          this.closeConfirmationAction();
          this.differentConditionGroupSelected(group);
        },
        cancel: () => {
          this.closeConfirmationAction();
          this.currentItem.group = this.currentItem.condition ? this.sharedConditionGroup : '';
        },
      },
      'actionConfirmModal',
      true
    );

    this.ngxSmartModalService.getModal('actionConfirmModal').open(true);
  }

  differentConditionGroupSelected(group: string) {
    this.delayService.execute(() => {
      this.resetItemsConditions();
      this.conditionsDatasource.updateOptions(this.conditionGroups[group]);
      this.currentItem.group = this.sharedConditionGroup = group;
      this.currentItem.condition = this.conditionGroups[group]?.[0]?.value ?? '';
    }, 100);
  }

  resetItemsConditions() {
    this.items.forEach((item) => {
      item.group = '';
      item.condition = '';
    });
  }

  closeConfirmationAction() {
    this.ngxSmartModalService.getModal('actionConfirmModal').close();
  }

  updateCondition(condition: string) {
    this.items[this.currentItemIndex].condition = condition;
  }

  saveItem() {
    if (this.selectedItemType == ItemToAddOrEdit.Text) this.adjustTextsTitle();

    this.validateItemContent();
    if (this.errors.length) return;

    if (this.selectedItemType === ItemToAddOrEdit.Text && this.edit) {
      this.editText();
      return;
    }

    if (this.selectedItemType === ItemToAddOrEdit.Text && !this.edit) {
      this.addText();
      return;
    }

    if (this.selectedItemType === ItemToAddOrEdit.Image && this.edit) {
      this.editImage();
      return;
    }

    if (this.selectedItemType === ItemToAddOrEdit.Image && !this.edit) {
      this.addImage();
      return;
    }

    if (this.selectedItemType === ItemToAddOrEdit.Background) {
      this.addOrEditBackground();
      return;
    }

    if (this.selectedItemType === ItemToAddOrEdit.BodyText) {
      this.addOrEditBodyText();
      return;
    }
  }

  validateItemContent() {
    this.errors = [];

    const isText = this.selectedItemType === ItemToAddOrEdit.Text;
    const isImage = this.selectedItemType === ItemToAddOrEdit.Image;
    const isBackground = this.selectedItemType === ItemToAddOrEdit.Background;
    const isBodyText = this.selectedItemType === ItemToAddOrEdit.BodyText;

    if ((isBackground || isBodyText) && !this.sectionId) this.errors.push('admin-olc-templates.section-empty-error');

    if ((isText || isImage) && this.rotation && (+this.rotation < 0 || +this.rotation > 360)) {
      this.errors.push('admin-olc-templates.invalid-rotation-value');
    }

    this.items.forEach((item) => {
      if (isText) this.validateTextItemContent(item as ITextItem);
      if (isBodyText) this.validateBodyItemContent(item as ITEDBody);
      if (isImage) this.validateImageItemContent(item as IImageItem);
      if (isBackground) this.validateBackgroundItemContent(item as IBackground);
    });

    if (isText && !this.errors.length && !this.title) {
      this.errors.push(this.translateService.instant('admin-olc-templates.invalid-text-empty-title'));
    }
  }

  validateTextItemContent(item: ITextItem) {
    if (!isHtmlEmpty(item.text)) return;

    return this.errors.push(
      `${this.getConditionSummary(item)} - ${this.translateService.instant(
        'admin-olc-templates.invalid-text-empty-content'
      )}`
    );
  }

  validateBodyItemContent(item: ITEDBody) {
    if (!isHtmlEmpty(item.text)) return;

    this.errors.push(
      `${this.getConditionSummary(item)} - ${this.translateService.instant(
        'admin-olc-templates.invalid-body-text-empty-content'
      )}`
    );
  }

  validateImageItemContent(item: IImageItem) {
    if (item.image) return;

    this.errors.push(
      `${this.getConditionSummary(item)} - ${this.translateService.instant(
        'admin-olc-templates.invalid-image-empty-url'
      )}`
    );
  }

  validateBackgroundItemContent(item: IBackground) {
    if (item.pdfURL) return;

    this.errors.push(
      `${this.getConditionSummary(item)} - ${this.translateService.instant(
        'admin-olc-templates.invalid-background-empty-url'
      )}`
    );
  }

  adjustTextsTitle() {
    if (this.title) return;

    const items = this.items as ITextItem[];
    const mergedTexts = items.map((t) => t.text).join('');
    const content = this.htmlToText(mergedTexts);
    this.title = content.length > 15 ? content.slice(0, 15) + '...' : content;
  }

  addText() {
    const updatedCanvasState = { ...this.canvasState };

    updatedCanvasState.shapes.push(
      new Shape({
        id: uniqueID(),
        title: this.title,
        x: this.convertToPixel(this.left),
        y: this.convertToPixel(this.top),
        w: this.convertToPixel(this.width),
        h: this.convertToPixel(this.height),
        page: this.templateEditorService.currentDisplayPage,
        section: this.templateEditorService.currentSection,
        type: ShapeType.Text,
        texts: this.items as ITextItem[],
        images: null,
        class: this.class,
        rotate: +this.rotation,
      })
    );

    updatedCanvasState.selection = updatedCanvasState.shapes[updatedCanvasState.shapes.length - 1];

    const nodeTitle = this.title.length > 15 ? this.title.slice(0, 15) + '...' : this.title;

    this.templateEditorService.tree.create_node(
      'S' + this.templateEditorService.currentSection + 'P' + this.templateEditorService.currentDisplayPage,
      {
        id: updatedCanvasState.selection.id,
        text: nodeTitle,
        type: JsTreeNodeType.Text,
        state: { opened: true },
        data: {
          section: this.templateEditorService.currentSection,
          page: this.templateEditorService.currentDisplayPage,
        },
      },
      'last'
    );

    this.templateEditorService.tree.deselect_all();
    this.templateEditorService.tree.select_node(updatedCanvasState.selection.id);

    this.templateRefreshService.refreshBackground(updatedCanvasState);

    this.closeAddOrEditItemModal();
  }

  editText() {
    const updatedCanvasState = { ...this.canvasState };

    const updatedText = new Shape({
      id: updatedCanvasState.selection.id,
      title: this.title,
      x: this.convertToPixel(this.left),
      y: this.convertToPixel(this.top),
      w: this.convertToPixel(this.width),
      h: this.convertToPixel(this.height),
      page: this.templateEditorService.currentDisplayPage,
      section: this.templateEditorService.currentSection,
      type: ShapeType.Text,
      texts: this.items as ITextItem[],
      images: null,
      class: this.class,
      rotate: +this.rotation,
    });

    const shapeIndex = updatedCanvasState.shapes.findIndex((sh) => sh.id === updatedCanvasState.selection.id);

    updatedCanvasState.shapes[shapeIndex] = updatedText;
    updatedCanvasState.selection = updatedText;

    const nodeTitle = this.title.length > 15 ? this.title.slice(0, 15) + '...' : this.title;

    this.templateEditorService.tree.rename_node(updatedCanvasState.selection.id, nodeTitle);

    this.templateRefreshService.refreshBackground(updatedCanvasState);

    this.closeAddOrEditItemModal();
  }

  addImage() {
    const items = this.items as IImageItem[];

    const adjustedTitle = !this.title
      ? items[0].imageName.length > 15
        ? items[0].imageName.slice(0, 15) + '...'
        : items[0].imageName
      : this.title;

    const updatedCanvasState = { ...this.canvasState };

    updatedCanvasState.shapes.push(
      new Shape({
        id: uniqueID(),
        title: adjustedTitle,
        x: this.convertToPixel(this.left),
        y: this.convertToPixel(this.top),
        w: this.convertToPixel(this.width),
        h: this.convertToPixel(this.height),
        page: this.templateEditorService.currentDisplayPage,
        section: this.templateEditorService.currentSection,
        type: ShapeType.Image,
        texts: null,
        images: items,
        class: this.class,
        rotate: +this.rotation,
      })
    );

    updatedCanvasState.selection = updatedCanvasState.shapes[updatedCanvasState.shapes.length - 1];

    const nodeTitle = !this.title
      ? items[0].imageName.length > 15
        ? items[0].imageName.slice(0, 15) + '...'
        : items[0].imageName
      : this.title.length > 15
      ? this.title.slice(0, 15) + '...'
      : this.title;

    this.templateEditorService.tree.create_node(
      'S' + this.templateEditorService.currentSection + 'P' + this.templateEditorService.currentDisplayPage,
      {
        id: updatedCanvasState.selection.id,
        text: nodeTitle,
        type: JsTreeNodeType.Image,
        state: { opened: true },
        data: {
          section: this.templateEditorService.currentSection,
          page: this.templateEditorService.currentDisplayPage,
        },
      },
      'last'
    );

    this.templateEditorService.tree.deselect_all();
    this.templateEditorService.tree.select_node(updatedCanvasState.selection.id);

    this.templateRefreshService.refreshBackground(updatedCanvasState);

    this.closeAddOrEditItemModal();
  }

  editImage() {
    const items = this.items as IImageItem[];

    const adjustedTitle = !this.title
      ? items[0].imageName.length > 15
        ? items[0].imageName.slice(0, 15) + '...'
        : items[0].imageName
      : this.title;

    const updatedCanvasState = { ...this.canvasState };

    const updatedText = new Shape({
      id: updatedCanvasState.selection.id,
      title: adjustedTitle,
      x: this.convertToPixel(this.left),
      y: this.convertToPixel(this.top),
      w: this.convertToPixel(this.width),
      h: this.convertToPixel(this.height),
      page: this.templateEditorService.currentDisplayPage,
      section: this.templateEditorService.currentSection,
      type: ShapeType.Image,
      texts: null,
      images: items,
      class: this.class,
      rotate: +this.rotation,
    });

    const shapeIndex = updatedCanvasState.shapes.findIndex((sh) => sh.id === updatedCanvasState.selection.id);

    updatedCanvasState.shapes[shapeIndex] = updatedText;

    updatedCanvasState.selection = updatedText;

    const nodeTitle = !this.title
      ? items[0].imageName.length > 15
        ? items[0].imageName.slice(0, 15) + '...'
        : items[0].imageName
      : this.title.length > 15
      ? this.title.slice(0, 15) + '...'
      : this.title;

    this.templateEditorService.tree.rename_node(updatedCanvasState.selection.id, nodeTitle);

    this.templateRefreshService.refreshBackground(updatedCanvasState);

    this.closeAddOrEditItemModal();
  }

  addOrEditBackground() {
    const items = this.items as Background[];

    const updatedCanvasState = { ...this.canvasState };

    const sectionToEdit = updatedCanvasState.sections.find((s) => s.id === this.sectionId);
    sectionToEdit.backgrounds = items;

    this.templateRefreshService.refreshBackground(updatedCanvasState);

    this.closeAddOrEditItemModal();
  }

  addOrEditBodyText() {
    const items = this.items as ITEDBody[];

    const updatedCanvasState = { ...this.canvasState };

    const sectionToEdit = updatedCanvasState.sections.find((s) => s.id === this.sectionId);
    sectionToEdit.bodies = items;

    this.templateRefreshService.refreshBackground(updatedCanvasState);

    this.closeAddOrEditItemModal();
  }

  closeAddOrEditItemModal = () => {
    this.addOrEditItemModal.removeData();
    this.addOrEditItemModal.close();
    this.resetModal();
  };

  onCancel = () => {
    this.closeAddOrEditItemModal();

    if (this.edit) {
      this.notifyCanvasWithUpdates(
        {
          left: this.canvasState.selection.x,
          top: this.canvasState.selection.y,
          width: this.canvasState.selection.w,
          height: this.canvasState.selection.h,
          angle: this.canvasState.selection.rotate,
        },
        ItemUpdateMode.Edit
      );

      return;
    }

    this.notifyCanvasWithUpdates(null, ItemUpdateMode.Delete);
  };

  resetModal() {
    this.title = '';
    this.left = '3.5cm';
    this.top = '3.5cm';
    this.width = '8cm';
    this.height = '3cm';
    this.class = '';
    this.rotation = '0';

    this.adjustNewShapeDimensions();

    this.edit = false;
    this.selectedItemType = ItemToAddOrEdit.Text;

    this.items = [];
    this.currentItemIndex = 0;

    this.selectedMediaPreviewData = { url: '', name: '', type: MediaFileType.PNG };
  }

  clearSelectedMedia() {
    const item = this.items[this.currentItemIndex] as Background;
    item.pdfURL = '';
    item.pdfName = '';
    item.type = MediaFileType.PDF;
    this.setCurrentItem();
  }

  openSelectMediaModal() {
    this.ngxSmartModalService.setModalData({ itemType: this.selectedItemType }, 'selectMediaModal', true);
    this.selectMediaModal.open();
  }

  htmlToText(html: string): string {
    const div = document.createElement('div');
    div.innerHTML = html;
    return div.textContent;
  }

  onSort(dragData: DragData) {
    const oldIndex = dragData.elementPosition - 1;
    const newIndex = dragData.targetPosition - 1;

    if (this.currentItemIndex === oldIndex) {
      this.activateItem(newIndex);
      return;
    }

    if (oldIndex < this.currentItemIndex && newIndex >= this.currentItemIndex) {
      this.activateItem(this.currentItemIndex - 1);
      return;
    }

    if (oldIndex > this.currentItemIndex && newIndex <= this.currentItemIndex) {
      this.activateItem(this.currentItemIndex + 1);
      return;
    }
  }

  onScroll(position: number) {
    this.directiveRef.scrollToY(position, this.autoScrollStep);
  }

  getSelectedSectionData() {
    const selectedSection = this.templateSections.find((section) => section.id === this.sectionId);

    return selectedSection
      ? {
          defaultUnit: this.templateEditorService.defaultUnit,
          pageSize: selectedSection.pageSize,
          width: this.templateEditorService.convertPixelTo(
            selectedSection.width,
            this.templateEditorService.defaultUnit
          ),
          height: this.templateEditorService.convertPixelTo(
            selectedSection.height,
            this.templateEditorService.defaultUnit
          ),
          orientation: this.translateService.instant(
            `admin-olc-templates.${selectedSection.portrait ? 'portrait' : 'landscape'}`
          ),
          pagesNumber: selectedSection.pages,
        }
      : null;
  }

  onLeftBlur(value: string) {
    this.delayService.execute(() => {
      const result = this.validateShapeDimensionValue(value, ShapeDimension.Left);
      this.left = result.updatedValue;
      this.leftFieldValidity = result.validity;
      this.leftFieldValidityError = result.error;

      if (this.leftFieldValidityError) return;

      this.notifyCanvasWithUpdates(null, ItemUpdateMode.Edit);
    }, 0);
  }

  onTopBlur(value: string) {
    this.delayService.execute(() => {
      const result = this.validateShapeDimensionValue(value, ShapeDimension.Top);
      this.top = result.updatedValue;
      this.topFieldValidity = result.validity;
      this.topFieldValidityError = result.error;

      if (this.topFieldValidityError) return;

      this.notifyCanvasWithUpdates(null, ItemUpdateMode.Edit);
    }, 0);
  }

  onWidthBlur(value: string) {
    this.delayService.execute(() => {
      const result = this.validateShapeDimensionValue(value, ShapeDimension.Width);
      this.width = result.updatedValue;
      this.widthFieldValidity = result.validity;
      this.widthFieldValidityError = result.error;

      if (this.widthFieldValidityError) return;

      this.notifyCanvasWithUpdates(null, ItemUpdateMode.Edit);
    }, 0);
  }

  onHeightBlur(value: string) {
    this.delayService.execute(() => {
      const result = this.validateShapeDimensionValue(value, ShapeDimension.Height);
      this.height = result.updatedValue;
      this.heightFieldValidity = result.validity;
      this.heightFieldValidityError = result.error;

      if (this.heightFieldValidityError) return;

      this.notifyCanvasWithUpdates(null, ItemUpdateMode.Edit);
    }, 0);
  }

  onRotationBlur(value: string) {
    this.delayService.execute(() => {
      this.rotation = (+value).toFixed(2);

      this.validateRotation();

      if (this.rotationFieldValidity === this.metaDataValidity.notValid) return;

      this.notifyCanvasWithUpdates(null, ItemUpdateMode.Edit);
    }, 0);
  }

  validateRotation() {
    const isValidRotation = +this.rotation >= 0 && +this.rotation <= 360;

    this.rotationFieldValidityError = !isValidRotation
      ? this.translateService.instant('admin-olc-templates.invalid-rotation-angle')
      : '';
    this.rotationFieldValidity = !isValidRotation ? this.metaDataValidity.notValid : this.metaDataValidity.valid;
  }

  notifyCanvasWithUpdates(updates: IItemUpdate | null, updateMode: ItemUpdateMode) {
    let values = {
      left: this.convertToPixel(this.left),
      top: this.convertToPixel(this.top),
      width: this.convertToPixel(this.width),
      height: this.convertToPixel(this.height),
      angle: +this.rotation,
    } as any;

    if (updates) values = updates;

    values.mode = updateMode;

    this.tedCanvasService.onUpdate.next(values);
  }

  validateShapeDimensionValue(value: string, dimensionToValidate: ShapeDimension): IShapeDimensionValidationResult {
    value = value.replace(/\s/g, '');

    if (this.isValidNumber(+value)) {
      value = this.convertMinusZeroToPlusZero(value);

      return this.getShapeDimensionValidationResult(
        value + this.templateEditorService.defaultUnit,
        dimensionToValidate
      );
    }

    const unit = LengthUnit[value.substring(value.length - 2, value.length).toUpperCase()];
    const number = this.getValueAsNumber(value);

    let error = '';

    if (!this.isValidNumber(number)) {
      error = this.translateService.instant('admin-olc-templates.invalid-number');
    }

    if (![LengthUnit.CM, LengthUnit.IN, LengthUnit.MM, LengthUnit.PT].includes(unit)) {
      error = (error ? error + ' / ' : '') + this.translateService.instant('admin-olc-templates.invalid-unit');
    }

    if (error) {
      return {
        updatedValue: this.convertMinusZeroToPlusZero(value),
        validity: MetaDataValidity.notValid,
        error: error,
      };
    }

    value = number + unit;

    if (unit != this.templateEditorService.defaultUnit) value = this.convertValueToDefaultUnit(value);

    return this.getShapeDimensionValidationResult(value, dimensionToValidate);
  }

  getShapeDimensionValidationResult(
    valueWithUnit: string,
    dimensionToValidate: ShapeDimension
  ): IShapeDimensionValidationResult {
    const updatedValue = this.getCorrectedValueWithinRange(valueWithUnit, dimensionToValidate);

    return {
      updatedValue,
      validity: MetaDataValidity.none,
      error: '',
    };
  }

  isValidNumber(value: number): boolean {
    return !isNaN(value);
  }

  getCorrectedValueWithinRange(valueWithUnit: string, dimensionToValidate: ShapeDimension): string {
    if (!this.itemLimits) return valueWithUnit;

    let maxValueInMM;
    let minValueInMM;

    if (dimensionToValidate === ShapeDimension.Left) {
      maxValueInMM = this.templateEditorService.convertPixelTo(this.itemLimits.maxLeft, LengthUnit.MM);
      minValueInMM = this.templateEditorService.convertPixelTo(this.itemLimits.minLeft, LengthUnit.MM);
    }

    if (dimensionToValidate === ShapeDimension.Top) {
      maxValueInMM = this.templateEditorService.convertPixelTo(this.itemLimits.maxTop, LengthUnit.MM);
      minValueInMM = this.templateEditorService.convertPixelTo(this.itemLimits.minTop, LengthUnit.MM);
    }

    if (dimensionToValidate === ShapeDimension.Height) {
      maxValueInMM = this.templateEditorService.convertPixelTo(this.itemLimits.maxHeight, LengthUnit.MM);
      minValueInMM = this.templateEditorService.convertPixelTo(this.itemLimits.minHeight, LengthUnit.MM);
    }

    if (dimensionToValidate === ShapeDimension.Width) {
      maxValueInMM = this.templateEditorService.convertPixelTo(this.itemLimits.maxWidth, LengthUnit.MM);
      minValueInMM = this.templateEditorService.convertPixelTo(this.itemLimits.minWidth, LengthUnit.MM);
    }

    const isMaxValid = this.isValidMaxValue(valueWithUnit, maxValueInMM + LengthUnit.MM);
    const isMinValid = this.isValidMinValue(valueWithUnit, minValueInMM + LengthUnit.MM);

    let updatedValue = '';

    if (isMaxValid && isMinValid) {
      updatedValue = valueWithUnit;
    } else if (!isMaxValid) {
      updatedValue = this.convertValueToDefaultUnit(maxValueInMM + LengthUnit.MM);
    } else if (!isMinValid) {
      updatedValue = this.convertValueToDefaultUnit(minValueInMM + LengthUnit.MM);
    }

    return updatedValue;
  }

  isValidMaxValue(valueWithUnit: string, maxValueInMM: string): boolean {
    const convertedValueWithUnit = this.convertValueToDefaultUnit(valueWithUnit);
    const convertedValue = this.getValueAsNumber(convertedValueWithUnit);

    const convertedMaxValueWithUnit = this.convertValueToDefaultUnit(maxValueInMM);
    const convertedMaxValue = this.getValueAsNumber(convertedMaxValueWithUnit);

    return convertedValue < convertedMaxValue;
  }

  isValidMinValue(valueWithUnit: string, minValueInMM: string): boolean {
    const convertedValueWithUnit = this.convertValueToDefaultUnit(valueWithUnit);
    const convertedValue = this.getValueAsNumber(convertedValueWithUnit);

    const convertedMinValueWithUnit = this.convertValueToDefaultUnit(minValueInMM);
    const convertedMinValue = this.getValueAsNumber(convertedMinValueWithUnit);

    return convertedValue > convertedMinValue;
  }

  convertValueToDefaultUnit(valueWithUnit: string) {
    return (
      this.templateEditorService.convertPixelTo(this.convertToPixel(valueWithUnit)) +
      this.templateEditorService.defaultUnit
    );
  }

  convertToPixel = (valueWithUnit: string): number => {
    const unit = LengthUnit[valueWithUnit.substring(valueWithUnit.length - 2, valueWithUnit.length).toUpperCase()];
    const value = this.getValueAsNumber(valueWithUnit);

    return +(value * this.templateEditorService.getScale(unit)).toFixed(2);
  };

  getValueAsNumber(valueWithUnit: string): number {
    const valueAsNumber = +valueWithUnit.substring(0, valueWithUnit.length - 2);
    return +this.convertMinusZeroToPlusZero(valueAsNumber + '');
  }

  convertMinusZeroToPlusZero(value: string) {
    return value && +value !== -0 ? value : '0';
  }

  ngOnDestroy(): void {
    this.subscriptions.forEach((s) => s.unsubscribe());
  }
}

interface IShapeDimensionValidationResult {
  updatedValue: string;
  validity: MetaDataValidity;
  error: string;
}
