import { Component, Input, OnInit } from '@angular/core';
import { FieldDefinition } from '../../../../../../../../Bamba.Shared/src/models/field-definition';
import { TemplateVersion } from '../../models/template';
import { MetaDataType } from '../../../../../../../../Bamba.Shared/src/models/metadata-definition';
import { TranslateService } from '@ngx-translate/core';

@Component({
  selector: 'app-version-properties-approval',
  templateUrl: './version-properties-approval.component.html',
  styleUrls: ['./version-properties-approval.component.scss'],
})
export class VersionPropertiesApprovalComponent implements OnInit {
  @Input() version: TemplateVersion;

  fieldSubmitter: FieldDefinition;
  fieldReviewer: FieldDefinition;
  fieldComment: FieldDefinition;

  constructor(private translate: TranslateService) {}

  ngOnInit() {
    this.createFields();
  }

  private createFields() {
    this.fieldSubmitter = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('admin-olc-templates.approval-submitter-label'),
      required: false,
    });

    this.fieldReviewer = new FieldDefinition({
      type: MetaDataType.Text,
      label: this.translate.instant('admin-olc-templates.approval-reviewer-label'),
      required: false,
    });

    this.fieldComment = new FieldDefinition({
      type: MetaDataType.LargeText,
      label: this.translate.instant('admin-olc-templates.version-comment-label'),
      required: false,
    });
  }
}
